def _get_ai_safe_settings_snapshot(user):
    """Return current values for AI-readable settings only; never include credentials or admin settings."""
    values = {field: getattr(user, field, None) for field in AI_SAFE_EDITABLE_FIELDS}
    system_prompt = getattr(user, 'system_prompt', None) or ''
    if getattr(user, 'enable_e2ee', False) and system_prompt:
        system_prompt = decrypt_val(system_prompt)
    values.update({
        'system_prompt': system_prompt,
        'system_prompt_enabled': user.system_prompt_enabled if user.system_prompt_enabled is not None else True,
        'apply_global_system_prompt': user.apply_global_system_prompt if user.apply_global_system_prompt is not None else True,
        'apply_auto_system_prompt_notices': get_user_auto_system_prompt_notices_enabled(user),
        'auto_system_prompt_notices_config': get_user_auto_system_prompt_notices_config(user),
        'mic_transcribe_mode': _normalize_mic_transcribe_mode(getattr(user, 'mic_transcribe_mode', None)),
        'stt_model': getattr(user, 'stt_model', None) or 'gpt-4o-mini-transcribe',
        'llm_transcribe_prompt': _normalize_llm_transcribe_prompt(getattr(user, 'llm_transcribe_prompt', None)) or '',
        'temp_chat_timeout_seconds': _get_user_temp_chat_timeout_seconds(user),
        'default_model': getattr(user, 'default_model', None) or 'gemini-3.6-flash',
        'default_vision_model': getattr(user, 'default_vision_model', None) or 'gemini-3-flash-preview',
        'default_thinking_level': getattr(user, 'default_thinking_level', None) or 'high',
        'default_thinking_budget': user.default_thinking_budget if user.default_thinking_budget is not None else 4096,
        'default_reasoning_effort': getattr(user, 'default_reasoning_effort', None) or 'medium',
        'default_safety_setting': getattr(user, 'default_safety_setting', None) or 'default',
        'rich_paste_prompt_default': getattr(user, 'rich_paste_prompt_default', None) or '',
        'rich_paste_prompt_use_custom_default': bool(getattr(user, 'rich_paste_prompt_use_custom_default', False)),
        'theme_color': getattr(user, 'theme_color', None) or '',
        'liquid_glass_enabled': bool(getattr(user, 'liquid_glass_enabled', False)),
        'compact_prompt_mode': bool(getattr(user, 'compact_prompt_mode', False)),
        'minimal_prompt_mode': bool(getattr(user, 'minimal_prompt_mode', False)),
        'voice_studio_ui': bool(getattr(user, 'voice_studio_ui', True)),
        'enable_latency_metrics': bool(getattr(user, 'enable_latency_metrics', False)),
        'enable_client_debug_log': bool(getattr(user, 'enable_client_debug_log', False)),
        'bot_detection_enabled': user.bot_detection_enabled if user.bot_detection_enabled is not None else True,
        'skip_2fa_on_google_login': bool(getattr(user, 'skip_2fa_on_google_login', False)),
        'default_2fa_method': getattr(user, 'default_2fa_method', None) or 'totp',
    })
    return {field: values.get(field) for field in sorted(AI_SAFE_EDITABLE_FIELDS)}


def _summarize_ai_settings_for_model(values):
    """Keep private/long prompt bodies out of the intent-classification context."""
    summarized = dict(values or {})
    for field in ('system_prompt', 'llm_transcribe_prompt', 'rich_paste_prompt_default'):
        summarized[field] = '設定済み' if summarized.get(field) else '未設定'
    if summarized.get('auto_system_prompt_notices_config'):
        summarized['auto_system_prompt_notices_config'] = '設定済み'
    return summarized

def _apply_ai_settings_update(current_user, delta):
    """
    Apply a delta dict (from AI tool call) to current_user, but ONLY for AI_SAFE_EDITABLE_FIELDS.
    Never touches secrets, admin-only, or high-risk fields. Mirrors the assignment logic
    from handle_settings POST for consistency ("ロジックは同じ").
    Does NOT commit. Caller must safe_db_commit() after.
    Returns dict of actually applied field->new_value (for response summary).
    """
    if not delta or not isinstance(delta, dict):
        return {}
    applied = {}
    for key, val in delta.items():
        if key not in AI_SAFE_EDITABLE_FIELDS:
            continue  # silently ignore unknown or disallowed
        if key in AI_NEVER_EDITABLE_FIELDS:
            continue
        try:
            if key == 'system_prompt':
                if current_user.enable_e2ee:
                    current_user.system_prompt = encrypt_val(val or "")
                else:
                    current_user.system_prompt = val or ""
                applied[key] = "(更新)"
            elif key == 'system_prompt_enabled':
                current_user.system_prompt_enabled = bool(val)
                applied[key] = current_user.system_prompt_enabled
            elif key == 'apply_global_system_prompt':
                current_user.apply_global_system_prompt = bool(val)
                applied[key] = current_user.apply_global_system_prompt
            elif key == 'apply_auto_system_prompt_notices':
                current_user.apply_auto_system_prompt_notices = bool(val)
                applied[key] = current_user.apply_auto_system_prompt_notices
            elif key == 'auto_system_prompt_notices_config':
                set_user_auto_system_prompt_notices_config(current_user, val)
                applied[key] = "(更新)"
            elif key in ('mic_transcribe_mode',):
                current_user.mic_transcribe_mode = _normalize_mic_transcribe_mode(val)
                applied[key] = current_user.mic_transcribe_mode
            elif key == 'stt_model':
                _raw = str(val).strip() if val else ''
                if _raw and _raw not in VALID_STT_MODELS:
                    log_force(f"AI-SETTINGS-INVALID-STT: user={current_user.id} rejected={_raw}")
                    continue
                current_user.stt_model = _raw if _raw else "gpt-4o-mini-transcribe"
                applied[key] = current_user.stt_model
            elif key == 'llm_transcribe_prompt':
                current_user.llm_transcribe_prompt = _normalize_llm_transcribe_prompt(val)
                applied[key] = "(更新)"
            elif key == 'enter_to_send':
                current_user.enter_to_send = bool(val)
                applied[key] = current_user.enter_to_send
            elif key == 'use_sw_cache':
                current_user.use_sw_cache = bool(val)
                applied[key] = current_user.use_sw_cache
            elif key == 'compact_prompt_mode':
                current_user.compact_prompt_mode = bool(val)
                if current_user.compact_prompt_mode:
                    current_user.minimal_prompt_mode = False
                applied[key] = current_user.compact_prompt_mode
            elif key == 'minimal_prompt_mode':
                current_user.minimal_prompt_mode = bool(val)
                if current_user.minimal_prompt_mode:
                    current_user.compact_prompt_mode = False
                applied[key] = current_user.minimal_prompt_mode
            elif key == 'theme_color':
                current_user.theme_color = normalize_theme_color(val)
                applied[key] = current_user.theme_color
            elif key == 'liquid_glass_enabled':
                current_user.liquid_glass_enabled = bool(val)
                applied[key] = current_user.liquid_glass_enabled
            elif key == 'auto_search_on_links':
                current_user.auto_search_on_links = bool(val)
                applied[key] = current_user.auto_search_on_links
            elif key == 'use_last_chat_settings':
                current_user.use_last_chat_settings = bool(val)
                applied[key] = current_user.use_last_chat_settings
            elif key == 'voice_studio_ui':
                current_user.voice_studio_ui = bool(val)
                applied[key] = current_user.voice_studio_ui
            elif key == 'temp_chat_timeout_seconds':
                current_user.temp_chat_timeout_seconds = _normalize_temp_chat_timeout_seconds(val)
                applied[key] = current_user.temp_chat_timeout_seconds
            elif key == 'default_model':
                _raw = str(val).strip() if val else ''
                if _raw and _raw not in ALL_VALID_MODEL_IDS:
                    log_force(f"AI-SETTINGS-INVALID-MODEL: user={current_user.id} rejected={_raw}")
                    continue
                current_user.default_model = _raw if _raw else current_user.default_model
                applied[key] = current_user.default_model
            elif key == 'default_enable_search':
                current_user.default_enable_search = bool(val)
                applied[key] = current_user.default_enable_search
            elif key == 'default_enable_url_context':
                current_user.default_enable_url_context = bool(val)
                applied[key] = current_user.default_enable_url_context
            elif key == 'default_enable_maps':
                current_user.default_enable_maps = bool(val)
                applied[key] = current_user.default_enable_maps
            elif key == 'default_enable_python':
                current_user.default_enable_python = bool(val)
                applied[key] = current_user.default_enable_python
            elif key == 'default_enable_thinking':
                current_user.default_enable_thinking = bool(val)
                applied[key] = current_user.default_enable_thinking
            elif key == 'default_thinking_level':
                _raw = str(val).strip() if val else ''
                if _raw in VALID_THINKING_LEVELS:
                    current_user.default_thinking_level = _raw
                else:
                    current_user.default_thinking_level = "high"
                applied[key] = current_user.default_thinking_level
            elif key == 'default_thinking_budget':
                try:
                    current_user.default_thinking_budget = int(val)
                    applied[key] = current_user.default_thinking_budget
                except Exception:
                    pass
            elif key == 'default_reasoning_effort':
                _raw = str(val).strip() if val else ''
                if _raw in VALID_REASONING_EFFORTS:
                    current_user.default_reasoning_effort = _raw
                else:
                    current_user.default_reasoning_effort = "medium"
                applied[key] = current_user.default_reasoning_effort
            elif key == 'default_enable_system_prompt':
                current_user.default_enable_system_prompt = bool(val)
                applied[key] = current_user.default_enable_system_prompt
            elif key == 'default_safety_setting':
                _raw = str(val).strip() if val else ''
                if _raw in VALID_SAFETY_SETTINGS:
                    current_user.default_safety_setting = _raw
                else:
                    current_user.default_safety_setting = "default"
                applied[key] = current_user.default_safety_setting
            elif key == 'rich_paste_prompt_default':
                current_user.rich_paste_prompt_default = str(val or "")
                applied[key] = current_user.rich_paste_prompt_default
            elif key == 'rich_paste_prompt_use_custom_default':
                current_user.rich_paste_prompt_use_custom_default = bool(val)
                applied[key] = current_user.rich_paste_prompt_use_custom_default
            elif key == 'enable_latency_metrics':
                current_user.enable_latency_metrics = bool(val)
                applied[key] = current_user.enable_latency_metrics
            elif key == 'enable_client_debug_log':
                current_user.enable_client_debug_log = bool(val)
                applied[key] = current_user.enable_client_debug_log
                log_force(f"SETTINGS-AI-UPDATE: user={current_user.id} enable_client_debug_log={val}")
            elif key == 'bot_detection_enabled':
                if val is not None:
                    current_user.bot_detection_enabled = bool(val)
                    applied[key] = current_user.bot_detection_enabled
            elif key == 'skip_2fa_on_google_login':
                current_user.skip_2fa_on_google_login = bool(val)
                applied[key] = current_user.skip_2fa_on_google_login
            elif key == 'default_2fa_method':
                current_user.default_2fa_method = str(val) if val in ('totp', 'webauthn') else 'totp'
                applied[key] = current_user.default_2fa_method
            # Note: auto_system_prompt_notices_config handled above; complex ones can be extended later
        except Exception as e:
            log_force(f"AI-SETTINGS-APPLY-ERR key={key} err={e}")
    return applied

def _normalize_mic_transcribe_mode(value):
    v = str(value or "").strip().lower()
    return v if v in MIC_TRANSCRIBE_MODES else "stt_api"

def _normalize_llm_transcribe_prompt(raw_text):
    if raw_text is None:
        return None
    text = str(raw_text).strip()
    if not text:
        return None
    if len(text) > LLM_TRANSCRIBE_PROMPT_MAX_CHARS:
        text = text[:LLM_TRANSCRIBE_PROMPT_MAX_CHARS]
    return text

def get_user_llm_transcribe_prompt(user):
    try:
        raw = getattr(user, "llm_transcribe_prompt", None)
    except Exception:
        raw = None
    return _normalize_llm_transcribe_prompt(raw) or DEFAULT_LLM_TRANSCRIBE_PROMPT

def _analyze_image_with_vision_model(model_id, img_data, img_mime, prompt, api_keys):
    try:
        model_l = model_id.lower()
        img_b64 = base64.b64encode(img_data).decode("utf-8")
        data_uri = f"data:{img_mime};base64,{img_b64}"

        # --- Gemini ---
        if model_l.startswith("gemini-"):
            g_key = api_keys.get("gemini")
            if not g_key:
                return None
            try:
                import google.genai.types as types
                g_client = _get_gemini_client(api_key=g_key)
                if not g_client:
                    return None
                resp = g_client.models.generate_content(
                    model=model_id,
                    contents=[prompt, types.Part.from_bytes(data=img_data, mime_type=img_mime)]
                )
                return resp.text if hasattr(resp, "text") else None
            except Exception:
                pass
            return None

        # --- OpenAI / xAI (Grok) ---
        if model_l.startswith(("gpt-", "o1-", "o3-", "grok-")):
            base_url = None
            oa_key = None
            if model_l.startswith("grok-"):
                oa_key = api_keys.get("xai")
                base_url = f"https://{_XAI_API_HOST}/v1"
            else:
                oa_key = api_keys.get("openai")
            if not oa_key:
                return None
            oa_client = _get_openai_client(oa_key, base_url=base_url)
            if not oa_client:
                return None
            resp = oa_client.chat.completions.create(
                model=model_id,
                messages=[{"role": "user", "content": [{"type": "text", "text": prompt}, {"type": "image_url", "image_url": {"url": data_uri}}]}],
                max_tokens=4096,
            )
            return getattr(resp.choices[0].message, "content", None) or ""

        # --- Anthropic Claude ---
        if model_l.startswith("claude-"):
            c_key = api_keys.get("anthropic")
            if not c_key:
                return None
            try:
                from anthropic import Anthropic
            except ImportError:
                return None
            c_client = Anthropic(api_key=c_key)
            resp = c_client.messages.create(
                model=model_id,
                max_tokens=4096,
                messages=[{"role": "user", "content": [{"type": "text", "text": prompt}, {"type": "image", "source": {"type": "base64", "media_type": img_mime, "data": img_b64}}]}],
            )
            text_parts = []
            for block in resp.content:
                if block.type == "text":
                    text_parts.append(block.text)
            return "".join(text_parts) or None

        return None
    except Exception as e:
        log_force(f"IMAGE_ANALYSIS_ERROR: model={model_id} error={e}")
        return None

def _extract_openai_response_text(resp):
    try:
        if isinstance(resp, dict):
            raw = resp.get("output_text")
            if isinstance(raw, str) and raw.strip():
                return raw.strip()
        else:
            raw = getattr(resp, "output_text", None)
            if isinstance(raw, str) and raw.strip():
                return raw.strip()
        output = resp.get("output") if isinstance(resp, dict) else getattr(resp, "output", None)
        texts = []
        for item in output or []:
            content = item.get("content") if isinstance(item, dict) else getattr(item, "content", None)
            for part in content or []:
                if isinstance(part, dict):
                    p_type = part.get("type")
                    if p_type in ("output_text", "text") and part.get("text"):
                        texts.append(str(part.get("text")))
                else:
                    p_type = getattr(part, "type", None)
                    p_text = getattr(part, "text", None)
                    if p_type in ("output_text", "text") and p_text:
                        texts.append(str(p_text))
        if texts:
            return "\n".join(texts).strip()
    except Exception:
        return ""
    return ""

def _transcribe_audio_with_llm(audio_content, fname, llm_model_key, user):
    no_speech_token = "[[NO_SPEECH]]"
    base_transcription_prompt = get_user_llm_transcribe_prompt(user)
    transcription_prompt = (
        f"{base_transcription_prompt}\n"
        f"聞き取れない、無音、音声が極端に小さい場合は推測せず {no_speech_token} のみを返してください。"
    )
    model_key = (llm_model_key or "").strip()
    model_key_l = model_key.lower()
    is_gem = is_gemini_model_key(model_key_l)
    is_deepseek = is_deepseek_model_key(model_key_l)
    is_grok = ("grok" in model_key_l) and ("gpt" not in model_key_l)
    if is_grok:
        raise ValueError("現在の xAI/Grok モデルのLLM文字起こしは未対応です。OpenAI/Gemini対応モデルに切り替えるか、STT APIを使用してください。")
    if is_deepseek:
        raise ValueError("DeepSeek モデルのLLM文字起こしは未対応です。OpenAI/Gemini対応モデルに切り替えるか、STT APIを使用してください。")
    if not model_key:
        model_key = "gpt-4o-mini"
        model_key_l = model_key.lower()

    src_ext = os.path.splitext(fname or "")[1].lower() or ".webm"
    if src_ext not in (".webm", ".wav", ".mp3", ".m4a", ".ogg", ".flac", ".opus"):
        src_ext = ".webm"
    try:
        target_rate = 16000 if is_gem else 24000
        pcm = _convert_audio_to_pcm(audio_content, src_suffix=src_ext, rate=target_rate)
        wav_bytes = _pcm_to_wav_bytes(pcm, rate=target_rate)
    except Exception as e:
        raise RuntimeError(f"Audio conversion failed (ffmpeg): {e}") from e

    metrics = _pcm_audio_metrics_mono_s16le(pcm, rate=target_rate)
    # Guard against near-silent capture in LLM mode to prevent hallucinated transcripts.
    # Relaxed thresholds to allow quieter valid inputs.
    if metrics["duration_sec"] >= 0.35 and metrics["rms"] < 30 and metrics["peak"] < 250:
        logger.warning(
            "LLM transcription rejected due to near-silent audio "
            f"(model={model_key}, dur={metrics['duration_sec']:.2f}s, rms={metrics['rms']}, peak={metrics['peak']})"
        )
        raise ValueError("録音音声が極端に小さい/無音です。マイク入力（ノイズ抑制設定含む）を確認して、もう一度お試しください。")

    if is_gem:
        gemini_runtime = _resolve_gemini_runtime(user)
        g_key = _get_model_specific_api_key(user, model_key) or gemini_runtime.get("api_key")
        backend = gemini_runtime.get("backend")
        if backend == "vertex_ai":
            if not gemini_runtime.get("vertex_project"):
                raise ValueError("Vertex AI Project ID が未設定です。Gemini設定を確認してください。")
        elif not g_key:
            raise ValueError("Gemini API Key not configured")
        g_client = _get_gemini_client(
            api_key=g_key,
            backend=backend,
            vertex_project=gemini_runtime.get("vertex_project"),
            vertex_location=gemini_runtime.get("vertex_location"),
            vertex_credentials_json=gemini_runtime.get("vertex_credentials_json"),
        )
        if not g_client:
            raise RuntimeError("Gemini client initialization failed")
        resp = g_client.models.generate_content(
            model=model_key,
            contents=[
                types.Part(text=transcription_prompt),
                types.Part.from_bytes(data=wav_bytes, mime_type="audio/wav"),
            ],
        )
        text_out = (getattr(resp, "text", None) or "").strip()
        if _llm_transcript_is_no_speech(text_out, no_speech_token):
            raise ValueError("音声を検出できませんでした。マイク入力（ノイズ抑制設定含む）を確認して、もう一度お試しください。")
        return text_out

    o_key = _get_model_specific_api_key(user, model_key) or decrypt_val(user.openai_api_key)
    if not o_key and _admin_env_fallback_enabled(user):
        o_key = os.getenv('OPENAI_API_KEY')
    if not o_key:
        raise ValueError("OpenAI API Key not configured")
    client = _get_openai_client(o_key, base_url=None)
    audio_b64 = base64.b64encode(wav_bytes).decode("ascii")
    resp = client.responses.create(
        model=model_key,
        input=[
            {
                "role": "user",
                "content": [
                    {"type": "input_text", "text": transcription_prompt},
                    {"type": "input_audio", "input_audio": {"data": audio_b64, "format": "wav"}}
                ]
            }
        ]
    )
    text_out = _extract_openai_response_text(resp).strip()
    if _llm_transcript_is_no_speech(text_out, no_speech_token):
        raise ValueError("音声を検出できませんでした。マイク入力（ノイズ抑制設定含む）を確認して、もう一度お試しください。")
    return text_out

async def _openai_sts_realtime(pcm_bytes, api_key, model_key, voice="alloy", speed=None, rate=24000):
    # OpenAI Realtime currently supports 24kHz PCM audio for output; keep session aligned.
    rate = 24000
    if model_key == "gpt-realtime-translate":
        url = f"wss://api.openai.com/v1/realtime/translations?model={model_key}"
    elif model_key == "gpt-realtime-whisper":
        url = f"wss://api.openai.com/v1/realtime/transcription_sessions?model={model_key}"
    else:
        url = f"wss://api.openai.com/v1/realtime?model={model_key}"
    
    headers = {
        "Authorization": f"Bearer {api_key}",
        "OpenAI-Beta": "realtime=v1",
    }
    audio_out = bytearray()
    transcript_out = ""
    async with websockets.connect(url, additional_headers=headers, max_size=None) as ws:
        session_update = {
            "type": "session.update",
            "session": {
                "type": "realtime",
                "model": model_key,
                "output_modalities": ["audio"],
                "voice": voice,
                "audio": {
                    "input": {
                        "format": {"type": "audio/pcm", "rate": rate},
                        "turn_detection": None
                    },
                    "output": {
                        "format": {"type": "audio/pcm", "rate": rate}
                    }
                }
            }
        }
        if speed is not None:
            session_update["session"]["speed"] = speed
        await ws.send(json.dumps(session_update))
        await ws.send(json.dumps({"type": "input_audio_buffer.clear"}))
        for chunk in _chunk_bytes(pcm_bytes):
            await ws.send(json.dumps({
                "type": "input_audio_buffer.append",
                "audio": base64.b64encode(chunk).decode('utf-8')
            }))
        await ws.send(json.dumps({"type": "input_audio_buffer.commit"}))
        resp_cfg = {"voice": voice}
        if speed is not None:
            resp_cfg["speed"] = speed
        await ws.send(json.dumps({"type": "response.create", "response": resp_cfg}))
        while True:
            msg = json.loads(await ws.recv())
            mtype = msg.get("type")
            if mtype == "error":
                logger.error(f"OpenAI STS error event: {msg}")
            elif mtype and mtype.startswith("response."):
                logger.debug(f"OpenAI STS event: {mtype}")
            if mtype in ("response.output_audio.delta", "response.audio.delta"):
                delta = msg.get("delta")
                if delta:
                    audio_out += base64.b64decode(delta)
            elif mtype in ("response.output_audio", "response.audio"):
                delta = msg.get("audio") or msg.get("data")
                if delta:
                    audio_out += base64.b64decode(delta)
            elif mtype == "response.output_audio_transcript.delta":
                delta = msg.get("delta")
                if delta:
                    transcript_out += delta
            elif mtype in ("response.output_audio.done", "response.done"):
                break
    return bytes(audio_out), transcript_out

async def _openai_realtime_transcribe(pcm_bytes, api_key, model_key, rate=24000):
    """Transcribe one committed PCM turn through an OpenAI Realtime transcription session."""
    if model_key not in {"gpt-transcribe", "gpt-live-transcribe"}:
        raise ValueError("Unsupported OpenAI transcription model")

    rate = 24000
    # Transcription models are selected inside session.audio.input.transcription;
    # they are not Realtime conversation models for the WebSocket query string.
    url = "wss://api.openai.com/v1/realtime?intent=transcription"
    headers = {"Authorization": f"Bearer {api_key}"}
    transcript_deltas = []

    async with websockets.connect(url, additional_headers=headers, max_size=None) as ws:
        await ws.send(json.dumps({
            "type": "session.update",
            "session": {
                "type": "transcription",
                "audio": {
                    "input": {
                        "format": {"type": "audio/pcm", "rate": rate},
                        "transcription": {"model": model_key},
                        "turn_detection": None,
                    }
                },
            },
        }))
        await ws.send(json.dumps({"type": "input_audio_buffer.clear"}))
        for chunk in _chunk_bytes(pcm_bytes):
            await ws.send(json.dumps({
                "type": "input_audio_buffer.append",
                "audio": base64.b64encode(chunk).decode("ascii"),
            }))
        await ws.send(json.dumps({"type": "input_audio_buffer.commit"}))

        while True:
            raw = await asyncio.wait_for(ws.recv(), timeout=60)
            event = json.loads(raw)
            event_type = event.get("type")
            if event_type == "conversation.item.input_audio_transcription.delta":
                delta = event.get("delta")
                if delta:
                    transcript_deltas.append(str(delta))
            elif event_type == "conversation.item.input_audio_transcription.completed":
                completed = str(event.get("transcript") or "").strip()
                return completed or "".join(transcript_deltas).strip()
            elif event_type == "conversation.item.input_audio_transcription.failed":
                error = event.get("error") or {}
                message = error.get("message") if isinstance(error, dict) else str(error)
                raise RuntimeError(message or "Realtime transcription failed")
            elif event_type == "error":
                error = event.get("error") or {}
                message = error.get("message") if isinstance(error, dict) else str(error)
                raise RuntimeError(message or "OpenAI Realtime API error")

async def _xai_sts_realtime(pcm_bytes, api_key, model_key="grok-voice-agent", voice="Ara", rate_in=24000, rate_out=24000):
    model_key = XAI_STS_MODEL_ALIASES.get(model_key, model_key)
    url = f"wss://{_XAI_API_HOST}/v1/realtime?model={model_key}"
    headers = {"Authorization": f"Bearer {api_key}"}
    audio_out = bytearray()
    transcript_out = ""
    async with websockets.connect(url, ssl=True, additional_headers=headers, max_size=None) as ws:
        session_update = {
            "type": "session.update",
            "session": {
                "voice": voice,
                "turn_detection": {"type": None},
                "audio": {
                    "input": {"format": {"type": "audio/pcm", "rate": rate_in}},
                    "output": {"format": {"type": "audio/pcm", "rate": rate_out}}
                }
            }
        }
        await ws.send(json.dumps(session_update))
        for chunk in _chunk_bytes(pcm_bytes):
            await ws.send(json.dumps({
                "type": "input_audio_buffer.append",
                "audio": base64.b64encode(chunk).decode('utf-8')
            }))
        await ws.send(json.dumps({"type": "input_audio_buffer.commit"}))

        # Wait for commit confirmation when using client-side VAD
        try:
            while True:
                msg = json.loads(await asyncio.wait_for(ws.recv(), timeout=2.0))
                if msg.get("type") == "input_audio_buffer.committed":
                    break
        except Exception:
            pass

        await ws.send(json.dumps({"type": "response.create", "response": {"modalities": ["audio", "text"]}}))
        while True:
            msg = json.loads(await ws.recv())
            mtype = msg.get("type")
            if mtype == "error":
                logger.error(f"xAI STS error event: {msg}")
            elif mtype and mtype.startswith("response."):
                logger.debug(f"xAI STS event: {mtype}")
            if mtype == "response.output_audio.delta":
                delta = msg.get("delta")
                if delta:
                    audio_out += base64.b64decode(delta)
            elif mtype == "response.output_audio":
                delta = msg.get("audio")
                if delta:
                    audio_out += base64.b64decode(delta)
            elif mtype == "response.output_audio_transcript.delta":
                delta = msg.get("delta")
                if delta:
                    transcript_out += delta
            elif mtype in ("response.output_audio.done", "response.done"):
                break
    return bytes(audio_out), transcript_out

# =============================================================================
# Lyria RealTime (lyria-realtime-exp) real-time music session manager
# -----------------------------------------------------------------------------
# Lyria RealTime is a WebSocket-based streaming music generation model. The
# browser cannot reach Google's BidiGenerateMusic WebSocket directly without
# exposing the user's raw Gemini API key, so the server keeps a persistent
# session (thread + asyncio loop) per active session, streams audio deltas to
# the client over SSE, and accepts steering commands over HTTP.
# =============================================================================
LYRIA_REALTIME_MODEL = "lyria-realtime-exp"
LYRIA_SESSIONS = {}
LYRIA_SESSIONS_LOCK = threading.Lock()
LYRIA_MAX_SESSION_SECONDS = 15 * 60  # auto-stop to bound cost
LYRIA_MAX_AUDIO_BYTES = 512 * 1024 * 1024  # cap accumulated PCM
LYRIA_PROMPT_MAX_CHARS = 4000
LYRIA_SESSION_TTL_SECONDS = 30 * 60  # closed sessions are purged after this

LYRIA_SCALES = {
    "C_MAJOR_A_MINOR": "C major / A minor",
    "D_FLAT_MAJOR_B_FLAT_MINOR": "D\u266d major / B\u266d minor",
    "D_MAJOR_B_MINOR": "D major / B minor",
    "E_FLAT_MAJOR_C_MINOR": "E\u266d major / C minor",
    "E_MAJOR_D_FLAT_MINOR": "E major / C\u266f/D\u266d minor",
    "F_MAJOR_D_MINOR": "F major / D minor",
    "G_FLAT_MAJOR_E_FLAT_MINOR": "G\u266d major / E\u266d minor",
    "G_MAJOR_E_MINOR": "G major / E minor",
    "A_FLAT_MAJOR_F_MINOR": "A\u266d major / F minor",
    "A_MAJOR_G_FLAT_MINOR": "A major / F\u266f/G\u266d minor",
    "B_FLAT_MAJOR_G_MINOR": "B\u266d major / G minor",
    "B_MAJOR_A_FLAT_MINOR": "B major / G\u266f/A\u266d minor",
}


class LyriaSession:
    """One persistent Lyria RealTime streaming session for a single user."""

    def __init__(self, session_id, user_id, api_key, prompts, config):
        self.session_id = session_id
        self.user_id = user_id
        self.api_key = api_key
        self.prompts = prompts          # [{"text", "weight"}]
        self.config = config            # normalized musicGenerationConfig (camelCase)
        self.loop = None                # asyncio event loop of the worker thread
        self.ws = None                  # websocket to Google (owned by worker thread)
        self.audio_buffer = bytearray()  # accumulated raw PCM (48kHz stereo s16le)
        self.audio_lock = threading.Lock()
        self.pending = []                # base64 deltas not yet consumed by the SSE stream
        self.pending_cond = threading.Condition()
        self.cmd_queue = _queue.Queue()  # steering commands from HTTP handlers
        self.stop_event = threading.Event()
        self.status = "connecting"       # connecting|streaming|paused|stopped|error|closed
        self.error = None
        self.filtered_prompt = None
        self.started_at = time.time()
        self.thread = None


def _normalize_lyria_config(raw):
    """Validate / normalize a Lyria RealTime music generation config (camelCase output)."""
    raw = raw or {}
    # The client must know the output format. Lyria RealTime emits raw 16-bit
    # PCM at 48kHz stereo; make it explicit so updates don't reset it.
    cfg = {
        "audioFormat": "pcm16",
        "sampleRateHz": 48000,
    }

    def clamp(name, lo, hi, cast=float):
        val = raw.get(name)
        if val is None or val == "":
            return None
        try:
            value = cast(val)
        except (TypeError, ValueError):
            return None
        return max(lo, min(hi, value))

    bpm = clamp("bpm", 60, 200, int)
    if bpm is not None:
        cfg["bpm"] = bpm
    guidance = clamp("guidance", 0.0, 6.0)
    if guidance is not None:
        cfg["guidance"] = guidance
    density = clamp("density", 0.0, 1.0)
    if density is not None:
        cfg["density"] = density
    brightness = clamp("brightness", 0.0, 1.0)
    if brightness is not None:
        cfg["brightness"] = brightness
    temperature = clamp("temperature", 0.0, 3.0)
    if temperature is not None:
        cfg["temperature"] = temperature
    top_k = clamp("top_k", 1, 1000, int)
    if top_k is not None:
        cfg["topK"] = top_k
    seed = raw.get("seed")
    if seed is not None and str(seed).strip():
        try:
            seed_val = int(str(seed).strip())
            if 0 <= seed_val <= 2147483647:
                cfg["seed"] = seed_val
        except (TypeError, ValueError):
            pass
    scale = str(raw.get("scale") or "").strip()
    if scale and scale != "SCALE_UNSPECIFIED" and scale in LYRIA_SCALES:
        cfg["scale"] = scale
    mode = str(raw.get("music_generation_mode") or "QUALITY").strip().upper()
    if mode not in ("QUALITY", "DIVERSITY", "VOCALIZATION"):
        mode = "QUALITY"
    cfg["musicGenerationMode"] = mode
    for src, dst in (
        ("mute_bass", "muteBass"),
        ("mute_drums", "muteDrums"),
        ("only_bass_and_drums", "onlyBassAndDrums"),
    ):
        val = raw.get(src)
        if val is not None:
            cfg[dst] = bool(val)
    return cfg


def _normalize_lyria_prompts(raw_list):
    prompts = []
    for item in raw_list or []:
        if not isinstance(item, dict):
            continue
        text = str(item.get("text") or "").strip()
        if not text:
            continue
        try:
            weight = float(item.get("weight", 1.0))
        except (TypeError, ValueError):
            weight = 1.0
        if weight <= 0 or weight > 100:
            weight = 1.0
        prompts.append({"text": text[:LYRIA_PROMPT_MAX_CHARS], "weight": weight})
    return prompts


def _lyria_pcm_to_wav_stereo(pcm_bytes, rate=48000):
    """Wrap raw 16-bit stereo PCM (interleaved L/R) into a WAV container."""
    buf = BytesIO()
    with wave.open(buf, "wb") as wf:
        wf.setnchannels(2)
        wf.setsampwidth(2)
        wf.setframerate(rate)
        wf.writeframes(pcm_bytes)
    return buf.getvalue()


async def _lyria_send_control(session, action):
    if session.ws:
        await session.ws.send(json.dumps({"playbackControl": action}))


async def _lyria_receive_loop(session, ws):
    try:
        while True:
            raw = await ws.recv()
            if isinstance(raw, bytes):
                raw = raw.decode("utf-8", "replace")
            msg = json.loads(raw)
            server_content = msg.get("serverContent")
            if server_content and server_content.get("audioChunks"):
                for chunk in server_content["audioChunks"]:
                    data = chunk.get("data")
                    if not data:
                        continue
                    try:
                        binary = base64.b64decode(data)
                    except Exception:
                        continue
                    with session.audio_lock:
                        if len(session.audio_buffer) + len(binary) > LYRIA_MAX_AUDIO_BYTES:
                            continue
                        session.audio_buffer += binary
                    with session.pending_cond:
                        session.pending.append(data)
                        session.pending_cond.notify_all()
            if msg.get("filteredPrompt"):
                session.filtered_prompt = msg.get("filteredPrompt")
            if msg.get("error"):
                raise RuntimeError(str(msg.get("error")))
    except asyncio.CancelledError:
        raise
    except Exception as exc:
        session.error = str(exc)
        session.status = "error"
        session.stop_event.set()
        with session.pending_cond:
            session.pending_cond.notify_all()


async def _lyria_handle_command(session, ws, cmd):
    ctype = cmd.get("type")
    if ctype == "prompts":
        prompts = _normalize_lyria_prompts(cmd.get("weighted_prompts"))
        if not prompts:
            return
        await ws.send(json.dumps({"clientContent": {"weightedPrompts": prompts}}))
        session.prompts = prompts
    elif ctype == "config":
        cfg = _normalize_lyria_config(cmd.get("config"))
        await ws.send(json.dumps({"musicGenerationConfig": cfg}))
        session.config = cfg
        if cmd.get("reset_context"):
            await _lyria_send_control(session, "RESET_CONTEXT")
    elif ctype == "control":
        action = str(cmd.get("action") or "").upper()
        if action not in ("PLAY", "PAUSE", "STOP", "RESET_CONTEXT"):
            return
        await _lyria_send_control(session, action)
        if action == "PAUSE":
            session.status = "paused"
        elif action == "PLAY":
            session.status = "streaming"
        elif action == "STOP":
            session.status = "stopped"


async def _lyria_worker_async(session):
    ws_url = (
        "wss://generativelanguage.googleapis.com/ws/"
        "google.ai.generativelanguage.v1beta.GenerativeService.BidiGenerateMusic"
        f"?key={quote(session.api_key, safe='')}"
    )
    async with websockets.connect(ws_url, max_size=None) as ws:
        session.ws = ws
        await ws.send(json.dumps({"setup": {"model": f"models/{LYRIA_REALTIME_MODEL}"}}))
        # Wait for setup confirmation before sending any other message.
        while True:
            raw = await asyncio.wait_for(ws.recv(), timeout=30)
            if isinstance(raw, bytes):
                raw = raw.decode("utf-8", "replace")
            msg = json.loads(raw)
            if msg.get("setupComplete") is not None:
                break
            if msg.get("error"):
                raise RuntimeError(str(msg.get("error")))

        await ws.send(json.dumps({"clientContent": {"weightedPrompts": session.prompts}}))
        if session.config:
            await ws.send(json.dumps({"musicGenerationConfig": session.config}))
        await ws.send(json.dumps({"playbackControl": "PLAY"}))
        session.status = "streaming"

        recv_task = asyncio.ensure_future(_lyria_receive_loop(session, ws))
        while not session.stop_event.is_set():
            try:
                cmd = session.cmd_queue.get_nowait()
            except _queue.Empty:
                cmd = None
            if cmd is not None:
                try:
                    await _lyria_handle_command(session, ws, cmd)
                except Exception:
                    logger.exception("Lyria RealTime command error")
            if time.time() - session.started_at > LYRIA_MAX_SESSION_SECONDS:
                session.error = "最大セッション時間（15分）に達したため自動停止しました。"
                session.status = "stopped"
                session.stop_event.set()
                break
            if recv_task.done():
                break
            await asyncio.sleep(0.05)
        recv_task.cancel()
        try:
            await recv_task
        except Exception:
            pass
        # Best-effort graceful stop so the model finalizes the stream.
        try:
            await _lyria_send_control(session, "STOP")
        except Exception:
            pass


def _lyria_worker(session):
    loop = asyncio.new_event_loop()
    asyncio.set_event_loop(loop)
    session.loop = loop
    try:
        loop.run_until_complete(_lyria_worker_async(session))
    except asyncio.CancelledError:
        pass
    except Exception as exc:
        session.error = str(exc)
        session.status = "error"
        logger.exception("Lyria RealTime session error")
    finally:
        if session.status not in ("error", "stopped", "paused"):
            session.status = "closed"
        with session.pending_cond:
            session.pending_cond.notify_all()
        try:
            loop.run_until_complete(loop.shutdown_asyncgens())
        except Exception:
            pass
        loop.close()


def _lyria_purge_old_sessions():
    """Remove closed sessions that are past the TTL (run at session start)."""
    now = time.time()
    with LYRIA_SESSIONS_LOCK:
        stale = [
            sid for sid, sess in list(LYRIA_SESSIONS.items())
            if sess.status in ("closed", "error", "stopped")
            and (now - sess.started_at) > LYRIA_SESSION_TTL_SECONDS
        ]
        for sid in stale:
            LYRIA_SESSIONS.pop(sid, None)


def _lyria_get_session(session_id):
    session = LYRIA_SESSIONS.get(session_id or "")
    if not session or session.user_id != current_user.id:
        return None
    return session

# =============================================================================
# True real-time STS sessions (OpenAI Realtime / Grok Voice / Gemini native-audio)
# -----------------------------------------------------------------------------
# Server-held WebSocket sessions.  The browser streams microphone PCM over HTTP,
# the server relays it to the provider WebSocket in real time, and the provider's
# audio + transcripts stream back to the browser over SSE.  Provider-side VAD
# (or Gemini's natural turn handling) drives automatic turn-taking, so the user
# can talk continuously and hear the model reply while speaking.
# =============================================================================
RT_SESSIONS = {}
RT_SESSIONS_LOCK = threading.Lock()
RT_MAX_SESSION_SECONDS = 15 * 60
RT_SESSION_TTL_SECONDS = 30 * 60
RT_AUDIO_POST_MAX = 1 << 20
RT_PCM_CAP = 512 * 1024 * 1024


def _rt_is_conversation_model(model_key):
    """True for STS models that support a persistent streaming conversation."""
    model_key = XAI_STS_MODEL_ALIASES.get(model_key, model_key)
    if not is_sts_model(model_key):
        return False
    meta = STS_MODELS.get(model_key, {})
    if meta.get("mode") == "transcription":
        return False
    # Browser-direct Gemini Live models already stream in real time.
    if model_key in ("gemini-3.1-flash-live-preview", "gemini-3.5-live-translate-preview"):
        return False
    # One-shot transcription session model.
    if model_key == "gpt-realtime-whisper":
        return False
    return True


def _rt_push_event(session, event):
    with session.pending_cond:
        session.pending.append(event)
        session.pending_cond.notify_all()


def _rt_purge_old_sessions():
    now = time.time()
    with RT_SESSIONS_LOCK:
        stale = [
            sid for sid, sess in list(RT_SESSIONS.items())
            if sess.status in ("closed", "error", "stopped")
            and (now - sess.started_at) > RT_SESSION_TTL_SECONDS
        ]
        for sid in stale:
            RT_SESSIONS.pop(sid, None)


def _rt_get_session(session_id):
    session = RT_SESSIONS.get(session_id or "")
    if not session or session.user_id != current_user.id:
        return None
    return session


class RtSession:
    """One persistent real-time speech-to-speech session for a single user."""

    def __init__(self, session_id, user_id, model_key, api_key, params):
        self.session_id = session_id
        self.user_id = user_id
        self.model_key = model_key
        self.provider = get_sts_provider(model_key)
        self.api_key = api_key
        self.params = params
        meta = STS_MODELS.get(model_key, {})
        self.rate_in = int(params.get("rate_in") or meta.get("rate_in", 24000))
        self.rate_out = int(params.get("rate_out") or meta.get("rate_out", 24000))
        self.loop = None                # asyncio event loop of the worker thread
        self.ws = None                  # provider WebSocket (owned by worker thread)
        self.audio_in = _queue.Queue()  # ("audio", bytes) / ("commit",)
        self.pending = []               # output events awaiting the SSE stream
        self.pending_cond = threading.Condition()
        self.cmd_queue = _queue.Queue()  # reserved for future steering commands
        self.stop_event = threading.Event()
        self.status = "connecting"       # connecting|ready|speaking|stopped|error|closed
        self.error = None
        self.started_at = time.time()
        self.thread = None
        self.assistant_audio = bytearray()   # accumulated output PCM (for saving)
        self.assistant_lock = threading.Lock()
        self.user_audio = bytearray()        # accumulated input PCM (for saving)
        self.user_lock = threading.Lock()
        self.user_transcript = ""
        self.assistant_transcript = ""
        self.assistant_thought = ""
        self.speech_active = False
        self.turn_count = 0
        self.saved = False


def _normalize_rt_params(provider, model_key, data):
    """Validate / normalize real-time session parameters (always returns a dict)."""
    data = data or {}
    meta = STS_MODELS.get(model_key, {})
    params = {
        "rate_in": int(data.get("rate_in") or meta.get("rate_in", 24000)),
        "rate_out": int(data.get("rate_out") or meta.get("rate_out", 24000)),
    }
    if provider == "openai":
        v = str(data.get("voice") or "alloy").lower()
        params["voice"] = v if v in OPENAI_STS_VOICES else "alloy"
        speed = clamp_float(data.get("speed"), 0.25, 1.5)
        if speed is not None:
            params["speed"] = speed
    elif provider == "xai":
        v = str(data.get("voice") or "Ara")
        params["voice"] = v if v in XAI_STS_VOICES else "Ara"
    elif provider == "google":
        v = str(data.get("voice") or "Kore")
        params["voice"] = v if v in GEMINI_STS_VOICES else "Kore"
        thinking = str(data.get("thinking_level") or "").strip()
        params["thinking_level"] = thinking or None
        params["include_thoughts"] = bool(data.get("include_thoughts"))
    return params


async def _rt_openai_xai_send_loop(session, ws):
    while not session.stop_event.is_set():
        try:
            item = session.audio_in.get_nowait()
        except _queue.Empty:
            item = None
        if item is None:
            await asyncio.sleep(0.02)
            continue
        kind = item[0]
        try:
            if kind == "audio":
                data = item[1]
                if not data:
                    continue
                await ws.send(json.dumps({
                    "type": "input_audio_buffer.append",
                    "audio": base64.b64encode(data).decode("ascii"),
                }))
            elif kind == "commit":
                # Finalize any trailing audio; with server VAD this is usually
                # automatic, but the explicit commit covers the push-to-talk end.
                await ws.send(json.dumps({"type": "input_audio_buffer.commit"}))
                session.status = "speaking"
        except Exception as exc:
            logger.error(f"Realtime STS send error: {exc}")


async def _rt_openai_xai_receive_loop(session, ws):
    try:
        while True:
            raw = await ws.recv()
            if isinstance(raw, bytes):
                raw = raw.decode("utf-8", "replace")
            msg = json.loads(raw)
            mtype = msg.get("type")
            if mtype == "session.updated":
                session.status = "ready"
                _rt_push_event(session, {"type": "status", "status": "ready"})
            elif mtype == "input_audio_buffer.speech_started":
                session.speech_active = True
                _rt_push_event(session, {"type": "speech_started"})
            elif mtype == "input_audio_buffer.speech_stopped":
                session.speech_active = False
                _rt_push_event(session, {"type": "speech_stopped"})
            elif mtype == "input_audio_buffer.committed":
                _rt_push_event(session, {"type": "committed"})
            elif mtype == "response.created":
                _rt_push_event(session, {"type": "response_start"})
            elif mtype in ("response.output_audio.delta", "response.audio.delta"):
                delta = msg.get("delta")
                if delta:
                    try:
                        binary = base64.b64decode(delta)
                    except Exception:
                        binary = b""
                    if binary:
                        with session.assistant_lock:
                            if len(session.assistant_audio) + len(binary) <= RT_PCM_CAP:
                                session.assistant_audio += binary
                        _rt_push_event(session, {"type": "audio", "data": delta})
            elif mtype == "response.output_audio_transcript.delta":
                delta = msg.get("delta")
                if delta:
                    session.assistant_transcript += delta
                    _rt_push_event(session, {"type": "transcript", "role": "assistant", "delta": delta})
            elif mtype == "conversation.item.input_audio_transcription.delta":
                delta = msg.get("delta")
                if delta:
                    session.user_transcript += delta
                    _rt_push_event(session, {"type": "transcript", "role": "user", "delta": delta})
            elif mtype == "conversation.item.input_audio_transcription.updated":
                # xAI emits a cumulative transcript here.
                text = str(msg.get("transcript") or "")
                if text:
                    session.user_transcript = text
                    _rt_push_event(session, {"type": "transcript", "role": "user", "delta": text, "cumulative": True})
            elif mtype == "conversation.item.input_audio_transcription.completed":
                # OpenAI emits the full committed transcript here.
                text = str(msg.get("transcript") or "")
                if text:
                    session.user_transcript = text
                    _rt_push_event(session, {"type": "transcript", "role": "user", "delta": text, "cumulative": True})
            elif mtype == "response.done":
                session.turn_count += 1
                _rt_push_event(session, {"type": "response_done"})
            elif mtype == "error":
                raise RuntimeError(str(msg.get("error") or "Provider error"))
    except asyncio.CancelledError:
        raise
    except Exception as exc:
        session.error = str(exc)
        session.status = "error"
        session.stop_event.set()
        _rt_push_event(session, {"type": "error", "message": str(exc)})
        with session.pending_cond:
            session.pending_cond.notify_all()


async def _rt_openai_xai_session_async(session):
    model_key = session.model_key
    if session.provider == "xai":
        model_key = XAI_STS_MODEL_ALIASES.get(model_key, model_key)
        url = f"wss://{_XAI_API_HOST}/v1/realtime?model={model_key}"
        headers = {"Authorization": f"Bearer {session.api_key}"}
    else:
        if model_key == "gpt-realtime-translate":
            url = f"wss://api.openai.com/v1/realtime/translations?model={model_key}"
        else:
            url = f"wss://api.openai.com/v1/realtime?model={model_key}"
        headers = {
            "Authorization": f"Bearer {session.api_key}",
            "OpenAI-Beta": "realtime=v1",
        }

    async with websockets.connect(url, additional_headers=headers, max_size=None) as ws:
        session.ws = ws
        voice = session.params.get("voice") or ("alloy" if session.provider == "openai" else "Ara")
        audio_cfg = {
            "input": {"format": {"type": "audio/pcm", "rate": session.rate_in}},
            "output": {"format": {"type": "audio/pcm", "rate": session.rate_out}},
        }
        if session.provider == "xai":
            # xAI is OpenAI-Realtime compatible but uses a top-level turn_detection.
            sess = {
                "voice": voice,
                "turn_detection": {"type": "server_vad"},
                "audio": audio_cfg,
            }
        else:
            sess = {
                "type": "realtime",
                "model": model_key,
                "output_modalities": ["audio"],
                "voice": voice,
                "audio": audio_cfg,
            }
            sess["audio"]["input"]["turn_detection"] = {"type": "server_vad"}
            speed = session.params.get("speed")
            if speed is not None:
                sess["speed"] = speed
        await ws.send(json.dumps({"type": "session.update", "session": sess}))

        # Wait for the session to be ready before streaming audio.
        while True:
            raw = await asyncio.wait_for(ws.recv(), timeout=30)
            if isinstance(raw, bytes):
                raw = raw.decode("utf-8", "replace")
            msg = json.loads(raw)
            if msg.get("type") == "session.updated":
                session.status = "ready"
                _rt_push_event(session, {"type": "status", "status": "ready"})
                break
            if msg.get("type") == "error":
                raise RuntimeError(str(msg.get("error") or "Session setup failed"))

        recv_task = asyncio.ensure_future(_rt_openai_xai_receive_loop(session, ws))
        send_task = asyncio.ensure_future(_rt_openai_xai_send_loop(session, ws))
        while not session.stop_event.is_set():
            if time.time() - session.started_at > RT_MAX_SESSION_SECONDS:
                session.error = "最大セッション時間（15分）に達したため自動停止しました。"
                session.status = "stopped"
                session.stop_event.set()
                break
            if recv_task.done():
                break
            await asyncio.sleep(0.05)
        recv_task.cancel()
        send_task.cancel()
        try:
            await recv_task
        except Exception:
            pass
        try:
            await send_task
        except Exception:
            pass


async def _rt_gemini_send_loop(session, ws):
    while not session.stop_event.is_set():
        try:
            item = session.audio_in.get_nowait()
        except _queue.Empty:
            item = None
        if item is None:
            await asyncio.sleep(0.02)
            continue
        kind = item[0]
        if kind == "audio":
            data = item[1]
            if not data:
                continue
            try:
                await ws.send(json.dumps({
                    "realtimeInput": {
                        "audio": {
                            "data": base64.b64encode(data).decode("ascii"),
                            "mimeType": f"audio/pcm;rate={session.rate_in}",
                        }
                    }
                }))
            except Exception as exc:
                logger.error(f"Realtime STS Gemini send error: {exc}")


async def _rt_gemini_receive_loop(session, ws):
    try:
        while True:
            raw = await ws.recv()
            if isinstance(raw, bytes):
                raw = raw.decode("utf-8", "replace")
            msg = json.loads(raw)
            if msg.get("setupComplete") is not None:
                session.status = "ready"
                _rt_push_event(session, {"type": "status", "status": "ready"})
            sc = msg.get("serverContent")
            if sc is not None:
                model_turn = sc.get("modelTurn")
                if model_turn:
                    for part in model_turn.get("parts") or []:
                        inline = part.get("inlineData") or {}
                        audio_b64 = inline.get("data")
                        if audio_b64:
                            try:
                                binary = base64.b64decode(audio_b64)
                            except Exception:
                                binary = b""
                            if binary:
                                with session.assistant_lock:
                                    if len(session.assistant_audio) + len(binary) <= RT_PCM_CAP:
                                        session.assistant_audio += binary
                                _rt_push_event(session, {"type": "audio", "data": audio_b64})
                        text = part.get("text")
                        if text:
                            if part.get("thought"):
                                session.assistant_thought += text
                                _rt_push_event(session, {"type": "transcript", "role": "thought", "delta": text})
                            else:
                                session.assistant_transcript += text
                                _rt_push_event(session, {"type": "transcript", "role": "assistant", "delta": text})
                out_tr = sc.get("outputTranscription") or {}
                if out_tr.get("text"):
                    text = out_tr["text"]
                    session.assistant_transcript += text
                    _rt_push_event(session, {"type": "transcript", "role": "assistant", "delta": text})
                in_tr = sc.get("inputTranscription") or {}
                if in_tr.get("text"):
                    text = in_tr["text"]
                    session.user_transcript += text
                    _rt_push_event(session, {"type": "transcript", "role": "user", "delta": text})
                if sc.get("interrupted"):
                    _rt_push_event(session, {"type": "interrupted"})
                if sc.get("turnComplete"):
                    session.turn_count += 1
                    _rt_push_event(session, {"type": "turn_complete"})
            if msg.get("error"):
                raise RuntimeError(str(msg.get("error")))
    except asyncio.CancelledError:
        raise
    except Exception as exc:
        session.error = str(exc)
        session.status = "error"
        session.stop_event.set()
        _rt_push_event(session, {"type": "error", "message": str(exc)})
        with session.pending_cond:
            session.pending_cond.notify_all()


async def _rt_gemini_session_async(session):
    ws_url = (
        "wss://generativelanguage.googleapis.com/ws/"
        "google.ai.generativelanguage.v1beta.GenerativeService.BidiGenerateContent"
        f"?key={quote(session.api_key, safe='')}"
    )
    async with websockets.connect(ws_url, max_size=None) as ws:
        session.ws = ws
        setup = {
            "setup": {
                "model": f"models/{session.model_key}",
                "generationConfig": {"responseModalities": ["AUDIO"]},
                "inputAudioTranscription": {},
                "outputAudioTranscription": {},
            }
        }
        voice = session.params.get("voice")
        if voice and voice in GEMINI_STS_VOICES:
            setup["setup"]["generationConfig"]["speechConfig"] = {
                "voiceConfig": {"prebuiltVoiceConfig": {"voiceName": voice}}
            }
        thinking_level = session.params.get("thinking_level")
        if thinking_level:
            setup["setup"]["generationConfig"]["thinkingConfig"] = {
                "thinkingLevel": thinking_level,
                "includeThoughts": bool(session.params.get("include_thoughts")),
            }
        await ws.send(json.dumps(setup))
        while True:
            raw = await asyncio.wait_for(ws.recv(), timeout=30)
            if isinstance(raw, bytes):
                raw = raw.decode("utf-8", "replace")
            msg = json.loads(raw)
            if msg.get("setupComplete") is not None:
                session.status = "ready"
                _rt_push_event(session, {"type": "status", "status": "ready"})
                break
            if msg.get("error"):
                raise RuntimeError(str(msg.get("error")))

        recv_task = asyncio.ensure_future(_rt_gemini_receive_loop(session, ws))
        send_task = asyncio.ensure_future(_rt_gemini_send_loop(session, ws))
        while not session.stop_event.is_set():
            if time.time() - session.started_at > RT_MAX_SESSION_SECONDS:
                session.error = "最大セッション時間（15分）に達したため自動停止しました。"
                session.status = "stopped"
                session.stop_event.set()
                break
            if recv_task.done():
                break
            await asyncio.sleep(0.05)
        recv_task.cancel()
        send_task.cancel()
        try:
            await recv_task
        except Exception:
            pass
        try:
            await send_task
        except Exception:
            pass


def _rt_worker(session):
    loop = asyncio.new_event_loop()
    asyncio.set_event_loop(loop)
    session.loop = loop
    try:
        if session.provider == "google":
            loop.run_until_complete(_rt_gemini_session_async(session))
        else:
            loop.run_until_complete(_rt_openai_xai_session_async(session))
    except asyncio.CancelledError:
        pass
    except Exception as exc:
        session.error = str(exc)
        session.status = "error"
        _rt_push_event(session, {"type": "error", "message": str(exc)})
        logger.exception("Realtime STS session error")
    finally:
        if session.status not in ("error", "stopped", "paused"):
            session.status = "closed"
        session.stop_event.set()
        with session.pending_cond:
            session.pending_cond.notify_all()
        try:
            loop.run_until_complete(loop.shutdown_asyncgens())
        except Exception:
            pass
        loop.close()


def _rt_resolve_api_key(current_user_obj, model_key, provider):
    model_specific_key = _get_model_specific_api_key(current_user_obj, model_key)
    if provider == "google":
        runtime = _resolve_gemini_runtime(current_user_obj)
        return (model_specific_key or runtime.get("api_key")), None
    if provider == "openai":
        key = model_specific_key or decrypt_val(current_user_obj.openai_api_key)
        if not key and _admin_env_fallback_enabled(current_user_obj):
            key = os.getenv("OPENAI_API_KEY")
        return key, None
    if provider == "xai":
        key = model_specific_key or decrypt_val(current_user_obj.xai_api_key)
        if not key and _admin_env_fallback_enabled(current_user_obj):
            key = os.getenv("XAI_API_KEY")
        return key, None
    return None, None

async def _google_sts_live(
    pcm_bytes,
    model_key,
    gemini_api_key=None,
    gemini_backend="gemini_api",
    gemini_vertex_project=None,
    gemini_vertex_location=None,
    gemini_vertex_credentials_json=None,
    rate=16000,
    voice="Kore",
    thinking_level=None,
    include_thoughts=False,
):
    client = _get_gemini_client(
        api_key=gemini_api_key,
        backend=gemini_backend,
        vertex_project=gemini_vertex_project,
        vertex_location=gemini_vertex_location,
        vertex_credentials_json=gemini_vertex_credentials_json,
    )
    if not client:
        raise ValueError("Gemini client not configured")

    live_conf = {"response_modalities": ["AUDIO"]}
    if voice and voice in GEMINI_STS_VOICES:
        live_conf["speech_config"] = {
            "voice_config": {
                "prebuilt_voice_config": {"voice_name": voice}
            }
        }
    if thinking_level:
        live_conf["thinking_config"] = {
            "thinking_level": thinking_level,
            "include_thoughts": include_thoughts
        }

    async with client.aio.live.connect(
        model=model_key,
        config=live_conf,
    ) as session:
        # Send audio in small chunks to the Live API
        for chunk in _chunk_bytes(pcm_bytes, 4096):
            await session.send_realtime_input(
                audio=types.Blob(data=chunk, mime_type=f"audio/pcm;rate={rate}")
            )
        await session.send_realtime_input(audio_stream_end=True)
        
        total_audio_len = 0
        async for msg in session.receive():
            if total_audio_len > 10 * 1024 * 1024:
                break

            chunk_audio = bytearray()
            chunk_transcript = ""
            chunk_thought = ""
            chunk_input_transcript = ""
            turn_complete = False

            sc = getattr(msg, "server_content", None)
            if sc:
                model_turn = getattr(sc, "model_turn", None)
                if model_turn:
                    for part in model_turn.parts:
                        if part.inline_data and part.inline_data.data:
                            chunk_audio.extend(part.inline_data.data)
                        if part.text:
                            if getattr(part, "thought", False):
                                chunk_thought += part.text
                            else:
                                chunk_transcript += part.text

                if getattr(sc, "output_transcription", None) and sc.output_transcription.text:
                    chunk_transcript += sc.output_transcription.text
                if getattr(sc, "input_transcription", None) and sc.input_transcription.text:
                    chunk_input_transcript = sc.input_transcription.text
                
                if sc.turn_complete:
                    turn_complete = True
            elif msg.data:
                chunk_audio.extend(msg.data)

            if chunk_audio:
                total_audio_len += len(chunk_audio)
            
            if chunk_audio or chunk_transcript or chunk_thought or chunk_input_transcript or turn_complete:
                yield bytes(chunk_audio), chunk_transcript, chunk_input_transcript, chunk_thought, turn_complete
                if turn_complete:
                    break

