@app.route('/login', methods=['GET', 'POST'])
def login():
    if current_user.is_authenticated: return redirect(url_for('index'))
    if request.method == 'POST':
        is_ajax = request.headers.get('X-Requested-With') == 'XMLHttpRequest' or \
                  'application/json' in request.headers.get('Accept', '')
        
        if request.is_json:
            form_data = request.get_json(silent=True) or {}
        else:
            form_data = request.form

        login_ip = get_client_ip() or request.remote_addr or 'unknown'
        if not rate_limit(f"rl:login:ip:{login_ip}", 20, 300):
            if is_ajax: return jsonify({'error': "Too many attempts. Try again later."}), 429
            return render_template('login.html', site_key=os.getenv('TURNSTILE_SITE_KEY'), error="Too many attempts. Try again later.")

        if not verify_turnstile(form_data.get('cf-turnstile-response')):
            if is_ajax: return jsonify({'error': "認証エラーが発生しました"}), 401
            return render_template('login.html', site_key=os.getenv('TURNSTILE_SITE_KEY'), error="認証エラーが発生しました")
            
        username = (form_data.get('username') or '').strip()
        pw = form_data.get('password') or ""
        if len(username) > 80 or len(pw) > 512:
            if is_ajax:
                return jsonify({'error': "ユーザー名またはパスワードが正しくありません"}), 401
            return render_template('login.html', site_key=os.getenv('TURNSTILE_SITE_KEY'), error="ユーザー名またはパスワードが正しくありません"), 401
        user = User.query.filter_by(username=username).first()
        # Allow login even if IP/Cookie is banned; ban screen will handle after login.
        if user:
            if not rate_limit(f"rl:login:user:{user.id}", 10, 300):
                if is_ajax: return jsonify({'error': "Too many attempts. Try again later."}), 429
                return render_template('login.html', site_key=os.getenv('TURNSTILE_SITE_KEY'), error="Too many attempts. Try again later.")
            
            now = datetime.utcnow()
            easy_ok = False
            try:
                if user.easy_login_hash and user.easy_login_expires_at and now <= user.easy_login_expires_at:
                    easy_ok = check_password_hash(user.easy_login_hash, pw)
            except Exception:
                easy_ok = False
                
            if easy_ok:
                # One-time easy login: disable after first successful use
                user.easy_login_hash = None
                user.easy_login_expires_at = None
                safe_db_commit()
                session['easy_login_used'] = True
                remember = bool(form_data.get('remember'))
                login_user(user, remember=remember)
                create_user_session(user)
                record_user_client_token(user)
                if is_ajax: return jsonify({'status': 'ok', 'redirect': url_for('index')})
                return redirect(url_for('index'))
                
            if user.easy_login_hash and user.easy_login_expires_at and now > user.easy_login_expires_at:
                user.easy_login_hash = None
                user.easy_login_expires_at = None
                safe_db_commit()
                
            if user.check_password(pw):
                if user.is_2fa_enabled:
                    session['remember_me'] = bool(form_data.get('remember'))
                    session['pre_2fa_user_id'] = user.id
                    if is_ajax: return jsonify({
                        'status': '2fa_required',
                        'default_method': user.default_2fa_method or 'totp'
                    })
                    return redirect(url_for('verify_2fa'))
                
                remember = bool(form_data.get('remember'))
                login_user(user, remember=remember)
                create_user_session(user)
                record_user_client_token(user)
                if is_ajax: return jsonify({'status': 'ok', 'redirect': url_for('index')})
                return redirect(url_for('index'))
                
        if is_ajax: return jsonify({'error': "ユーザー名またはパスワードが正しくありません"}), 401
        g_client_id = os.getenv('GOOGLE_CLIENT_ID', '')
        if not g_client_id:
            log_force("DEBUG: GOOGLE_CLIENT_ID is missing in .env")
        return render_template('login.html', 
                               site_key=os.getenv('TURNSTILE_SITE_KEY'), 
                               google_client_id=g_client_id, 
                               error="ユーザー名またはパスワードが正しくありません")
    
    g_client_id = os.getenv('GOOGLE_CLIENT_ID', '')
    return render_template('login.html', 
                           site_key=os.getenv('TURNSTILE_SITE_KEY'), 
                           google_client_id=g_client_id)

def _resolve_or_create_google_user(google_id, email):
    """Resolve or create the account for a verified Google identity.

    Accounts are matched strictly by Google identity (``google_id``) and by
    the verified Google email already recorded on the account
    (``google_email``).  Usernames are never used for linking, so an account
    whose username happens to equal another person's Google email cannot
    absorb that person's Google login (pre-account-takeover defense).  When
    the email-as-username is already taken by an unrelated registration, a
    unique username is generated so a legitimate Google signup is never
    silently routed into that account.
    """
    user = User.query.filter_by(google_id=google_id).first()
    if user:
        return user
    user = User.query.filter_by(google_email=email).first()
    if user:
        if user.google_id and user.google_id != google_id:
            raise ValueError("Invalid Google identity")
        user.google_id = google_id
        if not user.google_email:
            user.google_email = email
        safe_db_commit()
        return user
    username = email
    if User.query.filter_by(username=username).first():
        local = (email.split('@', 1)[0] or 'user')[:40]
        while True:
            username = f"{local}-{secrets.token_hex(4)}"
            if not User.query.filter_by(username=username).first():
                break
    user = User(
        username=username,
        google_id=google_id,
        google_email=email,
        is_setup_completed=False,
    )
    db.session.add(user)
    safe_db_commit()
    return user

@app.route('/login/google')
def login_google():
    if current_user.is_authenticated:
        # If already logged in, we are linking
        session['google_link_mode'] = True
    else:
        session.pop('google_link_mode', None)
    redirect_uri = url_for('login_google_callback', _external=True)
    return oauth.google.authorize_redirect(redirect_uri)

@app.route('/login/google/callback')
def login_google_callback():
    link_mode = session.pop('google_link_mode', False)
    try:
        token = oauth.google.authorize_access_token()
        user_info = token.get('userinfo')
        if not user_info or user_info.get('email_verified') is not True:
            flash("Google からユーザー情報を取得できませんでした。")
            return redirect(url_for('login' if not current_user.is_authenticated else 'index'))
        
        google_id = str(user_info.get('sub') or '').strip()
        email = str(user_info.get('email') or '').strip().lower()
        if not google_id or not email or len(email) > 128:
            raise ValueError("Invalid Google identity")
        
        if current_user.is_authenticated:
            # Explicit linking from settings
            existing_with_id = User.query.filter_by(google_id=google_id).first()
            if existing_with_id and existing_with_id.id != current_user.id:
                flash("この Google アカウントは既に他のユーザーに紐付けられています。")
                return redirect(url_for('index'))
            
            current_user.google_id = google_id
            if not current_user.google_email:
                current_user.google_email = email
            safe_db_commit()
            flash("Google アカウントと連携しました。")
            return redirect(url_for('index'))

        # Login/Signup flow
        user = _resolve_or_create_google_user(google_id, email)

        if user.is_2fa_enabled and not user.skip_2fa_on_google_login:
            session['pre_2fa_user_id'] = user.id
            session['remember_me'] = True
            return redirect(url_for('verify_2fa'))

        login_user(user, remember=True)
        create_user_session(user)
        record_user_client_token(user)
        
        if not user.is_setup_completed:
            return redirect(url_for('setup'))
        return redirect(url_for('index'))
    except Exception as e:
        logger.error(f"Google Login Callback Error: {e}")
        flash("Google 連携中にエラーが発生しました。")
        return redirect(url_for('login' if not current_user.is_authenticated else 'index'))

@app.route('/login/google/one-tap', methods=['POST'])
def login_google_one_tap():
    token = request.form.get('credential')
    if not token:
        return jsonify({'error': 'No credential provided'}), 400
    
    try:
        # Verify the ID token
        idinfo = id_token.verify_oauth2_token(token, google_requests.Request(), os.getenv('GOOGLE_CLIENT_ID'))

        if idinfo.get('email_verified') is not True:
            return jsonify({'error': 'Google email is not verified'}), 400
        google_id = str(idinfo.get('sub') or '').strip()
        email = str(idinfo.get('email') or '').strip().lower()
        if not google_id or not email or len(email) > 128:
            return jsonify({'error': 'Invalid Google identity'}), 400
        
        user = _resolve_or_create_google_user(google_id, email)

        if user.is_2fa_enabled and not user.skip_2fa_on_google_login:
            session['pre_2fa_user_id'] = user.id
            session['remember_me'] = True
            return jsonify({
                'status': '2fa_required', 
                'redirect': url_for('verify_2fa'),
                'default_method': user.default_2fa_method or 'totp'
            })

        login_user(user, remember=True)
        create_user_session(user)
        record_user_client_token(user)
        
        if not user.is_setup_completed:
            return jsonify({'status': 'ok', 'redirect': url_for('setup')})
        return jsonify({'status': 'ok', 'redirect': url_for('index')})

    except Exception as e:
        logger.error(f"Google One Tap Login Error: {e}")
        return jsonify({'error': 'Google One Tap 認証中にエラーが発生しました'}), 400

@app.route('/api/account/unlink_google', methods=['POST'])
@login_required
def unlink_google():
    if not current_user.google_id:
        return jsonify({'error': 'Not linked'}), 400
    
    # Optional: Prevent unlinking if no password or other login method exists
    # but here we allow it.
    current_user.google_id = None
    current_user.google_email = None
    safe_db_commit()
    return jsonify({'status': 'ok'})

@app.route('/login/passkey/options', methods=['POST'])
def login_passkey_options():
    if current_user.is_authenticated:
        return jsonify({'error': 'already_authenticated'}), 400
    login_ip = get_client_ip() or request.remote_addr or 'unknown'
    if not rate_limit(f"rl:login:ip:{login_ip}", 20, 300):
        return jsonify({'error': 'Too many attempts. Try again later.'}), 429
    data = request.json or {}
    if not verify_turnstile(data.get('turnstile')):
        return jsonify({'error': 'Auth Error'}), 401
    username = (data.get('username') or '').strip()
    if not username:
        return jsonify({'error': 'Username required'}), 400
    user = User.query.filter_by(username=username).first()
    if not user or not getattr(user, "passkey_only_login", False):
        return jsonify({'error': 'Invalid credentials'}), 400
    # Allow passkey login even if IP/Cookie is banned; ban screen will handle after login.
    if not rate_limit(f"rl:login:user:{user.id}", 10, 300):
        return jsonify({'error': 'Too many attempts. Try again later.'}), 429
    creds = _load_user_webauthn_credentials(user)
    if not creds:
        return jsonify({'error': 'No credentials'}), 400
    options = generate_authentication_options(
        rp_id=request.host.split(':')[0],
        allow_credentials=[
            PublicKeyCredentialDescriptor(id=base64url_to_bytes(c['id'])) for c in creds
        ],
        user_verification=UserVerificationRequirement.REQUIRED
    )
    session['passkey_login_user_id'] = user.id
    session['webauthn_login_challenge'] = base64.b64encode(options.challenge).decode('utf-8')
    session['passkey_login_remember'] = bool(data.get('remember'))
    return options_to_json(options)

@app.route('/login/passkey/verify', methods=['POST'])
def login_passkey_verify():
    if current_user.is_authenticated:
        return jsonify({'error': 'already_authenticated'}), 400
    user_id = session.get('passkey_login_user_id')
    if not user_id:
        return jsonify({'error': 'Session expired'}), 401
    if not rate_limit(f"rl:webauthn:user:{user_id}", 8, 300):
        return jsonify({'error': 'Too many attempts'}), 429
    user = User.query.get(user_id)
    if not user:
        return jsonify({'error': 'Invalid user'}), 400
    try:
        data = request.json or {}
        challenge = session.get('webauthn_login_challenge')
        if not challenge:
            return jsonify({'error': 'Challenge missing'}), 400
        creds = _load_user_webauthn_credentials(user)
        credential_id = str(data.get('id') or '').strip()
        current_cred = next((c for c in creds if c['id'] == credential_id), None)
        if not current_cred:
            return jsonify({'error': 'Credential not found'}), 400
        verification = verify_authentication_response(
            credential=data,
            expected_challenge=base64.b64decode(challenge),
            expected_rp_id=request.host.split(':')[0],
            expected_origin=request.url_root.rstrip('/'),
            credential_public_key=base64url_to_bytes(current_cred['public_key']),
            credential_current_sign_count=current_cred['sign_count'],
            require_user_verification=True
        )
        current_cred['sign_count'] = verification.new_sign_count
        _save_user_webauthn_credentials(user, creds)
        db.session.commit()
        session.pop('passkey_login_user_id', None)
        session.pop('webauthn_login_challenge', None)
        remember = bool(session.pop('passkey_login_remember', False))
        login_user(user, remember=remember)
        create_user_session(user)
        record_user_client_token(user)
        return jsonify({'status': 'ok'})
    except Exception as e:
        logger.error(f"Passkey Login Verify Error: {e}")
        return jsonify({'error': str(e)}), 400

@app.route('/verify-2fa', methods=['GET', 'POST'])
def verify_2fa():
    if current_user.is_authenticated: return redirect(url_for('index'))
    user_id = session.get('pre_2fa_user_id')
    if not user_id: return redirect(url_for('login'))
    
    user = User.query.get(user_id)
    if not user: return redirect(url_for('login'))

    if request.method == 'POST':
        is_ajax = request.headers.get('X-Requested-With') == 'XMLHttpRequest' or \
                  'application/json' in request.headers.get('Accept', '')
        
        if not rate_limit(f"rl:2fa:user:{user.id}", 8, 300):
            if is_ajax: return jsonify({'error': "Too many attempts. Try again later."}), 429
            return render_template('verify_2fa.html', error="Too many attempts. Try again later.")
            
        code = None
        if is_ajax:
            data = request.json or {}
            code = data.get('totp_code')
        
        if not code:
            code = request.form.get('totp_code')
            
        if code:
            secret = decrypt_val(user.totp_secret)
            if secret and pyotp.TOTP(secret).verify(code):
                session.pop('pre_2fa_user_id', None)
                remember = bool(session.pop('remember_me', False))
                login_user(user, remember=remember)
                create_user_session(user)
                record_user_client_token(user)
                if is_ajax: return jsonify({'status': 'ok', 'redirect': url_for('index')})
                return redirect(url_for('index'))
            
            if is_ajax: return jsonify({'error': "Invalid Code"}), 400
            return render_template('verify_2fa.html', error="Invalid Code")
        
        if is_ajax: return jsonify({'error': "Code required"}), 400
            
    has_totp = bool(user.totp_secret)
    has_webauthn = bool(_load_user_webauthn_credentials(user))
    default_method = user.default_2fa_method or 'totp'
    
    # If the default method is not available, switch to the one that is
    if default_method == 'totp' and not has_totp and has_webauthn:
        default_method = 'webauthn'
    elif default_method == 'webauthn' and not has_webauthn and has_totp:
        default_method = 'totp'

    return render_template('verify_2fa.html', 
                           has_totp=has_totp, 
                           has_webauthn=has_webauthn, 
                           default_method=default_method)

@app.route('/verify-2fa/webauthn/options', methods=['POST'])
def verify_2fa_webauthn_options():
    user_id = session.get('pre_2fa_user_id')
    logger.info(f"WebAuthn Options Req: user_id={user_id}, session={session.keys()}")
    if not user_id: return jsonify({'error': 'Session expired'}), 401
    user = User.query.get(user_id)
    
    creds = _load_user_webauthn_credentials(user)
    
    logger.info(f"User Creds Count: {len(creds)}")
    if not creds: return jsonify({'error': 'No credentials'}), 400

    options = generate_authentication_options(
        rp_id=request.host.split(':')[0],
        allow_credentials=[
            PublicKeyCredentialDescriptor(id=base64url_to_bytes(c['id'])) for c in creds
        ],
        user_verification=UserVerificationRequirement.PREFERRED
    )
    
    session['webauthn_challenge'] = base64.b64encode(options.challenge).decode('utf-8')
    return options_to_json(options)

@app.route('/verify-2fa/webauthn/verify', methods=['POST'])
def verify_2fa_webauthn_verify():
    user_id = session.get('pre_2fa_user_id')
    if not user_id: return jsonify({'error': 'Session expired'}), 401
    user = User.query.get(user_id)
    if not rate_limit(f"rl:webauthn:user:{user_id}", 8, 300):
        return jsonify({'error': 'Too many attempts'}), 429
    
    try:
        data = request.json or {}
        challenge = session.get('webauthn_challenge')
        if not challenge: return jsonify({'error': 'Challenge missing'}), 400
        
        creds = _load_user_webauthn_credentials(user)
        credential_id = str(data.get('id') or '').strip()
        current_cred = next((c for c in creds if c['id'] == credential_id), None)
        if not current_cred: return jsonify({'error': 'Credential not found'}), 400

        verification = verify_authentication_response(
            credential=data,
            expected_challenge=base64.b64decode(challenge),
            expected_rp_id=request.host.split(':')[0],
            expected_origin=request.url_root.rstrip('/'),
            credential_public_key=base64url_to_bytes(current_cred['public_key']),
            credential_current_sign_count=current_cred['sign_count'],
            require_user_verification=False # Depends on device
        )
        
        current_cred['sign_count'] = verification.new_sign_count
        _save_user_webauthn_credentials(user, creds)
        db.session.commit()
        
        session.pop('pre_2fa_user_id', None)
        remember = bool(session.pop('remember_me', False))
        login_user(user, remember=remember)
        create_user_session(user)
        return jsonify({'status': 'ok'})
    except Exception as e:
        logger.error(f"WebAuthn Verify Error: {e}")
        return jsonify({'error': str(e)}), 400

@app.route('/signup', methods=['GET', 'POST'])
def signup():
    if current_user.is_authenticated: return redirect(url_for('index'))
    if request.method == 'POST':
        signup_ip = get_client_ip() or request.remote_addr or 'unknown'
        if not rate_limit(f"rl:signup:ip:{signup_ip}", 10, 3600):
            return render_template('signup.html', site_key=os.getenv('TURNSTILE_SITE_KEY'), error="Too many attempts. Try again later.")
        if not verify_turnstile(request.form.get('cf-turnstile-response')): return render_template('signup.html', site_key=os.getenv('TURNSTILE_SITE_KEY'), error="Auth Error")
        if is_request_banned_identifier():
            return render_template('signup.html', site_key=os.getenv('TURNSTILE_SITE_KEY'), error="Signup blocked.")
        username = str(request.form.get('username') or '').replace('\x00', '').strip()
        password = str(request.form.get('password') or '')
        if len(username) < 3 or len(username) > 80 or re.search(r'[\x00-\x1f\x7f]', username):
            return render_template('signup.html', site_key=os.getenv('TURNSTILE_SITE_KEY'), error="Username must be 3-80 characters.")
        if '@' in username:
            return render_template('signup.html', site_key=os.getenv('TURNSTILE_SITE_KEY'), error="Username cannot contain @.")
        if len(password) < 8 or len(password) > 256:
            return render_template('signup.html', site_key=os.getenv('TURNSTILE_SITE_KEY'), error="Password must be 8-256 characters.")
        if _is_primary_admin_username(username): return render_template('signup.html', site_key=os.getenv('TURNSTILE_SITE_KEY'), error="Username taken")
        if User.query.filter_by(username=username).first(): return render_template('signup.html', site_key=os.getenv('TURNSTILE_SITE_KEY'), error="Username taken")
        new_user = User(username=username, is_setup_completed=False)
        new_user.set_password(password)
        db.session.add(new_user)
        safe_db_commit()
        login_user(new_user)
        # Establish the server-side session before redirecting.  Deferring this
        # to ensure_active_session on the first /setup request allowed parallel
        # browser requests (manifest/service-worker, etc.) to create competing
        # sessions; one could revoke the other and send the user back to /login.
        create_user_session(new_user)
        record_user_client_token(new_user)
        return redirect(url_for('setup'))
    return render_template('signup.html', site_key=os.getenv('TURNSTILE_SITE_KEY'))

def _user_has_unencrypted_data(user):
    """True when the account still stores plaintext messages or files.

    During setup a freshly imported account may already contain chats/files
    before the user picks E2EE on the final keys step.  When E2EE is enabled at
    that point the imported data must be re-encrypted to match, so the setup
    handler can detect whether a migration job is actually needed.
    """
    try:
        has_unencrypted_message = db.session.query(Message.id).join(
            Thread, Message.thread_id == Thread.id
        ).filter(
            Thread.user_id == user.id,
            or_(Message.is_encrypted.is_(None), Message.is_encrypted.is_(False)),
        ).first() is not None
    except Exception:
        has_unencrypted_message = False
    has_unencrypted_file = False
    user_dir = os.path.join(app.config['UPLOAD_FOLDER'], str(user.id))
    if os.path.isdir(user_dir):
        try:
            for root, _, names in os.walk(user_dir):
                if any(not name.endswith('.enc') for name in names):
                    has_unencrypted_file = True
                    break
        except Exception:
            pass
    return has_unencrypted_message or has_unencrypted_file

@app.route('/setup', methods=['GET', 'POST'])
@login_required
def setup():
    if current_user.is_setup_completed: return redirect(url_for('index'))
    if request.method == 'POST':
        try:
            vertex_credentials_json = _normalize_gemini_vertex_credentials_json(request.form.get('gemini_vertex_credentials_json'))
        except ValueError as e:
            return render_template('setup.html', error=str(e))
        # Preserve secrets imported during the setup step when a key field is
        # left empty here, instead of overwriting them with an empty value.
        for field, raw_value in (
            ('openai_api_key', request.form.get('openai_key')),
            ('gemini_api_key', request.form.get('gemini_key')),
            ('deepseek_api_key', request.form.get('deepseek_key')),
            ('kimi_api_key', request.form.get('kimi_key')),
            ('mistral_api_key', request.form.get('mistral_key')),
            ('xai_api_key', request.form.get('xai_key')),
            ('google_api_key', request.form.get('google_key')),
            ('google_cloud_project', request.form.get('google_project')),
            ('gemini_vertex_project', request.form.get('gemini_vertex_project')),
            ('gemini_vertex_credentials_json', vertex_credentials_json),
        ):
            value = str(raw_value or '').strip()
            if value:
                setattr(current_user, field, encrypt_val(value))
        current_user.gemini_backend = _normalize_gemini_backend(request.form.get('gemini_backend'))
        current_user.gemini_vertex_location = _normalize_gemini_vertex_location(request.form.get('gemini_vertex_location'))
        current_user.default_model = request.form.get('default_model') or "gemini-3.6-flash"
        current_user.enable_e2ee = (request.form.get('enable_e2ee') == 'on')
        current_user.is_setup_completed = True
        safe_db_commit()
        # Data imported during the setup step is stored with the account's
        # pre-setup E2EE state (plaintext).  When the user enables E2EE here,
        # re-encrypt the imported content in the background so it matches, in
        # the same way toggling E2EE on the settings screen triggers a migration.
        if current_user.enable_e2ee and _user_has_unencrypted_data(current_user):
            task_queue.enqueue(migrate_e2ee_task, current_user.id, True)
        return redirect(url_for('index'))
    return render_template(
        'setup.html',
        default_model=current_user.default_model or 'gemini-3.6-flash',
        gemini_backend=_normalize_gemini_backend(current_user.gemini_backend),
    )

@app.route('/logout', methods=['POST'])
def logout():
    if current_user.is_authenticated:
        sid = session.get('session_id')
        if sid:
            user_sess = UserSession.query.filter_by(user_id=current_user.id, session_id=sid, is_revoked=False).first()
            if user_sess:
                user_sess.is_revoked = True
                user_sess.revoked_at = datetime.utcnow()
                try:
                    safe_db_commit()
                except Exception:
                    pass
    logout_user()
    session.pop('session_id', None)
    session.pop('pre_2fa_user_id', None)
    return redirect(url_for('index'))

# -----------------------------------------------------------
# API Routes
# -----------------------------------------------------------

def _is_browser_fast_mode_model(model_key):
    model_l = str(model_key or '').strip().lower()
    return (
        model_key in ALL_VALID_MODEL_IDS
        and model_l.startswith('gemini-')
        and not any(marker in model_l for marker in ('image', 'native-audio', 'tts', 'live'))
    )

def _get_browser_fast_mode_user_key(user, model_key):
    """Return only a key owned by this user; never disclose admin/env fallback keys."""
    model_key_value = _get_model_specific_api_key(user, model_key)
    if model_key_value:
        return model_key_value, 'model_specific'
    common_value = decrypt_val(getattr(user, 'gemini_api_key', None)) if user else None
    if common_value and str(common_value).strip():
        return str(common_value).strip(), 'gemini_common'
    return None, None

def _browser_fast_mode_history(thread, parent_message):
    if not thread or not parent_message:
        return []
    all_messages = Message.query.filter_by(thread_id=thread.id).all()
    message_map = {message.id: message for message in all_messages}
    current = message_map.get(parent_message.id)
    history_rev = []
    total_chars = 0
    selected_image_count = 0
    selected_image_bytes = 0
    while current and len(history_rev) < 200:
        raw_content = current.content or ''
        content = decrypt_val(raw_content) if current.is_encrypted else raw_content
        content = str(content or '')
        if total_chars + len(content) > 1_000_000:
            break
        images = []
        if current.image_url:
            for raw_ref in _iter_message_attachment_refs(current.image_url):
                if selected_image_count >= BROWSER_FAST_HISTORY_IMAGE_MAX_ITEMS:
                    break
                normalized = _normalize_attachment_list([raw_ref], thread.user_id)
                if len(normalized) != 1:
                    continue
                ref = normalized[0]
                if os.path.splitext(ref)[1].lower() not in _IMAGE_THUMB_EXTS:
                    continue
                info = _get_file_disk_info(ref)
                size = int(info.get('size') or 0) if info.get('exists') else 0
                if size <= 0 or selected_image_bytes + size > BROWSER_FAST_HISTORY_IMAGE_MAX_BYTES:
                    continue
                images.append({
                    'path': ref,
                    'mime_type': _normalize_media_mime(ref, mimetypes.guess_type(ref)[0] or 'application/octet-stream'),
                })
                selected_image_count += 1
                selected_image_bytes += size
        signatures = []
        if current.role == 'assistant' and current.thought_signature:
            try:
                parsed_signatures = json.loads(current.thought_signature)
                if isinstance(parsed_signatures, list):
                    signatures = [str(value) for value in parsed_signatures if value][:16]
                elif isinstance(parsed_signatures, str) and parsed_signatures:
                    signatures = [parsed_signatures]
            except Exception:
                signatures = [str(current.thought_signature)]
        if current.role in ('user', 'assistant') and (content or images or signatures):
            history_rev.append({
                'role': 'model' if current.role == 'assistant' else 'user',
                'text': content,
                'images': images,
                'thought_signatures': signatures,
            })
            total_chars += len(content)
        current = message_map.get(current.parent_id) if current.parent_id else None
    return list(reversed(history_rev))

@app.route('/api/browser_fast_mode/bootstrap', methods=['POST'])
@login_required
def bootstrap_browser_fast_mode():
    """Return the selected user's own Gemini key and the selected branch context."""
    if not rate_limit(f"rl:browser_fast_bootstrap:user:{current_user.id}", 60, 60):
        return jsonify({'error': 'rate_limit'}), 429
    data = request.get_json(silent=True) or {}
    if not isinstance(data, dict):
        return jsonify({'error': 'Invalid request'}), 400
    model_key = str(data.get('model') or '').strip()
    if not _is_browser_fast_mode_model(model_key):
        return jsonify({'error': 'Browser fast mode supports Gemini text models only'}), 400
    api_key, key_source = _get_browser_fast_mode_user_key(current_user, model_key)
    if not api_key:
        return jsonify({
            'error': '選択中モデルのモデル別APIキーまたは共通Gemini APIキーを設定してください',
            'code': 'user_api_key_missing',
        }), 400

    thread = None
    parent_message = None
    thread_ref = data.get('thread_id')
    if thread_ref:
        thread = resolve_thread_for_user(thread_ref, current_user.id)
        if not thread:
            return jsonify({'error': 'Invalid thread'}), 403
        parent_raw = data.get('parent_id')
        if parent_raw is not None and str(parent_raw).strip():
            try:
                parent_id = int(parent_raw)
            except (TypeError, ValueError):
                return jsonify({'error': 'Invalid parent message'}), 400
            parent_message = Message.query.filter_by(id=parent_id, thread_id=thread.id).first()
            if not parent_message:
                return jsonify({'error': 'Invalid parent message'}), 400
        else:
            parent_message = Message.query.filter_by(thread_id=thread.id).order_by(Message.id.desc()).first()

    response = jsonify({
        'status': 'ok',
        'api_key': api_key,
        'key_source': key_source,
        'model': model_key,
        'thread_id': thread.public_id if thread else None,
        'parent_id': parent_message.id if parent_message else None,
        'history': _browser_fast_mode_history(thread, parent_message),
    })
    response.headers['Cache-Control'] = 'no-store, no-cache, must-revalidate, private'
    response.headers['Pragma'] = 'no-cache'
    return response

@app.route('/api/browser_fast_mode/save', methods=['POST'])
@login_required
def save_browser_fast_mode_chat():
    """Persist a completed browser-direct Gemini turn as one atomic DB transaction."""
    if not rate_limit(f"rl:browser_fast_save:user:{current_user.id}", 30, 60):
        return jsonify({'error': 'rate_limit'}), 429
    data = request.get_json(silent=True) or {}
    if not isinstance(data, dict):
        return jsonify({'error': 'Invalid request'}), 400
    gate_resp = _bot_turnstile_gate(data.get('turnstile_token'))
    if gate_resp is not None:
        return gate_resp
    client_request_id = str(data.get('client_request_id') or '').strip()
    if client_request_id and not re.fullmatch(r'[A-Za-z0-9_-]{8,64}', client_request_id):
        return jsonify({'error': 'Invalid client request ID'}), 400

    user_text = data.get('message')
    assistant_text = data.get('assistant_content')
    thought_text = data.get('thought_content') or ''
    model_key = str(data.get('model') or '').strip()
    if not isinstance(user_text, str) or len(user_text) > 500_000:
        return jsonify({'error': 'Invalid or oversized message'}), 400
    # Allow image-only sends (no prompt text) when images are attached.
    fast_refs = data.get('image_urls') or []
    if not isinstance(fast_refs, list):
        fast_refs = [fast_refs]
    if not user_text.strip() and not bool([r for r in fast_refs if r]):
        return jsonify({'error': 'Invalid or oversized message'}), 400
    if not isinstance(assistant_text, str) or not assistant_text.strip() or len(assistant_text) > 2_000_000:
        return jsonify({'error': 'Invalid or oversized assistant content'}), 400
    if not isinstance(thought_text, str) or len(thought_text) > 2_000_000:
        return jsonify({'error': 'Invalid or oversized thought content'}), 400
    if not _is_browser_fast_mode_model(model_key):
        return jsonify({'error': 'Browser fast mode supports Gemini text models only'}), 400

    raw_signatures = data.get('thought_signatures') or []
    if not isinstance(raw_signatures, list) or len(raw_signatures) > 16:
        return jsonify({'error': 'Invalid thought signatures'}), 400
    thought_signatures = []
    signature_bytes = 0
    for raw_signature in raw_signatures:
        signature = str(raw_signature or '').strip()
        if not signature or len(signature) > 100_000:
            return jsonify({'error': 'Invalid thought signature'}), 400
        try:
            decoded_signature = base64.b64decode(signature, validate=True)
        except Exception:
            return jsonify({'error': 'Invalid thought signature'}), 400
        signature_bytes += len(decoded_signature)
        if signature_bytes > 256_000:
            return jsonify({'error': 'Thought signatures are too large'}), 400
        thought_signatures.append(signature)

    raw_refs = data.get('image_urls') or []
    if not isinstance(raw_refs, list):
        raw_refs = [raw_refs]
    refs = _normalize_attachment_list(raw_refs, current_user.id)
    if len(refs) != len(raw_refs):
        return jsonify({'error': 'One or more browser fast mode image references are invalid'}), 400
    if len(refs) > min(4, int(app.config.get('ATTACHMENT_MAX_FILES') or 30)):
        return jsonify({'error': 'Browser fast mode accepts at most 4 images'}), 400
    total_image_bytes = 0
    for ref in refs:
        ext = os.path.splitext(ref)[1].lower()
        info = _get_file_disk_info(ref)
        if ext not in _IMAGE_THUMB_EXTS or not info.get('exists'):
            return jsonify({'error': 'A saved browser fast mode image is missing or invalid'}), 400
        total_image_bytes += int(info.get('size') or 0)
        if total_image_bytes > _LOW_LATENCY_IMAGE_MAX_BYTES:
            return jsonify({'error': 'Browser fast mode images exceed the save limit'}), 400

    is_enc = bool(getattr(current_user, 'enable_e2ee', False))
    user_content = encrypt_val(user_text) if is_enc else user_text
    thought_payload = json.dumps({'text': thought_text}, ensure_ascii=False) if thought_text else None
    assistant_content = assistant_text
    if is_enc:
        assistant_content = encrypt_val(assistant_content)
        if thought_payload:
            thought_payload = encrypt_val(thought_payload)

    user_tokens = count_tokens(user_text, model_key)
    thought_tokens = count_tokens(thought_text, model_key) if thought_text else 0
    assistant_tokens = count_tokens_for_display(assistant_text, model_key, thought_text)
    thread_ref = data.get('thread_id')
    parent_raw = data.get('parent_id')
    if not thread_ref and parent_raw is not None and str(parent_raw).strip():
        return jsonify({'error': 'A parent message requires an existing thread'}), 400
    try:
        created_thread = not bool(thread_ref)
        if thread_ref:
            thread = resolve_thread_for_user(thread_ref, current_user.id)
            if not thread:
                return jsonify({'error': 'Invalid thread'}), 403
        else:
            thread = Thread(
                user_id=current_user.id,
                public_id=generate_thread_public_id(),
                title=_normalize_thread_title(user_text.strip()[:160] or 'New Chat'),
                is_temporary=bool(data.get('temporary_chat')),
                include_global_instruction=False,
                last_model=model_key,
                updated_at=datetime.utcnow(),
            )
            db.session.add(thread)
            db.session.flush()
        parent_message = None
        if parent_raw is not None and str(parent_raw).strip():
            try:
                parent_id = int(parent_raw)
            except (TypeError, ValueError):
                return jsonify({'error': 'Invalid parent message'}), 400
            parent_message = Message.query.filter_by(id=parent_id, thread_id=thread.id).first()
            if not parent_message:
                return jsonify({'error': 'Invalid parent message'}), 400
        elif not created_thread:
            parent_message = Message.query.filter_by(thread_id=thread.id).order_by(Message.id.desc()).first()
        submission_claimed, existing_submission = _claim_chat_submission(current_user.id, client_request_id)
        if not submission_claimed:
            if existing_submission and existing_submission.get("state") == "accepted":
                cached_response = existing_submission.get("response")
                if isinstance(cached_response, dict):
                    return jsonify(cached_response)
            return jsonify({
                "error": "This browser-fast turn is still being saved",
                "code": "submission_in_progress",
            }), 425
        user_msg = Message(
            thread_id=thread.id,
            role='user',
            content=user_content,
            model=model_key,
            image_url=json.dumps(refs) if refs else None,
            is_encrypted=is_enc,
            parent_id=parent_message.id if parent_message else None,
            tokens_in=user_tokens,
            tokens=sum_token_counts(user_tokens, None),
        )
        db.session.add(user_msg)
        db.session.flush()
        assistant_msg = Message(
            thread_id=thread.id,
            role='assistant',
            content=assistant_content,
            model=model_key,
            thought_data=thought_payload,
            thought_signature=json.dumps(thought_signatures) if thought_signatures else None,
            is_encrypted=is_enc,
            parent_id=user_msg.id,
            tokens_out=assistant_tokens,
            tokens=sum_token_counts(None, assistant_tokens),
            tokens_thought=thought_tokens,
        )
        db.session.add(assistant_msg)
        thread.updated_at = datetime.utcnow()
        thread.last_model = model_key
        current_user.last_model = model_key
        safe_db_commit()
        if thread.is_temporary:
            try:
                _mark_temp_chat_presence(
                    thread,
                    current_user.id,
                    timeout_seconds=_get_user_temp_chat_timeout_seconds(current_user),
                )
                _track_temp_chat_uploaded_refs(thread, current_user.id, refs)
            except Exception as exc:
                logger.warning("Browser fast mode temporary tracking failed for thread %s: %s", thread.id, exc)
        response_payload = {
            'status': 'ok',
            'thread_id': thread.public_id,
            'user_message_id': user_msg.id,
            'assistant_message_id': assistant_msg.id,
            'created_thread': created_thread,
        }
        _store_idempotent_submission(
            current_user.id,
            client_request_id,
            {"response": response_payload},
        )
        return jsonify(response_payload)
    except Exception as exc:
        db.session.rollback()
        _release_chat_submission(current_user.id, client_request_id)
        logger.error("Browser fast mode save failed for user %s: %s", current_user.id, exc)
        return jsonify({'error': 'Failed to save browser fast mode chat'}), 500


@app.route('/chat_stream', methods=['POST'])
@login_required
def chat_stream():
    data = request.get_json(silent=True) or {}
    if not isinstance(data, dict):
        return jsonify({'error': 'Invalid request'}), 400
    gate_resp = _bot_turnstile_gate(data.get('turnstile_token'))
    if gate_resp is not None:
        return gate_resp
    raw_message = data.get('message')
    if not isinstance(raw_message, str) or len(raw_message) > 500_000:
        return jsonify({'error': 'Invalid or oversized message'}), 400
    # Allow image/file-only sends (no prompt text) as long as attachments are present.
    raw_img_hint = data.get('image_urls') or []
    if not isinstance(raw_img_hint, list):
        raw_img_hint = [raw_img_hint]
    has_attachment_hint = bool([u for u in raw_img_hint if u]) or bool(data.get('image_items')) or bool(data.get('uploaded_image_urls'))
    if not raw_message.strip() and not has_attachment_hint:
        return jsonify({'error': 'Invalid or oversized message'}), 400
    client_request_id = str(data.get('client_request_id') or '').strip()
    if client_request_id and not re.fullmatch(r'[A-Za-z0-9_-]{8,64}', client_request_id):
        return jsonify({'error': 'Invalid client request ID'}), 400
    model_key = str(data.get('model') or '').strip()
    if model_key not in ALL_VALID_MODEL_IDS:
        return jsonify({'error': 'Invalid model'}), 400
    coding_mode = data.get('coding_mode') is True
    coding_target = data.get('coding_target')
    coding_candidates = []
    if coding_mode:
        if any(marker in model_key.lower() for marker in ("image", "video", "tts", "audio", "native-audio")):
            return jsonify({'error': 'Coding Mode requires a text generation model'}), 400
        if not isinstance(coding_target, dict):
            return jsonify({'error': 'Coding Mode target is required'}), 400
        raw_candidates = data.get('coding_candidates')
        if not isinstance(raw_candidates, list) or not raw_candidates or len(raw_candidates) > 30:
            return jsonify({'error': 'Coding Mode candidates are required'}), 400
        prompt_blocks = extract_markdown_code_blocks(raw_message)
        candidate_ids = set()
        total_candidate_chars = 0
        for raw_candidate in raw_candidates:
            if not isinstance(raw_candidate, dict):
                return jsonify({'error': 'Invalid Coding Mode candidate'}), 400
            candidate_id = str(raw_candidate.get('id') or '')[:100]
            if not re.fullmatch(r'[A-Za-z0-9_-]{1,100}', candidate_id) or candidate_id in candidate_ids:
                return jsonify({'error': 'Invalid Coding Mode candidate ID'}), 400
            candidate_ids.add(candidate_id)
            source = 'prompt' if raw_candidate.get('source') == 'prompt' else 'history'
            if source == 'prompt':
                try:
                    prompt_index = int(raw_candidate.get('prompt_index'))
                except (TypeError, ValueError):
                    return jsonify({'error': 'Invalid prompt code block index'}), 400
                if prompt_index < 0 or prompt_index >= len(prompt_blocks):
                    return jsonify({'error': 'Prompt code block was not found'}), 400
                code = prompt_blocks[prompt_index]['code']
                language = prompt_blocks[prompt_index]['language']
            else:
                code = raw_candidate.get('code')
                language = raw_candidate.get('language') or 'text'
            if not isinstance(code, str) or not code.strip() or len(code) > 300_000:
                return jsonify({'error': 'Invalid or oversized Coding Mode target'}), 400
            total_candidate_chars += len(code)
            if total_candidate_chars > 300_000:
                return jsonify({'error': 'Coding Mode candidates are too large'}), 400
            coding_candidates.append({
                'id': candidate_id,
                'code': code,
                'language': re.sub(r'[^A-Za-z0-9_+.#-]', '', str(language))[:40] or 'text',
                'source': source,
                'explicit': raw_candidate.get('explicit') is True,
            })
        default_target_id = str(coding_target.get('id') or '')[:100]
        if default_target_id not in candidate_ids:
            default_target_id = coding_candidates[-1]['id']
        default_candidate = next(item for item in coding_candidates if item['id'] == default_target_id)
        coding_target = {
            **default_candidate,
            'default_target_id': default_target_id,
            'explicit': (
                coding_target.get('explicit') is True
                and len(coding_candidates) == 1
                and default_target_id == coding_candidates[0]['id']
            ),
        }
    resolved_auth = _resolve_chat_model_auth(current_user, model_key)
    if resolved_auth.get("error_code"):
        return jsonify({
            "error": resolved_auth.get("error") or "APIキーが設定されていません。",
            "code": resolved_auth["error_code"],
            "model": model_key,
            "provider": resolved_auth.get("provider"),
        }), 400
    for bounded_key in ('quote_text', 'system_prompt', 'marker_system_prompt', 'thread_custom_instruction'):
        bounded_value = data.get(bounded_key)
        if bounded_value is not None and len(str(bounded_value)) > 100_000:
            return jsonify({'error': f'{bounded_key} is too large'}), 400
    user_config = {'enable_e2ee': current_user.enable_e2ee}
    job_id = f"job_{int(time.time())}_{current_user.id}_{secrets.token_hex(8)}"
    _latency_mark_once(job_id, "route_received_ms")

    temporary_requested = _coerce_bool_or_none(data.get('temporary_chat'))
    thread_ref = data.get('thread_id')
    thread_was_created = False
    if thread_ref:
        t = resolve_thread_for_user(thread_ref, current_user.id)
        if not t:
            return jsonify({'error': 'Invalid thread'}), 403
        if temporary_requested is not None:
            t.is_temporary = bool(temporary_requested)
    else:
        # Avoid a separate round trip on first send; create the thread in the same transaction.
        t = Thread(
            user_id=current_user.id,
            public_id=generate_thread_public_id(),
            is_temporary=bool(temporary_requested)
        )
        db.session.add(t)
        thread_was_created = True
    thread_id = t.id
    thread_stream_id = t.public_id if t and t.public_id else None

    # Prompt-cache provider lock: reject before saving the user message
    enable_pc_request = bool(data.get('enable_prompt_caching'))
    provider_for_pc = get_model_api_provider(data.get('model'))
    locked_provider = getattr(t, 'prompt_cache_provider', None)
    if enable_pc_request and locked_provider and provider_for_pc and locked_provider != provider_for_pc:
        locked_label = _PROVIDER_LABELS.get(locked_provider, locked_provider)
        next_label = _PROVIDER_LABELS.get(provider_for_pc, provider_for_pc)
        return jsonify({
            'error': f'PromptCache有効中は他API（{next_label}）のモデルに変更できません。ロック中: {locked_label}'
        }), 400
    submission_claimed, existing_submission = _claim_chat_submission(current_user.id, client_request_id)
    if not submission_claimed:
        if existing_submission and existing_submission.get("state") == "accepted":
            return jsonify({
                "error": "This prompt was already accepted",
                "code": "request_already_accepted",
                "job_id": existing_submission.get("job_id"),
                "thread_id": existing_submission.get("thread_id"),
                "message_id": existing_submission.get("message_id"),
                "model": existing_submission.get("model") or model_key,
            }), 409
        return jsonify({
            "error": "This prompt is still being accepted",
            "code": "submission_in_progress",
        }), 425
    
    user_msg = None
    attachment_name_map = {}
    try:
        raw_msg_content = raw_message
        msg_content = raw_msg_content
        if user_config['enable_e2ee']: msg_content = encrypt_val(msg_content)
        raw_image_urls = data.get('image_urls') or []
        if not isinstance(raw_image_urls, list):
            raw_image_urls = [raw_image_urls]
        norm_image_urls = _normalize_attachment_list(raw_image_urls, current_user.id)
        raw_image_items = data.get('image_items') or []
        if not isinstance(raw_image_items, list):
            raw_image_items = [raw_image_items]
        uploaded_image_refs = []
        for item in raw_image_items:
            if not isinstance(item, dict):
                continue
            ref = item.get('path') or item.get('filepath') or item.get('url') or item.get('file')
            norm_ref = _normalize_upload_ref(ref)
            if norm_ref and norm_ref.startswith(f"{current_user.id}/"):
                raw_name = item.get('name') or item.get('filename') or item.get('display_name')
                norm_name = _normalize_display_name_for_path(norm_ref, raw_name)
                if norm_name:
                    attachment_name_map[norm_ref] = norm_name
            source = _normalize_attachment_source(item.get('source'))
            if source == "upload" and ref:
                uploaded_image_refs.append(ref)
        explicit_uploaded_refs = data.get('uploaded_image_urls') or []
        if isinstance(explicit_uploaded_refs, list):
            uploaded_image_refs.extend(explicit_uploaded_refs)
        elif explicit_uploaded_refs:
            uploaded_image_refs.append(explicit_uploaded_refs)
        max_files = int(app.config.get('ATTACHMENT_MAX_FILES') or 30)
        if len(norm_image_urls) > max_files:
            _release_chat_submission(current_user.id, client_request_id)
            return jsonify({'error': f'Too many attachments. Max {max_files} files per message.'}), 400
        
        parent_id = data.get('parent_id', None)
        parent_explicit = data.get('parent_id_explicit', False)
        if isinstance(parent_explicit, str):
            parent_explicit = parent_explicit.strip().lower() in ("1", "true", "yes", "on")
        else:
            parent_explicit = bool(parent_explicit)

        if parent_id is not None and parent_id != "":
            try:
                if isinstance(parent_id, str) and parent_id.strip().lower() in ("null", "none", "root"):
                    parent_id = None
                else:
                    parent_id_int = int(parent_id)
                    if parent_id_int <= 0:
                        parent_id = None
                    else:
                        pm = Message.query.get(parent_id_int)
                        if not pm or pm.thread_id != thread_id or pm.thread.user_id != current_user.id:
                            parent_id = None
                        else:
                            parent_id = pm.id
            except Exception:
                parent_id = None

        if parent_id is None and not parent_explicit and not thread_was_created and t.id is not None:
            # Default to the last message in the thread
            last_msg = Message.query.filter_by(thread_id=t.id).order_by(Message.id.desc()).first()
            if last_msg:
                parent_id = last_msg.id

        # Calculate user tokens on send to avoid worker re-counting.
        user_tokens_in = None
        if user_tokens_in is None:
            user_tokens_in = count_tokens(raw_msg_content or "", data.get('model'))
        gem_uuid_val = data.get('gem_uuid')
        gem_name_val = None
        if gem_uuid_val:
            gem = Gem.query.filter_by(uuid=gem_uuid_val, user_id=current_user.id).first()
            if gem:
                gem_name_val = gem.name
        user_msg = Message(
            thread=t,
            role='user',
            content=msg_content,
            model=model_key,
            image_url=json.dumps(norm_image_urls) if norm_image_urls else None,
            quote_text=data.get('quote_text'),
            is_encrypted=user_config['enable_e2ee'],
            parent_id=parent_id,
            tokens_in=user_tokens_in,
            tokens=sum_token_counts(user_tokens_in, None),
            gem_uuid=gem_uuid_val,
            gem_name=gem_name_val
        )
        db.session.add(user_msg)
        if current_user.use_last_chat_settings:
            current_user.last_model = data.get('model')
            current_user.last_enable_search = bool(data.get('enable_search'))
            current_user.last_enable_url_context = bool(data.get('enable_url_context'))
            current_user.last_enable_maps = bool(data.get('enable_maps'))
            current_user.last_enable_python = bool(data.get('enable_python'))
            current_user.last_enable_thinking = bool(data.get('enable_thinking'))
            current_user.last_thinking_level = (data.get('thinking_level') or current_user.last_thinking_level or "high")
            tb = data.get('thinking_budget')
            try:
                if tb is not None and str(tb).strip() != "":
                    current_user.last_thinking_budget = int(tb)
            except Exception:
                pass
            current_user.last_reasoning_effort = (data.get('reasoning_effort') or current_user.last_reasoning_effort or "medium")
            current_user.last_enable_system_prompt = bool(data.get('enable_system_prompt'))
            current_user.last_safety_setting = (data.get('safety_setting') or current_user.last_safety_setting or "default")
        t.last_gem_uuid = data.get('gem_uuid')
        safe_db_commit()
        thread_id = t.id
        thread_stream_id = t.public_id if t and t.public_id else str(thread_id)
        if bool(getattr(t, "is_temporary", False)):
            _mark_temp_chat_presence(
                t,
                current_user.id,
                timeout_seconds=_get_user_temp_chat_timeout_seconds(current_user)
            )
            _track_temp_chat_uploaded_refs(t, current_user.id, uploaded_image_refs)
        elif temporary_requested is False:
            _clear_temp_chat_tracking_for_thread(t)
    except Exception as e:
        logger.error(f"Failed to save user msg: {e}")
        _release_chat_submission(current_user.id, client_request_id)
        return jsonify({'error': 'Failed to save message'}), 500

    quote_text = data.get('quote_text')
    if quote_text:
        try:
            redis_conn.setex(f"quote:{job_id}", 600, quote_text)
        except: pass

    sys_prompt = data.get('system_prompt')
    if sys_prompt:
        try:
            redis_conn.setex(f"sys:{job_id}", 600, sys_prompt)
        except: pass

    options = {
        'system_prompt': None,
        'enable_search': data.get('enable_search'),
        'enable_url_context': data.get('enable_url_context'),
        'disable_auto_search': data.get('disable_auto_search'),
        'enable_python': data.get('enable_python'),
        'enable_thinking': data.get('enable_thinking'),
        'thinking_level': data.get('thinking_level'),
        'thinking_budget': data.get('thinking_budget'),
        'reasoning_effort': data.get('reasoning_effort'),
        'enable_system_prompt': data.get('enable_system_prompt'),
        'marker_system_prompt': data.get('marker_system_prompt'),
        'safety_setting': data.get('safety_setting'),
        'tts_voice': data.get('tts_voice'),
        'tts_voice_custom': data.get('tts_voice_custom'),
        'tts_language': data.get('tts_language'),
        'tts_speed': data.get('tts_speed'),
        'image_size': data.get('image_size'),
        'image_quality': data.get('image_quality'),
        'image_format': data.get('image_format'),
        'image_compression': data.get('image_compression'),
        'image_mask': data.get('image_mask'),
        'gemini_image_aspect': data.get('gemini_image_aspect'),
        'gemini_image_size': data.get('gemini_image_size'),
        'grok_image_aspect': data.get('grok_image_aspect'),
        'grok_image_resolution': data.get('grok_image_resolution'),
        'grok_image_quality': data.get('grok_image_quality'),
        'grok_image_format': data.get('grok_image_format'),
        'grok_image_count': data.get('grok_image_count'),
        'xai_temperature': data.get('xai_temperature'),
        'xai_top_p': data.get('xai_top_p'),
        'xai_max_completion_tokens': data.get('xai_max_completion_tokens'),
        'xai_seed': data.get('xai_seed'),
        'xai_presence_penalty': data.get('xai_presence_penalty'),
        'xai_frequency_penalty': data.get('xai_frequency_penalty'),
        'xai_stop': data.get('xai_stop'),
        'xai_response_format': data.get('xai_response_format'),
        'xai_tool_choice': data.get('xai_tool_choice'),
        'xai_parallel_tool_calls': data.get('xai_parallel_tool_calls'),
        'xai_logprobs': data.get('xai_logprobs'),
        'xai_top_logprobs': data.get('xai_top_logprobs'),
        'grok_video_duration': data.get('grok_video_duration'),
            'grok_video_aspect': data.get('grok_video_aspect'),
            'grok_video_resolution': data.get('grok_video_resolution'),
            'ocr_table_format': data.get('ocr_table_format'),
            'ocr_extract_header': data.get('ocr_extract_header'),
            'ocr_extract_footer': data.get('ocr_extract_footer'),
            'ocr_include_blocks': data.get('ocr_include_blocks'),
            'ocr_include_image_base64': data.get('ocr_include_image_base64'),
            'ocr_pages': data.get('ocr_pages'),
            'transcription_language_codes': data.get('transcription_language_codes'),
            'transcription_custom_vocabulary': data.get('transcription_custom_vocabulary'),
            'transcription_mode': data.get('transcription_mode'),
            'transcription_diarization': data.get('transcription_diarization'),
            'transcription_word_timestamps': data.get('transcription_word_timestamps'),
            'attachment_name_map': attachment_name_map,
            'image_vision_model': data.get('image_vision_model'),
            'gem_uuid': data.get('gem_uuid'),
            'enable_prompt_caching': enable_pc_request,
            'prompt_cache_key': None,
            'coding_mode': coding_mode,
            'coding_target': coding_target if coding_mode else None,
            'coding_candidates': coding_candidates if coding_mode else [],
        }
    # Persist prompt-cache flags on the thread (provider locked while enabled)
    try:
        if enable_pc_request:
            t.enable_prompt_caching = True
            if provider_for_pc:
                t.prompt_cache_provider = provider_for_pc
            cache_id = t.public_id or str(t.id)
            options['prompt_cache_key'] = f"thread-{cache_id}"
        else:
            t.enable_prompt_caching = False
            t.prompt_cache_provider = None
        db.session.add(t)
        safe_db_commit()
    except Exception as e:
        logger.warning(f"prompt caching thread flags update failed: {e}")
    if 'thread_custom_instruction' in data:
        options['thread_custom_instruction'] = data.get('thread_custom_instruction')

    model_key = str(data.get('model') or '').strip()
    model_key_l = model_key.lower()
    no_attachments = not bool(norm_image_urls)
    low_latency_image_attachments = _is_low_latency_image_attachment_set(norm_image_urls)
    model_looks_heavy = any(x in model_key_l for x in ("image", "video", "tts", "audio", "native-audio"))

    # Every generation runs outside gunicorn so a web-service restart cannot
    # terminate an in-process daemon thread. Small text/image requests retain
    # the low-latency fast queue; only the unsafe direct execution is removed.
    fast_queue_eligible = bool(
        not model_looks_heavy
        and (no_attachments or low_latency_image_attachments)
    )
    queue_name = _CHAT_FAST_QUEUE_NAME if fast_queue_eligible else _CHAT_HEAVY_QUEUE_NAME
    execution_path = "queued_fast" if fast_queue_eligible else "queued_heavy"
    try:
        redis_conn.hset(
            _latency_trace_key(job_id),
            mapping={
                "execution_path": execution_path,
                "queue_name": queue_name[:64],
                "model": model_key[:80],
                "thread_public_id": (thread_stream_id or "")[:64],
                "user_id": str(current_user.id),
            }
        )
        redis_conn.expire(_latency_trace_key(job_id), _LATENCY_TRACE_TTL_SECONDS)
    except Exception:
        pass

    enqueue_queue = chat_fast_queue if queue_name == _CHAT_FAST_QUEUE_NAME else chat_heavy_queue
    enqueue_queue.enqueue(
        background_chat_task,
        job_id,
        thread_id,
        data.get('model'),
        user_msg.id,
        options,
        current_user.id,
        user_config,
        job_timeout=600,
        at_front=(queue_name == _CHAT_FAST_QUEUE_NAME)
    )
    _latency_mark_once(job_id, "route_dispatch_ms")
    try:
        redis_conn.setex(
            f"pending_job:{current_user.id}:{thread_id}",
            600,
            json.dumps({
                "job_id": job_id,
                "message_id": user_msg.id,
                "created_at": int(time.time()),
                "model": data.get('model')
            })
        )
    except Exception:
        pass
    try:
        if queue_name == _CHAT_FAST_QUEUE_NAME:
            redis_conn.setex(f"stream_acc:{job_id}:status", 600, "高速キューに投入しました。優先ワーカー待機中です...")
        else:
            redis_conn.setex(f"stream_acc:{job_id}:status", 600, "通常キューに投入しました。ワーカー待機中です...")
    except Exception:
        pass

    # Publish the accepted job before opening the stream. A retry after an
    # ambiguous disconnect can resume this exact job instead of creating a
    # second user message.
    _complete_chat_submission(
        current_user.id,
        client_request_id,
        job_id,
        thread_stream_id,
        user_msg.id,
        model_key,
    )

    def generate():
        pubsub = redis_conn.pubsub()
        channel = f"ai_chat:channel:{job_id}"
        pubsub.subscribe(channel)
        start_time = time.time()
        _latency_mark_once(job_id, "route_stream_open_ms")
        if thread_stream_id:
            yield json.dumps({"type": "thread_id", "content": thread_stream_id}) + "\n"
        yield json.dumps({"type": "job_id", "content": job_id}) + "\n"
        try:
            cached_status = redis_conn.get(f"stream_acc:{job_id}:status")
            if cached_status:
                _latency_mark_once(job_id, "stream_first_status_to_client_ms")
                yield json.dumps({"type": "status", "content": cached_status.decode("utf-8", "ignore")}) + "\n"
            cached_coding_diffs = redis_conn.lrange(f"stream_acc:{job_id}:coding_diff", 0, -1)
            for raw_diff in cached_coding_diffs:
                try:
                    yield json.dumps({
                        "type": "coding_diff",
                        "content": json.loads(raw_diff),
                    }, ensure_ascii=False) + "\n"
                except Exception:
                    continue
        except Exception:
            pass
        try:
            refresh_count = 0
            for message in pubsub.listen():
                if time.time() - start_time > 600: break
                refresh_count += 1
                if refresh_count % 20 == 0:
                    try:
                        redis_conn.expire(f"pending_job:{current_user.id}:{thread_id}", 600)
                    except Exception:
                        pass
                if message['type'] == 'message':
                    _latency_mark_once(job_id, "stream_first_pubsub_ms")
                    evt = json.loads(message['data'])
                    evt_type = str(evt.get('type') or '')
                    if evt_type == "status":
                        _latency_mark_once(job_id, "stream_first_status_to_client_ms")
                    elif evt_type == "thought":
                        _latency_mark_once(job_id, "stream_first_thought_to_client_ms")
                    elif evt_type == "content":
                        _latency_mark_once(job_id, "stream_first_content_to_client_ms")
                    yield json.dumps(evt) + "\n"
                    if evt_type in ['done', 'error']:
                        _latency_mark_once(job_id, "stream_done_ms")
                        break
        finally:
            _latency_mark_once(job_id, "stream_done_ms")
            pubsub.unsubscribe()
            _upsert_chat_latency_trace(
                job_id=job_id,
                user_id=current_user.id,
                thread_public_id=thread_stream_id,
                model=model_key,
                execution_path=execution_path
            )
    resp = Response(stream_with_context(generate()), mimetype='application/x-ndjson')
    resp.headers['Cache-Control'] = 'no-cache, no-transform'
    resp.headers['X-Accel-Buffering'] = 'no'
    return resp


@app.route('/api/token_estimate', methods=['POST'])
@login_required
def estimate_prompt_tokens_api():
    data = request.get_json(silent=True) or {}
    model_key = str(data.get('model') or '')
    message_text = data.get('message')
    quote_text = data.get('quote_text')
    raw_image_urls = data.get('image_urls') or []
    if not isinstance(raw_image_urls, list):
        raw_image_urls = [raw_image_urls]

    if message_text is None:
        message_text = ''
    else:
        message_text = str(message_text)
    if quote_text is None:
        quote_text = ''
    else:
        quote_text = str(quote_text)

    norm_image_urls = _normalize_attachment_list(raw_image_urls, current_user.id)
    max_files = int(app.config.get('ATTACHMENT_MAX_FILES') or 30)
    if len(norm_image_urls) > max_files:
        norm_image_urls = norm_image_urls[:max_files]
    if quote_text:
        message_for_count = f"Context (User Quote):\n\"\"\"\n{quote_text}\n\"\"\"\n\nUser Message:\n{message_text}"
    else:
        message_for_count = message_text

    if not should_count_tokens_for_display(model_key):
        return jsonify({
            'countable': False,
            'tokens_total': None,
            'tokens_prompt': None,
            'tokens_files': None,
            'files_total': len(norm_image_urls),
            'files_counted': 0,
            'files_non_text': 0,
            'files_missing': 0,
            'files_error': 0
        })

    prompt_tokens = count_tokens(message_for_count or "", model_key)
    file_tokens = 0
    files_counted = 0
    files_non_text = 0
    files_missing = 0
    files_error = 0

    for rel_path in norm_image_urls:
        est = _estimate_attachment_prompt_tokens(rel_path, model_key=model_key)
        tok = int(est.get("tokens") or 0)
        file_tokens += tok
        reason = est.get("reason")
        if est.get("countable"):
            files_counted += 1
        elif reason == "missing":
            files_missing += 1
        elif reason in ("non_text", "no_text"):
            files_non_text += 1
        else:
            files_error += 1

    return jsonify({
        'countable': True,
        'tokens_total': prompt_tokens + file_tokens,
        'tokens_prompt': prompt_tokens,
        'tokens_files': file_tokens,
        'files_total': len(norm_image_urls),
        'files_counted': files_counted,
        'files_non_text': files_non_text,
        'files_missing': files_missing,
        'files_error': files_error
    })


@app.route('/chat_stream_resume', methods=['POST'])
@login_required
def chat_stream_resume():
    data = request.get_json(silent=True) or {}
    gate_resp = _bot_turnstile_gate(data.get('turnstile_token'))
    if gate_resp is not None:
        return gate_resp
    job_id = str(data.get('job_id') or '')
    thread_id = data.get('thread_id')
    if not _is_valid_job_id(job_id) or not thread_id:
        return jsonify({'error': 'job_id and thread_id required'}), 400
    t = resolve_thread_for_user(thread_id, current_user.id)
    if not t:
        return jsonify({'error': 'Invalid thread'}), 403
    pending_raw = None
    try:
        pending_raw = redis_conn.get(f"pending_job:{current_user.id}:{t.id}")
    except Exception:
        pending_raw = None
    if not pending_raw:
        # 接続エラー後のリロードで一時的にセッション読込不能になるのを防ぐため、古いpendingをクリア
        try:
            redis_conn.delete(f"pending_job:{current_user.id}:{t.id}")
        except Exception:
            pass
        return jsonify({'error': 'no pending job'}), 404
    pending_job = None
    try:
        pending_job = json.loads(pending_raw)
    except Exception:
        try:
            pending_job = {"job_id": pending_raw.decode("utf-8", "ignore")}
        except Exception:
            pending_job = None
    if pending_job and pending_job.get('job_id') and pending_job.get('job_id') != job_id:
        return jsonify({'error': 'job mismatch'}), 404

    def generate():
        pubsub = redis_conn.pubsub()
        channel = f"ai_chat:channel:{job_id}"
        pubsub.subscribe(channel)
        start_time = time.time()
        yield json.dumps({"type": "job_id", "content": job_id}) + "\n"
        try:
            cached_status = redis_conn.get(f"stream_acc:{job_id}:status")
            if cached_status:
                yield json.dumps({"type": "status", "content": cached_status.decode("utf-8", "ignore")}) + "\n"
            cached_thought = redis_conn.get(f"stream_acc:{job_id}:thought")
            if cached_thought:
                yield json.dumps({"type": "thought", "content": cached_thought.decode("utf-8", "ignore")}) + "\n"
            cached_content = redis_conn.get(f"stream_acc:{job_id}:content")
            if cached_content:
                yield json.dumps({"type": "content", "content": cached_content.decode("utf-8", "ignore")}) + "\n"
            cached_coding_diffs = redis_conn.lrange(f"stream_acc:{job_id}:coding_diff", 0, -1)
            for raw_diff in cached_coding_diffs:
                try:
                    yield json.dumps({
                        "type": "coding_diff",
                        "content": json.loads(raw_diff),
                    }, ensure_ascii=False) + "\n"
                except Exception:
                    continue
            cached_search = redis_conn.get(f"stream_acc:{job_id}:search")
            if cached_search:
                yield json.dumps({"type": "search_status", "content": cached_search.decode("utf-8", "ignore")}) + "\n"
            cached_py = redis_conn.hgetall(f"stream_acc:{job_id}:python")
            if cached_py:
                for _, raw in cached_py.items():
                    try:
                        py = json.loads(raw)
                        yield json.dumps({"type": "python", "content": py}) + "\n"
                    except Exception:
                        continue
            cached_final = redis_conn.get(f"stream_acc:{job_id}:final")
            if cached_final:
                final_type = cached_final.decode("utf-8", "ignore").strip().lower()
                if final_type == "error":
                    cached_error = redis_conn.get(f"stream_acc:{job_id}:error")
                    if cached_error:
                        yield cached_error.decode("utf-8", "ignore") + "\n"
                    else:
                        yield json.dumps({"type": "error", "content": "The job has ended with an error. Please reload."}) + "\n"
                else:
                    yield json.dumps({"type": "done", "content": "OK"}) + "\n"
                return
        except Exception:
            pass
        try:
            refresh_count = 0
            for message in pubsub.listen():
                if time.time() - start_time > 600: break
                refresh_count += 1
                if refresh_count % 20 == 0:
                    try:
                        redis_conn.expire(f"pending_job:{current_user.id}:{t.id}", 600)
                    except Exception:
                        pass
                if message['type'] == 'message':
                    data = json.loads(message['data'])
                    yield json.dumps(data) + "\n"
                    if data.get('type') in ['done', 'error']: break
        finally:
            pubsub.unsubscribe()
    resp = Response(stream_with_context(generate()), mimetype='application/x-ndjson')
    resp.headers['Cache-Control'] = 'no-cache, no-transform'
    resp.headers['X-Accel-Buffering'] = 'no'
    return resp

@app.route('/api/stop_chat', methods=['POST'])
@login_required
def stop_chat():
    data = request.get_json(silent=True) or {}
    requested_job_id = str(data.get('job_id') or '') or None
    if requested_job_id and not _is_valid_job_id(requested_job_id):
        return jsonify({'error': 'invalid job_id'}), 400
    thread_ref = data.get('thread_id')
    t = resolve_thread_for_user(thread_ref, current_user.id) if thread_ref else None
    if not t:
        return jsonify({'error': 'valid thread_id required'}), 400
    pending_job_id = _pending_job_id_for_thread(current_user.id, t.id)
    if requested_job_id and pending_job_id != requested_job_id:
        return jsonify({'error': 'job mismatch'}), 404
    job_id = requested_job_id or pending_job_id
    stop_source = 'job_id' if requested_job_id else 'thread_id'
    
    log_force(f"STREAM-STOP-SIGNAL: Received stop request for job_id={job_id} via {stop_source}")
    if job_id:
        redis_conn.set(f"stop_job:{job_id}", "1", ex=300)
        return jsonify({'status': 'stopped', 'job_id': job_id, 'source': stop_source})
    return jsonify({'error': 'no job_id', 'detail': 'pending job not found'}), 400

@app.route('/api/temporary_chat/heartbeat', methods=['POST'])
@login_required
def temporary_chat_heartbeat():
    data = request.json or {}
    thread_ref = data.get('thread_id')
    t = resolve_thread_for_user(thread_ref, current_user.id)
    if not t:
        return jsonify({'error': 'Invalid thread'}), 404
    active = _coerce_bool_or_none(data.get('active'))
    if active is None:
        active = True
    if active and bool(getattr(t, "is_temporary", False)):
        _mark_temp_chat_presence(
            t,
            current_user.id,
            timeout_seconds=_get_user_temp_chat_timeout_seconds(current_user)
        )
    temp_meta = _get_temp_chat_runtime_meta(t, user=current_user)
    return jsonify({
        'status': 'ok',
        'thread_id': t.public_id or t.id,
        'is_temporary': bool(getattr(t, "is_temporary", False)),
        'timeout_seconds': temp_meta.get('timeout_seconds'),
        'temp_chat_expires_at': temp_meta.get('temp_chat_expires_at'),
        'temp_chat_remaining_seconds': temp_meta.get('temp_chat_remaining_seconds')
    })

@app.route('/api/generate_title', methods=['POST'])
@login_required
def generate_title_api():
    """Auto-generate chat title with multi-model fallback, prioritizing requested model"""
    try:
        data = request.get_json(silent=True) or {}
        thread_id = data.get('thread_id')
        requested_model = str(data.get('model_id') or '').strip() or None
        if requested_model and requested_model not in ALL_VALID_MODEL_IDS:
            return jsonify({'error': 'Invalid model'}), 400
        
        thread = resolve_thread_for_user(thread_id, current_user.id)
        if not thread:
            return jsonify({'error': 'Unauthorized'}), 403

        first_msg = Message.query.filter_by(thread_id=thread.id, role='user').order_by(Message.timestamp).first()
        if not first_msg: return jsonify({'status': 'skipped'})
        
        content = decrypt_val(first_msg.content) if first_msg.is_encrypted else first_msg.content
        title = "New Chat"

        # Determine target provider for requested_model
        primary_provider = None
        if requested_model:
            rml = requested_model.lower()
            if is_mistral_ocr_model_key(rml):
                primary_provider = None
            elif "gemini" in rml: primary_provider = "gemini"
            elif "grok" in rml: primary_provider = "xai"
            elif "deepseek" in rml: primary_provider = "deepseek"
            else: primary_provider = "openai"

        # Preparation
        o_key = (
            _get_model_specific_api_key(current_user, "gpt-4o-mini")
            or decrypt_val(current_user.openai_api_key)
            or (os.getenv('OPENAI_API_KEY') if _admin_env_fallback_enabled(current_user) else None)
        )
        gemini_runtime = _resolve_gemini_runtime(current_user)
        g_key = _get_model_specific_api_key(current_user, "gemini-2.0-flash-lite-preview") or gemini_runtime.get("api_key")
        x_key = (
            _get_model_specific_api_key(current_user, "grok-beta")
            or decrypt_val(current_user.xai_api_key)
            or (os.getenv('XAI_API_KEY') if _admin_env_fallback_enabled(current_user) else None)
        )
        d_key = (
            _get_model_specific_api_key(current_user, requested_model or "deepseek-v4-flash-0731")
            or _get_model_specific_api_key(current_user, "deepseek-v4-flash-0731")
            or decrypt_val(current_user.deepseek_api_key)
            or (os.getenv('DEEPSEEK_API_KEY') if _admin_env_fallback_enabled(current_user) else None)
        )

        # 1. Try Primary requested provider/model
        if primary_provider == "openai" and o_key:
            try:
                client = _get_openai_client(o_key, base_url=None)
                resp = client.chat.completions.create(
                    model=requested_model,
                    messages=[
                        {"role": "system", "content": "Generate a short title (max 6 words) for this chat. Output only the title text."},
                        {"role": "user", "content": content[:500]}
                    ],
                    max_tokens=20
                )
                if resp.choices[0].message.content:
                    title = resp.choices[0].message.content.strip().replace('"', '')
            except: pass
        elif primary_provider == "gemini":
            try:
                backend = gemini_runtime.get("backend")
                if (backend == "gemini_api" and bool(g_key)) or (backend == "vertex_ai"):
                    g_client = _get_gemini_client(api_key=g_key, backend=backend, vertex_project=gemini_runtime.get("vertex_project"), vertex_location=gemini_runtime.get("vertex_location"), vertex_credentials_json=gemini_runtime.get("vertex_credentials_json"))
                    if g_client:
                        resp = g_client.models.generate_content(
                            model=requested_model,
                            contents=[types.Part(text=f"Generate a short title (max 6 words) for this chat. Output only the title text.\n\nChat: {content[:500]}")]
                        )
                        if resp.text:
                            title = resp.text.strip().replace('"', '')
            except: pass
        elif primary_provider == "xai" and x_key and XAI_SDK_AVAILABLE:
            try:
                x_client = XAIClient(api_key=x_key)
                chat = x_client.chat.create(model=requested_model)
                chat.append(x_system("Generate a short, descriptive title (max 6 words) for this chat conversation. Output only the title text."))
                chat.append(x_user(content[:500]))
                resp = chat.sample()
                if resp and resp.message and resp.message.content:
                    title = resp.message.content.strip().replace('"', '')
            except: pass
        elif primary_provider == "deepseek" and d_key:
            try:
                client = _get_openai_client(d_key, base_url="https://api.deepseek.com")
                resp = client.chat.completions.create(
                    model=_deepseek_api_model_id(requested_model),
                    messages=[
                        {"role": "system", "content": "Generate a short title (max 6 words) for this chat. Output only the title text."},
                        {"role": "user", "content": content[:500]}
                    ],
                    max_tokens=20,
                    extra_body={"thinking": {"type": "disabled"}}
                )
                if resp.choices and resp.choices[0].message and resp.choices[0].message.content:
                    title = str(resp.choices[0].message.content).strip().replace('"', '')
            except: pass

        # 2. Fallbacks if still "New Chat"
        if title == "New Chat":
            # Try OpenAI (gpt-4o-mini)
            if o_key:
                try:
                    client = _get_openai_client(o_key, base_url=None)
                    resp = client.chat.completions.create(
                        model="gpt-4o-mini",
                        messages=[
                            {"role": "system", "content": "Generate a short title (max 6 words) for this chat. Output JSON: {\"title\": \"...\"}"},
                            {"role": "user", "content": content[:500]}
                        ],
                        response_format={"type": "json_object"}
                    )
                    title = json.loads(resp.choices[0].message.content).get('title', 'New Chat')
                except: pass
            
            # Try Gemini (flash)
            if title == "New Chat":
                try:
                    backend = gemini_runtime.get("backend")
                    if (backend == "gemini_api" and bool(g_key)) or (backend == "vertex_ai"):
                        g_client = _get_gemini_client(api_key=g_key, backend=backend, vertex_project=gemini_runtime.get("vertex_project"), vertex_location=gemini_runtime.get("vertex_location"), vertex_credentials_json=gemini_runtime.get("vertex_credentials_json"))
                        if g_client:
                            resp = g_client.models.generate_content(
                                model="gemini-2.0-flash-lite-preview",
                                contents=[types.Part(text=f"Generate a short title (max 6 words) for this chat. JSON: {{'title': '...'}}\n\nChat: {content[:500]}")],
                                config=types.GenerateContentConfig(response_mime_type="application/json")
                            )
                            title = json.loads(resp.text).get('title', 'New Chat')
                except: pass

            # Try xAI (grok-beta)
            if title == "New Chat" and x_key and XAI_SDK_AVAILABLE:
                try:
                    x_client = XAIClient(api_key=x_key)
                    chat = x_client.chat.create(model="grok-beta")
                    chat.append(x_system("Generate a short, descriptive title (max 6 words) for this chat conversation. Output only the title text."))
                    chat.append(x_user(content[:500]))
                    resp = chat.sample()
                    if resp and resp.message and resp.message.content:
                        title = resp.message.content.strip()
                except: pass
            
        # 5. Final fallback if still "New Chat" or empty
        if title == "New Chat" or not title.strip():
            # Use content snippet as fallback title
            snippet = content[:50].strip().replace('\n', ' ')
            if snippet:
                title = snippet + ('...' if len(content) > 50 else '')
            else:
                title = "New Chat"

        title = _normalize_thread_title(title)
        thread.title = title
        safe_db_commit()
        return jsonify({'status': 'ok', 'title': title})
    except Exception as e:
        return jsonify({'error': str(e)}), 500

# -----------------------------------------------------------------------------
# Lyria RealTime studio API
# -----------------------------------------------------------------------------
@app.route('/api/gemini/music/start', methods=['POST'])
@login_required
def gemini_music_start():
    _lyria_purge_old_sessions()
    data = request.get_json(silent=True) or {}
    gemini_runtime = _resolve_gemini_runtime(current_user)
    if gemini_runtime.get("backend") == "vertex_ai":
        return jsonify({'error': 'Lyria RealTimeはVertex AIでは利用できません。Gemini APIキーを使用してください。'}), 400
    model_specific_key = _get_model_specific_api_key(current_user, LYRIA_REALTIME_MODEL)
    key = model_specific_key or gemini_runtime.get("api_key")
    if not key:
        return jsonify({'error': 'Gemini API Key not configured'}), 400

    prompts = _normalize_lyria_prompts(data.get("weighted_prompts"))
    if not prompts:
        return jsonify({'error': 'プロンプトを入力してください'}), 400
    config = _normalize_lyria_config(data.get("config"))

    session_id = f"lyria_{int(time.time())}_{secrets.token_hex(4)}"
    session = LyriaSession(session_id, current_user.id, key, prompts, config)
    thread = threading.Thread(target=_lyria_worker, args=(session,), daemon=True, name=f"lyria-{session_id}")
    session.thread = thread
    with LYRIA_SESSIONS_LOCK:
        LYRIA_SESSIONS[session_id] = session
    thread.start()
    return jsonify({'session_id': session_id})


@app.route('/api/gemini/music/stream')
@login_required
def gemini_music_stream():
    session = _lyria_get_session(request.args.get('session_id'))
    if not session:
        return jsonify({'error': 'Session not found'}), 404

    def generate():
        try:
            # Snapshot the audio accumulated so far so a reconnecting client can
            # reconstruct the full recording, then stream live deltas only.
            with session.audio_lock:
                snapshot_bytes = bytes(session.audio_buffer)
            with session.pending_cond:
                session.pending.clear()
            snapshot_b64 = base64.b64encode(snapshot_bytes).decode('ascii')
            yield f"data: {json.dumps({'snapshot': snapshot_b64, 'status': session.status})}\n\n"
            while True:
                with session.pending_cond:
                    while not session.pending and not session.stop_event.is_set() and session.status != "error":
                        session.pending_cond.wait(timeout=1.0)
                    pending = list(session.pending)
                    session.pending.clear()
                for delta in pending:
                    yield f"data: {json.dumps({'audio': delta})}\n\n"
                if session.status == "error":
                    yield f"data: {json.dumps({'error': session.error or 'Unknown error'})}\n\n"
                    break
                if session.stop_event.is_set() and not session.pending:
                    yield f"data: {json.dumps({'final': True, 'status': session.status})}\n\n"
                    break
        except GeneratorExit:
            pass
        except Exception:
            logger.exception("Lyria RealTime stream error")

    return Response(
        stream_with_context(generate()),
        mimetype='text/event-stream',
        headers={'Cache-Control': 'no-cache', 'X-Accel-Buffering': 'no'},
    )


@app.route('/api/gemini/music/command', methods=['POST'])
@login_required
def gemini_music_command():
    data = request.get_json(silent=True) or {}
    session = _lyria_get_session(data.get('session_id'))
    if not session:
        return jsonify({'error': 'Session not found'}), 404
    if session.status in ("closed", "error"):
        return jsonify({'error': 'セッションは終了しています'}), 400
    ctype = str(data.get('type') or '')
    if ctype not in ("prompts", "config", "control"):
        return jsonify({'error': 'Invalid command type'}), 400
    session.cmd_queue.put(data)
    return jsonify({'status': 'ok'})


@app.route('/api/gemini/music/cancel', methods=['POST'])
@login_required
def gemini_music_cancel():
    data = request.get_json(silent=True) or {}
    session = _lyria_get_session(data.get('session_id'))
    if not session:
        return jsonify({'error': 'Session not found'}), 404
    session.stop_event.set()
    try:
        if session.loop and session.ws:
            asyncio.run_coroutine_threadsafe(_lyria_send_control(session, "STOP"), session.loop).result(timeout=3)
    except Exception:
        pass
    if session.thread:
        session.thread.join(timeout=3)
    with LYRIA_SESSIONS_LOCK:
        LYRIA_SESSIONS.pop(session.session_id, None)
    return jsonify({'status': 'ok'})


@app.route('/api/gemini/music/save', methods=['POST'])
@login_required
def gemini_music_save():
    data = request.get_json(silent=True) or {}
    session = _lyria_get_session(data.get('session_id'))
    if not session:
        return jsonify({'error': 'Session not found'}), 404

    session.stop_event.set()
    try:
        if session.loop and session.ws:
            asyncio.run_coroutine_threadsafe(_lyria_send_control(session, "STOP"), session.loop).result(timeout=3)
    except Exception:
        pass
    if session.thread:
        session.thread.join(timeout=5)

    with session.audio_lock:
        pcm_bytes = bytes(session.audio_buffer)
    if len(pcm_bytes) < 1024:
        with LYRIA_SESSIONS_LOCK:
            LYRIA_SESSIONS.pop(session.session_id, None)
        return jsonify({'error': 'オーディオデータがありません。再生を少し進めてから保存してください。'}), 400

    wav_bytes = _lyria_pcm_to_wav_stereo(pcm_bytes, rate=48000)
    try:
        fname, audio_url = _save_user_generated_bytes_verified(
            current_user.id,
            wav_bytes,
            lambda: f"lyria_realtime_{int(time.time())}_{os.urandom(4).hex()}.wav",
            current_user.enable_e2ee,
        )
    except Exception as exc:
        logger.exception("Lyria RealTime save error")
        with LYRIA_SESSIONS_LOCK:
            LYRIA_SESSIONS.pop(session.session_id, None)
        return jsonify({'error': f'保存に失敗しました: {exc}'}), 500

    try:
        thread_id = data.get('thread_id')
        t = resolve_thread_for_user(thread_id, current_user.id) if thread_id else None
        if not t:
            t = Thread(
                user_id=current_user.id,
                public_id=generate_thread_public_id(),
                is_temporary=True,
            )
            db.session.add(t)
            safe_db_commit()
            thread_id = t.id
        else:
            thread_id = t.id

        prompt_lines = []
        for p in session.prompts:
            weight = float(p.get('weight', 1.0))
            prompt_lines.append(f"{p.get('text', '')} (weight: {weight})")
        prompt_text = "\n".join(prompt_lines) if prompt_lines else "Lyria RealTime 生成"
        audio_tag = f'\n<audio controls src="{audio_url}" class="w-full mt-2"></audio>\n'
        assistant_content = f"**Lyria RealTime 生成**\n\n{audio_tag}"
        if session.filtered_prompt:
            assistant_content += f"\n\n*プロンプトが安全フィルターにより調整されました。*"

        u_content = encrypt_val(prompt_text) if current_user.enable_e2ee else prompt_text
        a_content = encrypt_val(assistant_content) if current_user.enable_e2ee else assistant_content
        user_tokens_in = count_tokens_for_display(prompt_text, LYRIA_REALTIME_MODEL)
        assistant_tokens_out = count_tokens_for_display("Lyria RealTime 生成", LYRIA_REALTIME_MODEL)

        parent_id = None
        last_msg = Message.query.filter_by(thread_id=thread_id).order_by(Message.id.desc()).first()
        if last_msg:
            parent_id = last_msg.id

        user_msg = Message(
            thread_id=thread_id,
            role='user',
            content=u_content,
            is_encrypted=current_user.enable_e2ee,
            parent_id=parent_id,
            model=LYRIA_REALTIME_MODEL,
            tokens_in=user_tokens_in,
            tokens=sum_token_counts(user_tokens_in, None),
        )
        db.session.add(user_msg)
        safe_db_commit()

        assistant_msg = Message(
            thread_id=thread_id,
            role='assistant',
            content=a_content,
            model=LYRIA_REALTIME_MODEL,
            is_encrypted=current_user.enable_e2ee,
            parent_id=user_msg.id,
            tokens_out=assistant_tokens_out,
            tokens=sum_token_counts(None, assistant_tokens_out),
        )
        db.session.add(assistant_msg)
        safe_db_commit()
    except Exception as exc:
        logger.exception("Lyria RealTime message save error")
        with LYRIA_SESSIONS_LOCK:
            LYRIA_SESSIONS.pop(session.session_id, None)
        return jsonify({'error': f'音声は保存されましたが、メッセージ保存に失敗しました: {exc}', 'audio_url': audio_url}), 500

    with LYRIA_SESSIONS_LOCK:
        LYRIA_SESSIONS.pop(session.session_id, None)
    return jsonify({'status': 'ok', 'audio_url': audio_url, 'thread_id': str(thread_id)})


# -----------------------------------------------------------------------------
# True real-time STS session API (OpenAI Realtime / Grok Voice / Gemini native-audio)
# -----------------------------------------------------------------------------
@app.route('/api/realtime/start', methods=['POST'])
@login_required
def realtime_start():
    _rt_purge_old_sessions()
    data = request.get_json(silent=True) or {}
    model_key = (data.get('model') or "").strip()
    if not _rt_is_conversation_model(model_key):
        return jsonify({'error': 'このモデルはリアルタイム会話セッションに対応していません'}), 400
    model_key = XAI_STS_MODEL_ALIASES.get(model_key, model_key)
    provider = get_sts_provider(model_key)

    key, _ = _rt_resolve_api_key(current_user, model_key, provider)
    if not key:
        labels = {"google": "Gemini", "openai": "OpenAI", "xai": "xAI"}
        return jsonify({'error': f'{labels.get(provider, "API")} API Key not configured'}), 400

    params = _normalize_rt_params(provider, model_key, data)
    session_id = f"rt_{int(time.time())}_{secrets.token_hex(4)}"
    session = RtSession(session_id, current_user.id, model_key, key, params)
    thread = threading.Thread(target=_rt_worker, args=(session,), daemon=True, name=f"rt-{session_id}")
    session.thread = thread
    with RT_SESSIONS_LOCK:
        RT_SESSIONS[session_id] = session
    thread.start()
    return jsonify({
        'session_id': session_id,
        'rate_in': session.rate_in,
        'rate_out': session.rate_out,
        'provider': provider,
    })


@app.route('/api/realtime/stream')
@login_required
def realtime_stream():
    session = _rt_get_session(request.args.get('session_id'))
    if not session:
        return jsonify({'error': 'Session not found'}), 404

    def generate():
        try:
            with session.pending_cond:
                pending = list(session.pending)
                session.pending.clear()
            if pending:
                for ev in pending:
                    yield f"data: {json.dumps(ev, ensure_ascii=False)}\n\n"
            else:
                yield f"data: {json.dumps({'type': 'status', 'status': session.status}, ensure_ascii=False)}\n\n"
            while True:
                with session.pending_cond:
                    while not session.pending and not session.stop_event.is_set() and session.status != "error":
                        session.pending_cond.wait(timeout=1.0)
                    events = list(session.pending)
                    session.pending.clear()
                for ev in events:
                    yield f"data: {json.dumps(ev, ensure_ascii=False)}\n\n"
                if session.status == "error":
                    yield f"data: {json.dumps({'type': 'error', 'message': session.error or 'Unknown error'}, ensure_ascii=False)}\n\n"
                    break
                if session.stop_event.is_set() and not session.pending:
                    yield f"data: {json.dumps({'type': 'final', 'status': session.status}, ensure_ascii=False)}\n\n"
                    break
        except GeneratorExit:
            pass
        except Exception:
            logger.exception("Realtime STS stream error")

    return Response(
        stream_with_context(generate()),
        mimetype='text/event-stream',
        headers={'Cache-Control': 'no-cache', 'X-Accel-Buffering': 'no'},
    )


@app.route('/api/realtime/audio', methods=['POST'])
@login_required
def realtime_audio():
    session = _rt_get_session(request.args.get('session_id'))
    if not session:
        return jsonify({'error': 'Session not found'}), 404
    if session.status in ("closed", "error", "stopped"):
        return jsonify({'error': 'セッションは終了しています'}), 400
    data = request.get_data(cache=False)
    if not data or len(data) > RT_AUDIO_POST_MAX:
        return jsonify({'error': 'Invalid audio payload'}), 400
    with session.user_lock:
        if len(session.user_audio) + len(data) <= RT_PCM_CAP:
            session.user_audio += data
    session.audio_in.put(("audio", data))
    return jsonify({'status': 'ok'})


@app.route('/api/realtime/commit', methods=['POST'])
@login_required
def realtime_commit():
    data = request.get_json(silent=True) or {}
    session = _rt_get_session(data.get('session_id'))
    if not session:
        return jsonify({'error': 'Session not found'}), 404
    if session.status in ("closed", "error", "stopped"):
        return jsonify({'error': 'セッションは終了しています'}), 400
    session.audio_in.put(("commit",))
    return jsonify({'status': 'ok'})


@app.route('/api/realtime/cancel', methods=['POST'])
@login_required
def realtime_cancel():
    data = request.get_json(silent=True) or {}
    session = _rt_get_session(data.get('session_id'))
    if not session:
        return jsonify({'error': 'Session not found'}), 404
    session.stop_event.set()
    if session.thread:
        session.thread.join(timeout=3)
    with RT_SESSIONS_LOCK:
        RT_SESSIONS.pop(session.session_id, None)
    return jsonify({'status': 'ok'})


@app.route('/api/realtime/save', methods=['POST'])
@login_required
def realtime_save():
    data = request.get_json(silent=True) or {}
    session = _rt_get_session(data.get('session_id'))
    if not session:
        return jsonify({'error': 'Session not found'}), 404

    session.stop_event.set()
    if session.thread:
        session.thread.join(timeout=6)

    with session.assistant_lock:
        assistant_pcm = bytes(session.assistant_audio)
    with session.user_lock:
        user_pcm = bytes(session.user_audio)

    audio_url = None
    in_fname = None
    try:
        if len(assistant_pcm) >= 1024:
            wav_bytes = _pcm_to_wav_bytes(assistant_pcm, rate=session.rate_out)
            out_fname, _ = _save_user_audio(current_user.id, wav_bytes, ".wav", current_user.enable_e2ee)
            audio_url = f"/files/{current_user.id}/{out_fname}"
        if len(user_pcm) >= 1024:
            u_wav = _pcm_to_wav_bytes(user_pcm, rate=session.rate_in)
            in_fname, _ = _save_user_audio(current_user.id, u_wav, ".wav", current_user.enable_e2ee)
    except Exception as exc:
        logger.exception("Realtime STS audio save error")

    user_text = (session.user_transcript or "音声メッセージ").strip()
    assistant_text = (session.assistant_transcript or "").strip()
    assistant_thought = (session.assistant_thought or "").strip()

    # Nothing was captured — drop the empty session without saving a message.
    if (not assistant_pcm and not user_pcm
            and not user_text.strip() and not assistant_text.strip()):
        with RT_SESSIONS_LOCK:
            RT_SESSIONS.pop(session.session_id, None)
        return jsonify({'status': 'empty'})

    thread_id = data.get('thread_id')
    t = resolve_thread_for_user(thread_id, current_user.id) if thread_id else None
    if not t:
        t = Thread(
            user_id=current_user.id,
            public_id=generate_thread_public_id(),
            is_temporary=True,
        )
        db.session.add(t)
        safe_db_commit()
        thread_id = t.id
    else:
        thread_id = t.id

    thought_tag = f"<thought>\n{assistant_thought}\n</thought>\n" if assistant_thought else ""
    audio_tag = f'\n<audio controls src="{audio_url}" class="w-full mt-2"></audio>\n' if audio_url else ""
    assistant_content = thought_tag + (assistant_text + "\n" if assistant_text else "") + audio_tag

    try:
        u_content = encrypt_val(user_text) if current_user.enable_e2ee else user_text
        a_content = encrypt_val(assistant_content) if current_user.enable_e2ee else assistant_content
        user_tokens_in = count_tokens_for_display(user_text, session.model_key)
        assistant_tokens_out = count_tokens_for_display(assistant_text, session.model_key)
        if assistant_thought:
            assistant_tokens_out += count_tokens_for_display(assistant_thought, session.model_key)

        parent_id = None
        last_msg = Message.query.filter_by(thread_id=thread_id).order_by(Message.id.desc()).first()
        if last_msg:
            parent_id = last_msg.id

        user_msg = Message(
            thread_id=thread_id,
            role='user',
            content=u_content,
            image_url=json.dumps([f"{current_user.id}/{in_fname}"]) if in_fname else None,
            is_encrypted=current_user.enable_e2ee,
            parent_id=parent_id,
            model=session.model_key,
            tokens_in=user_tokens_in,
            tokens=sum_token_counts(user_tokens_in, None),
        )
        db.session.add(user_msg)
        safe_db_commit()

        assistant_msg = Message(
            thread_id=thread_id,
            role='assistant',
            content=a_content,
            model=session.model_key,
            is_encrypted=current_user.enable_e2ee,
            parent_id=user_msg.id,
            tokens_out=assistant_tokens_out,
            tokens=sum_token_counts(None, assistant_tokens_out),
        )
        db.session.add(assistant_msg)
        safe_db_commit()
    except Exception as exc:
        logger.exception("Realtime STS message save error")
        with RT_SESSIONS_LOCK:
            RT_SESSIONS.pop(session.session_id, None)
        return jsonify({'error': f'メッセージ保存に失敗しました: {exc}', 'audio_url': audio_url}), 500

    with RT_SESSIONS_LOCK:
        RT_SESSIONS.pop(session.session_id, None)
    return jsonify({'status': 'ok', 'audio_url': audio_url, 'thread_id': str(thread_id)})


@app.route('/api/gemini/session', methods=['POST'])
@login_required
def gemini_session():
    data = request.get_json(silent=True) or {}
    model_key = (data.get('model') or "gemini-3.1-flash-live-preview").strip()
    if model_key not in STS_MODELS or get_sts_provider(model_key) != 'google':
        return jsonify({'error': 'Invalid Gemini Live model'}), 400
    
    # Resolve API key and runtime
    gemini_runtime = _resolve_gemini_runtime(current_user)
    model_specific_key = _get_model_specific_api_key(current_user, model_key)
    key = model_specific_key or gemini_runtime.get("api_key")
    
    if not key:
        return jsonify({'error': 'Gemini API Key not configured'}), 400
        
    # Use v1alpha for token creation as seen in test_genai_token.py
    client = _get_gemini_client(
        api_key=key,
        backend=gemini_runtime.get("backend"),
        vertex_project=gemini_runtime.get("vertex_project"),
        vertex_location=gemini_runtime.get("vertex_location"),
        vertex_credentials_json=gemini_runtime.get("vertex_credentials_json"),
        api_version='v1alpha'
    )
    
    if not client:
        return jsonify({'error': 'Gemini client not configured'}), 400

    # Thinking configuration and other setup
    thinking_level = data.get('thinking_level') or 'minimal'
    include_thoughts = data.get('include_thoughts') is True
    voice = (data.get('voice') or "Kore").strip()
    is_live_translate = (model_key == "gemini-3.5-live-translate-preview")
    is_live_transcribe = (model_key == "gemini-3.5-transcribe-live")

    if is_live_transcribe:
        # Live Transcription: TEXT output. The detailed transcription config
        # (language_codes / custom_vocabulary / mode) is sent by the client in
        # the WebSocket setup message; the installed SDK (v1.56.0) rejects those
        # fields inside the ephemeral token config, so pass an empty object here.
        generation_config = {
            'response_modalities': ['TEXT'],
            'input_audio_transcription': {},
        }
    else:
        generation_config = {
            'response_modalities': ['AUDIO'],
        }
        if not is_live_translate and voice and voice in GEMINI_STS_VOICES:
            generation_config['speech_config'] = {
                'voice_config': {
                    'prebuilt_voice_config': {'voice_name': voice}
                }
            }
        if not is_live_translate and thinking_level:
            generation_config['thinking_config'] = {
                'thinking_level': thinking_level,
                'include_thoughts': include_thoughts
            }
        if is_live_translate:
            # The installed SDK rejects `translation_config` inside the ephemeral
            # token config (no such field in LiveConnectConfig). The client sends
            # `translationConfig` in the WebSocket setup message instead, so we
            # intentionally omit it here to avoid a token-creation 400/422 error.
            pass

    config = {
        'live_connect_constraints': {
            'model': f'models/{model_key}',
            'config': generation_config
        }
    }
    
    try:
        # Note: auth_tokens.create is experimental in the SDK
        token = client.auth_tokens.create(config=config)
        return jsonify({
            'token': token.name,
            'url': 'wss://generativelanguage.googleapis.com/ws/google.ai.generativelanguage.v1beta.GenerativeService.BidiGenerateContentConstrained'
        })
    except Exception as e:
        logger.error(f"Failed to create Gemini session token: {e}")
        return jsonify({'error': str(e)}), 500

@app.route('/api/gemini/save_sts', methods=['POST'])
@login_required
def save_sts_direct():
    data = request.get_json(silent=True) or {}
    thread_id = data.get('thread_id')
    model_key = data.get('model')
    user_text = data.get('user_text')
    assistant_text = data.get('assistant_text')
    assistant_thought = data.get('assistant_thought')
    audio_base64 = data.get('audio_base64') # Assistant audio
    user_audio_base64 = data.get('user_audio_base64') # User audio recorded by client
    
    t = resolve_thread_for_user(thread_id, current_user.id)
    if not t:
        return jsonify({'error': 'Invalid thread'}), 403
    if model_key not in STS_MODELS or get_sts_provider(model_key) != 'google':
        return jsonify({'error': 'Invalid Gemini Live model'}), 400
    thread_db_id = t.id
    for text_value in (user_text, assistant_text, assistant_thought):
        if text_value is not None and len(str(text_value)) > 500_000:
            return jsonify({'error': 'Transcript is too large'}), 413

    # Save Assistant Audio (Gemini returns PCM 24kHz)
    audio_url = None
    if audio_base64:
        try:
            audio_data = _decode_base64_limited(audio_base64, _AUDIO_INPUT_MAX_BYTES)
            wav_bytes = _pcm_to_wav_bytes(audio_data, rate=24000)
            out_fname, _ = _save_user_audio(current_user.id, wav_bytes, ".wav", current_user.enable_e2ee)
            audio_url = f"/files/{current_user.id}/{out_fname}"
        except Exception as e:
            logger.error(f"Failed to save assistant audio: {e}")

    # Save User Audio (Client sends WebM/Opus)
    in_fname = None
    if user_audio_base64:
        try:
            user_audio_data = _decode_base64_limited(user_audio_base64, _AUDIO_INPUT_MAX_BYTES)
            in_fname, _ = _save_user_audio(current_user.id, user_audio_data, ".webm", current_user.enable_e2ee)
        except Exception as e:
            logger.error(f"Failed to save user audio: {e}")

    user_text = (user_text or "Voice message").strip()
    assistant_text_clean = (assistant_text or "").strip()
    assistant_thought_clean = (assistant_thought or "").strip()
    
    thought_tag = f"<thought>\n{assistant_thought_clean}\n</thought>\n" if assistant_thought_clean else ""
    audio_tag = f'\n<audio controls src="{audio_url}" class="w-full mt-2"></audio>\n' if audio_url else ""
    assistant_content = thought_tag + (assistant_text_clean + "\n" if assistant_text_clean else "") + audio_tag

    try:
        u_content = encrypt_val(user_text) if current_user.enable_e2ee else user_text
        a_content = encrypt_val(assistant_content) if current_user.enable_e2ee else assistant_content
        user_tokens_in = count_tokens_for_display(user_text, model_key)
        assistant_tokens_out = count_tokens_for_display(assistant_text_clean, model_key)
        if assistant_thought_clean:
            assistant_tokens_out += count_tokens_for_display(assistant_thought_clean, model_key)
        
        parent_id = None
        last_msg = Message.query.filter_by(thread_id=thread_db_id).order_by(Message.id.desc()).first()
        if last_msg: parent_id = last_msg.id

        user_msg = Message(
            thread_id=thread_db_id,
            role='user',
            content=u_content,
            image_url=json.dumps([f"{current_user.id}/{in_fname}"]) if in_fname else None,
            is_encrypted=current_user.enable_e2ee,
            parent_id=parent_id,
            model=model_key,
            tokens_in=user_tokens_in,
            tokens=sum_token_counts(user_tokens_in, None)
        )
        db.session.add(user_msg)
        safe_db_commit()

        assistant_msg = Message(
            thread_id=thread_db_id,
            role='assistant',
            content=a_content,
            model=model_key,
            is_encrypted=current_user.enable_e2ee,
            parent_id=user_msg.id,
            tokens_out=assistant_tokens_out,
            tokens=sum_token_counts(None, assistant_tokens_out)
        )
        db.session.add(assistant_msg)
        safe_db_commit()
        return jsonify({'status': 'ok'})
    except Exception as e:
        logger.error(f"Failed to save STS message: {e}")
        return jsonify({'error': str(e)}), 500

@app.route('/robots.txt')
def robots_txt():
    # Allow landing and auth pages, but disallow private/API paths
    lines = [
        "User-agent: *",
        "Disallow: /files/",
        "Disallow: /api/",
        "Disallow: /thread/",
        "Disallow: /chat/",
        "Allow: /login",
        "Allow: /signup",
        "Allow: /landing",
        "Allow: /help",
        "Allow: /changelog",
        "Allow: /"
    ]
    return Response("\n".join(lines), mimetype="text/plain")

def _add_file_privacy_headers(resp):
    resp.headers["X-Robots-Tag"] = "noindex, nofollow"
    resp.headers["Cache-Control"] = "private, no-cache, no-store, must-revalidate"
    resp.headers["Vary"] = "Cookie"
    return resp

def _add_thumb_cache_headers(resp, etag=None):
    resp.headers["X-Robots-Tag"] = "noindex, nofollow"
    resp.headers["Cache-Control"] = "private, max-age=86400, stale-while-revalidate=604800"
    resp.headers["Vary"] = "Cookie"
    if etag:
        resp.headers["ETag"] = f'"{etag}"'
    return resp

def _unreadable_file_http_response(filename, is_thumb):
    """Distinguish a file whose encryption key is unavailable (exists but cannot
    be decrypted) from a genuinely-missing file.  409 + JSON lets the frontend
    show a clear warning instead of a broken thumbnail."""
    resp = jsonify({
        "error": "encryption_key_mismatch",
        "message": "このファイルは暗号キーが一致しないため閲覧できません",
        "unreadable": True,
        "filename": filename,
        "thumbnail": bool(is_thumb),
    })
    resp.status_code = 409
    resp.headers["Cache-Control"] = "no-store"
    return resp


@app.route('/files/thumb/<path:filename>')
@login_required
def serve_file_thumb(filename):
    actual_rel_path = _resolve_user_upload_rel_path(filename, current_user.id)
    if not actual_rel_path:
        abort(403)
    info = _get_file_disk_info(actual_rel_path)
    if not info or not info.get("exists"):
        abort(404)

    ext = os.path.splitext(actual_rel_path)[1].lower()
    if ext not in _IMAGE_THUMB_EXTS:
        return redirect(url_for('serve_file', filename=filename))

    cache_key = (
        actual_rel_path,
        info.get("mtime"),
        info.get("size"),
        1 if info.get("is_encrypted") else 0,
        _THUMBNAIL_SIZE,
        _THUMBNAIL_QUALITY
    )
    etag = hashlib.sha256(repr(cache_key).encode()).hexdigest()
    request_etag = request.headers.get("If-None-Match") or ""
    if request_etag:
        req_tokens = [tok.strip().strip('"') for tok in request_etag.split(",") if tok.strip()]
        if "*" in req_tokens or etag in req_tokens:
            resp = Response(status=304)
            return _add_thumb_cache_headers(resp, etag=etag)

    thumb_bytes = _thumbnail_bytes_cache_get(cache_key)
    if thumb_bytes is None:
        data = _load_user_file_bytes(actual_rel_path, info)
        if data is None:
            # A file present on disk that the current key cannot decrypt is a
            # key-mismatch (unrecoverable) case, not a missing file.
            if info and info.get("exists"):
                return _unreadable_file_http_response(filename, is_thumb=True)
            abort(404)
        try:
            with Image.open(BytesIO(data)) as im:
                if hasattr(Image, "Resampling"):
                    resample_lanczos = Image.Resampling.LANCZOS
                else:
                    resample_lanczos = Image.LANCZOS
                if im.mode not in ("RGB", "RGBA"):
                    im = im.convert("RGB")
                im.thumbnail((_THUMBNAIL_SIZE, _THUMBNAIL_SIZE), resample=resample_lanczos)
                buf = BytesIO()
                im.save(buf, format="WEBP", quality=_THUMBNAIL_QUALITY, method=4)
                thumb_bytes = buf.getvalue()
        except Exception as e:
            log_force(f"Thumbnail generation failed for {actual_rel_path}: {e}")
            return redirect(url_for('serve_file', filename=filename))
        _thumbnail_bytes_cache_put(cache_key, thumb_bytes)

    resp = send_file(BytesIO(thumb_bytes), mimetype="image/webp")
    return _add_thumb_cache_headers(resp, etag=etag)

@app.route('/files/<path:filename>')
@login_required
def serve_file(filename):
    actual_rel_path = _resolve_user_upload_rel_path(filename, current_user.id)
    if not actual_rel_path:
        abort(403)
    file_path = os.path.join(app.config['UPLOAD_FOLDER'], actual_rel_path)
    if not _path_is_within(app.config['UPLOAD_FOLDER'], file_path):
        abort(403)
    
    enc_path = file_path + '.enc'
    mtype = mimetypes.guess_type(file_path)[0] or 'application/octet-stream'

    if os.path.exists(file_path):
        resp = send_file(file_path, mimetype=mtype, conditional=True)
        resp.headers.setdefault("Accept-Ranges", "bytes")
        return _add_file_privacy_headers(resp)
    elif os.path.exists(enc_path):
        info = _get_file_disk_info(actual_rel_path)
        data = _load_user_file_bytes(actual_rel_path, info)
        if data is None:
            if info and info.get("exists"):
                return _unreadable_file_http_response(filename, is_thumb=False)
            abort(404)
        range_header = request.headers.get('Range')
        if range_header:
            m = re.match(r"bytes=(\d*)-(\d*)", range_header)
            if m:
                size = len(data)
                start = int(m.group(1)) if m.group(1) else 0
                end = int(m.group(2)) if m.group(2) else size - 1
                end = min(end, size - 1)
                if start > end or start >= size:
                    return Response(status=416, headers={"Content-Range": f"bytes */{size}"})
                chunk = data[start:end + 1]
                resp = Response(chunk, status=206, mimetype=mtype, direct_passthrough=True)
                resp.headers["Content-Range"] = f"bytes {start}-{end}/{size}"
                resp.headers["Accept-Ranges"] = "bytes"
                resp.headers["Content-Length"] = str(end - start + 1)
                return _add_file_privacy_headers(resp)
        resp = send_file(BytesIO(data), download_name=os.path.basename(actual_rel_path), as_attachment=False, mimetype=mtype)
        return _add_file_privacy_headers(resp)
    else:
        abort(404)

@app.route('/api/threads', methods=['GET', 'POST'])
@login_required
def handle_threads():
    log_force(f"DEBUG: handle_threads started, method={request.method}")
    if request.method == 'GET':
        q = request.args.get('q', '').strip()
        page = request.args.get('page', 1, type=int)
        per_page = 20
        log_force(f"DEBUG: handle_threads query q={q}, page={page}")
        try:
            query = Thread.query.filter_by(user_id=current_user.id).filter(~Thread.title.startswith("[LIBRARY]"))
            if q: 
                if current_user.enable_e2ee: query = query.filter(Thread.title.contains(q))
                else: query = query.join(Message).filter(or_(Thread.title.contains(q), Message.content.contains(q))).distinct()
            
            pagination = query.order_by(Thread.is_bookmarked.desc(), Thread.bookmarked_at.desc(), Thread.updated_at.desc()).paginate(page=page, per_page=per_page, error_out=False)
            threads = []
            for t in pagination.items:
                threads.append({
                    'id': t.public_id or t.id,
                    'title': t.title,
                    'is_bookmarked': bool(t.is_bookmarked),
                    'last_model': t.last_model,
                    'is_temporary': bool(getattr(t, "is_temporary", False))
                })
            log_force(f"DEBUG: handle_threads returning {len(threads)} threads")
            return jsonify({
                'threads': threads,
                'has_next': pagination.has_next,
                'next_page': pagination.next_num
            })
        except Exception as e:
            log_force(f"DEBUG: handle_threads GET failed: {e}")
            raise e
    
    # POST logic
    try:
        payload = request.get_json(silent=True) or {}
        requested_temp = _coerce_bool_or_none(payload.get('is_temporary'))
        log_force(f"DEBUG: handle_threads creating new thread, is_temporary={requested_temp}")
        t = Thread(
            user_id=current_user.id,
            public_id=generate_thread_public_id(),
            is_temporary=bool(requested_temp)
        )
        db.session.add(t)
        safe_db_commit()
        log_force(f"DEBUG: handle_threads thread created, public_id={t.public_id}")
        if bool(t.is_temporary):
            _mark_temp_chat_presence(
                t,
                current_user.id,
                timeout_seconds=_get_user_temp_chat_timeout_seconds(current_user)
            )
        return jsonify({
            'id': t.public_id,
            'title': t.title,
            'is_temporary': bool(t.is_temporary),
            **_get_temp_chat_runtime_meta(t, user=current_user)
        })
    except Exception as e:
        log_force(f"DEBUG: handle_threads POST failed: {e}")
        raise e

@app.route('/api/threads/<thread_id>', methods=['GET', 'DELETE'])
@login_required
def handle_thread_item(thread_id):
    t = resolve_thread_for_user(thread_id, current_user.id)
    if not t: return jsonify({'error': '403'}), 403
    if request.method == 'GET':
        limit = request.args.get('limit', type=int)
        before_id = request.args.get('before_id', type=int)
        include_meta_raw = str(request.args.get('include_meta', '1')).strip().lower()
        include_meta = include_meta_raw not in ('0', 'false', 'no', 'off')
        if limit is not None:
            limit = max(1, min(limit, 200))
        has_older_messages = False
        total_messages = None
        oldest_loaded_id = None

        q = Message.query.filter_by(thread_id=t.id)
        if before_id:
            q = q.filter(Message.id < before_id)

        if limit:
            # Page by message ID (cursor=before_id) and then restore stable presentation order.
            rows_desc = q.order_by(Message.id.desc()).limit(limit + 1).all()
            if len(rows_desc) > limit:
                has_older_messages = True
                rows_desc = rows_desc[:limit]
            ms = sorted(rows_desc, key=lambda m: ((m.timestamp or datetime.min), m.id))
            if ms:
                oldest_loaded_id = ms[0].id
            if before_id is None:
                total_messages = None
        else:
            # Ensure stable ordering even when timestamps collide (e.g., rapid edit/regenerate).
            ms = Message.query.filter_by(thread_id=t.id).order_by(Message.timestamp, Message.id).all()
            if ms:
                oldest_loaded_id = ms[0].id
        res = []
        for m in ms:
            cnt = decrypt_val(m.content) if m.is_encrypted else m.content
            tht = decrypt_val(m.thought_data) if (m.is_encrypted and m.thought_data) else m.thought_data
            thought_text = extract_reasoning_text(tht)
            token_in = None
            token_out = None
            token_total = None
            tokens_content = None
            tokens_thought = None
            legacy_token_total = None
            legacy_token_in = None
            legacy_token_out = None
            if (m.tokens_in and m.tokens_in > 0) or (m.tokens_out and m.tokens_out > 0):
                token_in = m.tokens_in if m.tokens_in and m.tokens_in > 0 else None
                token_out = m.tokens_out if m.tokens_out and m.tokens_out > 0 else None
                token_total = sum_token_counts(token_in, token_out)
                stored_tokens_thought = getattr(m, 'tokens_thought', None)
                if stored_tokens_thought is not None and stored_tokens_thought > 0:
                    tokens_thought = stored_tokens_thought
            elif m.tokens is not None and m.tokens > 0 and (should_count_tokens_for_display(m.model) or not m.model):
                if m.role == 'user':
                    legacy_token_in = m.tokens
                else:
                    legacy_token_out = m.tokens
                legacy_token_total = m.tokens
            if token_total is None and should_count_tokens_for_display(m.model):
                details = build_message_token_details(m.role, cnt, thought_text, m.model, token_in, token_out)
                token_in = details["tokens_in"] if details["tokens_in"] is not None else token_in
                token_out = details["tokens_out"] if details["tokens_out"] is not None else token_out
                token_total = details["tokens_total"] if details["tokens_total"] is not None else token_total
                tokens_content = details["tokens_content"]
                tokens_thought = details["tokens_thought"]
            if token_total is None and legacy_token_total is not None:
                token_in = token_in if token_in is not None else legacy_token_in
                token_out = token_out if token_out is not None else legacy_token_out
                token_total = legacy_token_total
            res.append({
                'id': m.id, 
                'role': m.role, 
                'content': cnt, 
                'image_url': m.image_url, 
                'model': m.model, 
                'thought_data': tht,
                'tokens': token_total,
                'tokens_in': token_in,
                'tokens_out': token_out,
                'tokens_content': tokens_content,
                'tokens_thought': tokens_thought,
                'is_encrypted': bool(m.is_encrypted),
                'quote_text': m.quote_text,
                'parent_id': m.parent_id,
                'gem_uuid': m.gem_uuid,
                'gem_name': m.gem_name
            })
        payload = {
            'messages': res,
            'has_older_messages': bool(has_older_messages),
            'oldest_loaded_id': oldest_loaded_id,
            'loaded_count': len(res),
            'total_messages': total_messages
        }
        if include_meta:
            pending_job = None
            try:
                pending_raw = redis_conn.get(f"pending_job:{current_user.id}:{t.id}")
                if pending_raw:
                    try:
                        pending_job = json.loads(pending_raw)
                    except Exception:
                        pending_job = {"job_id": pending_raw.decode("utf-8", "ignore")}
            except Exception:
                pending_job = None
            payload.update({
                'title': t.title,
                'custom_instruction': t.custom_instruction,
                'include_global_instruction': t.include_global_instruction if t.include_global_instruction is not None else True,
                'last_model': t.last_model,
                'last_gem_uuid': t.last_gem_uuid,
                'enable_prompt_caching': bool(getattr(t, "enable_prompt_caching", False)),
                'prompt_cache_provider': getattr(t, "prompt_cache_provider", None),
                'is_temporary': bool(getattr(t, "is_temporary", False)),
                'pending_job': pending_job
            })
            payload.update(_get_temp_chat_runtime_meta(t, user=current_user))
        return jsonify(payload)

    temp_member = _temp_chat_member(t)
    for m in t.messages:
        if m.image_url:
            try:
                for p in _iter_message_attachment_refs(m.image_url):
                    _delete_user_upload_ref(current_user.id, p)
            except Exception:
                pass

    db.session.delete(t)
    safe_db_commit()
    _clear_temp_chat_tracking(temp_member)
    try:
        redis_conn.delete(f"pending_job:{current_user.id}:{t.id}")
    except Exception:
        pass
    return jsonify({'status': 'deleted'})

def _serialize_message_attachment_for_pdf(raw_ref):
    source = "unknown"
    ref = raw_ref
    if isinstance(raw_ref, dict):
        source = _normalize_attachment_source(raw_ref.get("source"))
        ref = raw_ref.get("filepath") or raw_ref.get("path") or raw_ref.get("url") or raw_ref.get("file") or ""
    norm = _normalize_upload_ref(ref)
    if not norm:
        return None
    filename = os.path.basename(norm)
    ext = os.path.splitext(filename)[1].lower().lstrip(".")
    is_image = ext in {e.lstrip(".") for e in _IMAGE_THUMB_EXTS}
    preview_endpoint = 'serve_file_thumb' if is_image else 'serve_file'
    return {
        "path": norm,
        "filename": filename,
        "source": source,
        "is_image": is_image,
        "url": url_for('serve_file', filename=norm),
        "preview_url": url_for(preview_endpoint, filename=norm)
    }

def _build_thread_pdf_payload(thread, leaf_id=None):
    messages = Message.query.filter_by(thread_id=thread.id).order_by(Message.timestamp, Message.id).all()
    if not messages:
        return {
            "thread": {
                "id": thread.id,
                "public_id": thread.public_id,
                "title": thread.title or "AI Chat"
            },
            "messages": [],
            "leaf_id": None,
            "generated_at": datetime.utcnow().isoformat() + "Z"
        }

    msg_map = {m.id: m for m in messages}
    leaf = msg_map.get(leaf_id) if leaf_id else None
    if leaf is None:
        leaf = messages[-1]

    path = []
    seen = set()
    curr = leaf
    while curr and curr.id not in seen:
        seen.add(curr.id)
        path.append(curr)
        parent_id = curr.parent_id
        curr = msg_map.get(parent_id) if parent_id else None
    path.reverse()

    serialized = []
    for m in path:
        content = decrypt_val(m.content) if m.is_encrypted else m.content
        thought_raw = decrypt_val(m.thought_data) if (m.is_encrypted and m.thought_data) else m.thought_data
        thought_text = extract_reasoning_text(thought_raw)
        token_in = None
        token_out = None
        token_total = None
        tokens_content = None
        tokens_thought = None
        legacy_token_total = None
        legacy_token_in = None
        legacy_token_out = None
        if (m.tokens_in and m.tokens_in > 0) or (m.tokens_out and m.tokens_out > 0):
            token_in = m.tokens_in if m.tokens_in and m.tokens_in > 0 else None
            token_out = m.tokens_out if m.tokens_out and m.tokens_out > 0 else None
            token_total = sum_token_counts(token_in, token_out)
            stored_tokens_thought = getattr(m, 'tokens_thought', None)
            if stored_tokens_thought is not None and stored_tokens_thought > 0:
                tokens_thought = stored_tokens_thought
        elif m.tokens is not None and m.tokens > 0 and (should_count_tokens_for_display(m.model) or not m.model):
            if m.role == 'user':
                legacy_token_in = m.tokens
            else:
                legacy_token_out = m.tokens
            legacy_token_total = m.tokens
        if token_total is None and should_count_tokens_for_display(m.model):
            details = build_message_token_details(m.role, content, thought_text, m.model, token_in, token_out)
            token_in = details["tokens_in"] if details["tokens_in"] is not None else token_in
            token_out = details["tokens_out"] if details["tokens_out"] is not None else token_out
            token_total = details["tokens_total"] if details["tokens_total"] is not None else token_total
            tokens_content = details["tokens_content"]
            tokens_thought = details["tokens_thought"]
        if token_total is None and legacy_token_total is not None:
            token_in = token_in if token_in is not None else legacy_token_in
            token_out = token_out if token_out is not None else legacy_token_out
            token_total = legacy_token_total

        attachments = []
        for raw_ref in _iter_message_attachment_refs(m.image_url):
            item = _serialize_message_attachment_for_pdf(raw_ref)
            if item:
                attachments.append(item)

        serialized.append({
            "id": m.id,
            "role": m.role,
            "content": content,
            "image_url": m.image_url,
            "attachments": attachments,
            "model": m.model,
            "thought_data": thought_raw,
            "thought_text": thought_text,
            "tokens": token_total,
            "tokens_in": token_in,
            "tokens_out": token_out,
            "tokens_content": tokens_content,
            "tokens_thought": tokens_thought,
            "is_encrypted": bool(m.is_encrypted),
            "quote_text": m.quote_text,
            "parent_id": m.parent_id,
            "timestamp": m.timestamp.isoformat() if m.timestamp else None
        })

    return {
        "thread": {
            "id": thread.id,
            "public_id": thread.public_id,
            "title": thread.title or "AI Chat",
            "last_model": thread.last_model,
            "custom_instruction": thread.custom_instruction,
            "include_global_instruction": thread.include_global_instruction if thread.include_global_instruction is not None else True
        },
        "messages": serialized,
        "leaf_id": leaf.id,
        "generated_at": datetime.utcnow().isoformat() + "Z"
    }

_RICH_PASTE_PDF_FONT_STATE = {
    "ready": False,
    "base": "Helvetica",
    "base_bold": "Helvetica-Bold",
    "mono": "Courier",
}


def _ensure_rich_paste_pdf_fonts():
    if _RICH_PASTE_PDF_FONT_STATE.get("ready"):
        return _RICH_PASTE_PDF_FONT_STATE
    try:
        from reportlab.pdfbase import pdfmetrics
        from reportlab.pdfbase.ttfonts import TTFont
    except Exception:
        _RICH_PASTE_PDF_FONT_STATE["ready"] = True
        return _RICH_PASTE_PDF_FONT_STATE

    font_candidates = [
        ("IPAGothic", "/usr/share/fonts/opentype/ipafont-gothic/ipag.ttf"),
        ("IPAPGothic", "/usr/share/fonts/opentype/ipafont-gothic/ipagp.ttf"),
        ("NotoSansMono", "/usr/share/fonts/truetype/noto/NotoSansMono-Regular.ttf"),
    ]
    for font_name, font_path in font_candidates:
        if not os.path.exists(font_path):
            continue
        try:
            pdfmetrics.registerFont(TTFont(font_name, font_path))
        except Exception:
            continue

    if "IPAGothic" in getattr(pdfmetrics, "_fonts", {}):
        _RICH_PASTE_PDF_FONT_STATE["base"] = "IPAGothic"
    if "IPAPGothic" in getattr(pdfmetrics, "_fonts", {}):
        _RICH_PASTE_PDF_FONT_STATE["base_bold"] = "IPAPGothic"
    elif _RICH_PASTE_PDF_FONT_STATE["base"] == "IPAGothic":
        _RICH_PASTE_PDF_FONT_STATE["base_bold"] = "IPAGothic"
    if "NotoSansMono" in getattr(pdfmetrics, "_fonts", {}):
        _RICH_PASTE_PDF_FONT_STATE["mono"] = "NotoSansMono"
    _RICH_PASTE_PDF_FONT_STATE["ready"] = True
    return _RICH_PASTE_PDF_FONT_STATE


def _css_color_to_hex(value):
    if value is None:
        return None
    raw = str(value).strip()
    if not raw:
        return None
    lower = raw.lower()
    if lower in {"inherit", "initial", "unset", "transparent", "none", "currentcolor"}:
        return None
    if lower.startswith("#"):
        if len(lower) == 4:
            return "#" + "".join(ch * 2 for ch in lower[1:])
        if len(lower) >= 7:
            return lower[:7]
    m = re.match(r"rgba?\(([^)]+)\)", lower)
    if m:
        parts = [p.strip() for p in m.group(1).split(",")]
        if len(parts) >= 3:
            nums = []
            for part in parts[:3]:
                if part.endswith("%"):
                    try:
                        num = int(round(float(part[:-1]) * 2.55))
                    except Exception:
                        return None
                else:
                    try:
                        num = int(float(part))
                    except Exception:
                        return None
                nums.append(max(0, min(255, num)))
            return "#%02x%02x%02x" % tuple(nums)
    return None


def _parse_inline_style(style_text):
    styles = {}
    if not style_text:
        return styles
    for decl in str(style_text).split(";"):
        if ":" not in decl:
            continue
        prop, value = decl.split(":", 1)
        prop = prop.strip().lower()
        value = value.strip()
        if prop in {"color", "background-color", "font-weight", "font-style", "text-decoration"}:
            styles[prop] = value
    return styles


def _rich_paste_pdf_filename(title):
    slug = re.sub(r"[^0-9A-Za-z\u3040-\u30ff\u4e00-\u9fff]+", "_", str(title or "").strip()).strip("_")
    if not slug:
        slug = "clipboard_rich"
    if len(slug) > 48:
        slug = slug[:48].rstrip("_")
    ts = datetime.utcnow().strftime("%Y%m%d_%H%M%S")
    return f"{slug}_{ts}.pdf"


def _build_rich_paste_pdf_bytes_reportlab(title, content_html, created_at=None):
    from io import BytesIO
    from bs4 import BeautifulSoup, NavigableString, Tag
    from reportlab import rl_config
    from reportlab.lib import colors
    from reportlab.lib.enums import TA_LEFT
    from reportlab.lib.pagesizes import A4
    from reportlab.lib.styles import ParagraphStyle, getSampleStyleSheet
    from reportlab.lib.units import mm
    from reportlab.lib.utils import ImageReader
    from reportlab.platypus import HRFlowable, Image, Paragraph, Preformatted, SimpleDocTemplate, Spacer, Table, TableStyle, XPreformatted

    sys.setrecursionlimit(max(sys.getrecursionlimit(), 5000))

    rl_config.defaultPageSize = A4
    fonts = _ensure_rich_paste_pdf_fonts()
    base_font = fonts.get("base", "Helvetica")
    bold_font = fonts.get("base_bold", "Helvetica-Bold")
    mono_font = fonts.get("mono", "Courier")

    def esc(value):
        return html.escape("" if value is None else str(value), quote=False)

    def normalize_text(value, preserve_newlines=False):
        txt = "" if value is None else str(value)
        txt = txt.replace("\u00a0", " ")
        txt = txt.replace("\r\n", "\n").replace("\r", "\n")
        if preserve_newlines:
            return txt.strip("\n")
        txt = re.sub(r"[ \t\f\v]+", " ", txt)
        txt = re.sub(r"\n[ \t]+", "\n", txt)
        txt = re.sub(r"[ \t]+\n", "\n", txt)
        txt = re.sub(r"\n{3,}", "\n\n", txt)
        return txt.strip()

    def get_attr_style(tag):
        return _parse_inline_style(tag.get("style"))

    def apply_inline_styles(text, tag=None):
        markup = text
        style = get_attr_style(tag) if tag is not None and hasattr(tag, "get") else {}
        if tag is not None and getattr(tag, "name", "").lower() == "code":
            markup = f'<font face="{mono_font}" backColor="#eeeeee">{markup}</font>'
        if "font-weight" in style and "bold" in style["font-weight"].lower():
            markup = f"<b>{markup}</b>"
        if "font-style" in style and "italic" in style["font-style"].lower():
            markup = f"<i>{markup}</i>"
        if "text-decoration" in style and "underline" in style["text-decoration"].lower():
            markup = f"<u>{markup}</u>"
        color_hex = _css_color_to_hex(style.get("color"))
        if color_hex:
            markup = f'<font color="{color_hex}">{markup}</font>'
        back_hex = _css_color_to_hex(style.get("background-color"))
        if back_hex:
            markup = f'<font backColor="{back_hex}">{markup}</font>'
        return markup

    def inline_markup(node):
        if node is None:
            return ""
        if isinstance(node, NavigableString):
            if type(node).__name__ in ('Doctype', 'Comment', 'Declaration', 'CData', 'ProcessingInstruction'):
                return ""
            return esc(str(node)).replace("\n", "<br/>")
        if not isinstance(node, Tag):
            return ""
        tag_name = (node.name or "").lower()
        if tag_name in {"script", "style", "noscript", "meta", "link", "head", "title", "base", "canvas", "svg", "object", "embed"}:
            return ""
        if tag_name == "br":
            return "<br/>"
        rendered = "".join(inline_markup(child) for child in node.children)
        rendered = rendered or ""
        if not rendered:
            return ""
        if tag_name in {"strong", "b"}:
            rendered = f"<b>{rendered}</b>"
        elif tag_name in {"em", "i"}:
            rendered = f"<i>{rendered}</i>"
        elif tag_name in {"u"}:
            rendered = f"<u>{rendered}</u>"
        elif tag_name in {"s", "strike", "del"}:
            rendered = f"<strike>{rendered}</strike>"
        elif tag_name == "code":
            rendered = f'<font face="{mono_font}" backColor="#eeeeee">{rendered}</font>'
        elif tag_name == "a":
            href = str(node.get("href") or "").strip()
            parsed_href = urlparse(href) if href else None
            if href and parsed_href and parsed_href.scheme.lower() in {"http", "https", "mailto"}:
                rendered = f'<a href="{esc(href)}">{rendered}</a>'
        rendered = apply_inline_styles(rendered, node)
        return rendered

    def paragraph_style(name, font_size=10.5, leading=15, bold=False, italic=False, color="#111827", space_after=6, left_indent=0, first_line_indent=0):
        return ParagraphStyle(
            name,
            parent=styles["BodyText"],
            fontName=bold_font if bold else base_font,
            fontSize=font_size,
            leading=leading,
            textColor=colors.HexColor(color),
            alignment=TA_LEFT,
            spaceAfter=space_after,
            leftIndent=left_indent,
            firstLineIndent=first_line_indent,
            wordWrap="CJK",
            splitLongWords=1,
        )

    styles = getSampleStyleSheet()
    title_style = paragraph_style("RichPasteTitle", font_size=18, leading=23, bold=True, color="#0f172a", space_after=10)
    meta_style = paragraph_style("RichPasteMeta", font_size=9, leading=12, color="#64748b", space_after=12)
    body_style = paragraph_style("RichPasteBody", font_size=10.5, leading=15, color="#111827", space_after=7)
    heading_styles = {
        1: paragraph_style("RichPasteH1", font_size=16, leading=20, bold=True, color="#0f172a", space_after=8),
        2: paragraph_style("RichPasteH2", font_size=14, leading=18, bold=True, color="#0f172a", space_after=8),
        3: paragraph_style("RichPasteH3", font_size=12.5, leading=16, bold=True, color="#0f172a", space_after=7),
        4: paragraph_style("RichPasteH4", font_size=11.5, leading=15, bold=True, color="#0f172a", space_after=6),
        5: paragraph_style("RichPasteH5", font_size=10.8, leading=14, bold=True, color="#0f172a", space_after=6),
        6: paragraph_style("RichPasteH6", font_size=10.5, leading=14, bold=True, color="#0f172a", space_after=6),
    }
    quote_style = paragraph_style("RichPasteQuote", font_size=10.2, leading=15, color="#334155", space_after=0, left_indent=4)
    code_style = ParagraphStyle(
        "RichPasteCode",
        parent=styles["Code"],
        fontName=mono_font,
        fontSize=9.2,
        leading=12.2,
        textColor=colors.HexColor("#111827"),
        alignment=TA_LEFT,
        spaceAfter=10,
        spaceBefore=10,
        leftIndent=0,
        rightIndent=0,
        wordWrap="CJK",
        splitLongWords=1,
        backColor=colors.HexColor("#f8fafc"),
        borderColor=colors.HexColor("#cbd5e1"),
        borderWidth=0.5,
        borderPadding=6,
        borderRadius=2,
    )
    list_style = paragraph_style("RichPasteList", font_size=10.5, leading=15, color="#111827", space_after=3)
    table_cell_style = paragraph_style("RichPasteTableCell", font_size=9.3, leading=12.5, color="#111827", space_after=0)
    note_style = paragraph_style("RichPasteNote", font_size=9.2, leading=12.2, color="#64748b", space_after=4)

    story = []
    doc_buffer = BytesIO()
    
    # Ensure title and created_at are safe for ReportLab
    safe_title = normalize_text(title) or "Clipboard Export"
    safe_created_at = normalize_text(created_at) or datetime.utcnow().strftime('%Y-%m-%d %H:%M:%S')

    doc = SimpleDocTemplate(
        doc_buffer,
        pagesize=A4,
        leftMargin=16 * mm,
        rightMargin=16 * mm,
        topMargin=16 * mm,
        bottomMargin=16 * mm,
        title=str(safe_title),
        author="AI Playground",
    )
    available_width = A4[0] - doc.leftMargin - doc.rightMargin

    def add_paragraph(text, style):
        clean = normalize_text(text)
        if not clean:
            return
        try:
            story.append(Paragraph(clean, style))
        except Exception:
            try:
                # Try escaping the whole thing if markup was invalid
                story.append(Paragraph(esc(clean), style))
            except Exception:
                # Last resort: just add as plain text if still failing
                pass

    def add_blockquote(node):
        text = normalize_text(node.get_text(" ", strip=True))
        if not text:
            return
        try:
            para = Paragraph(esc(text), quote_style)
            # If the blockquote is very long, don't use Table as it may fail page splitting
            if len(text) > 1200:
                story.append(para)
                return
            box = Table([[para]], colWidths=[available_width])
            box.setStyle(TableStyle([
                ("BACKGROUND", (0, 0), (-1, -1), colors.HexColor("#fff9eb")),
                ("LEFTPADDING", (0, 0), (-1, -1), 10),
                ("RIGHTPADDING", (0, 0), (-1, -1), 10),
                ("TOPPADDING", (0, 0), (-1, -1), 8),
                ("BOTTOMPADDING", (0, 0), (-1, -1), 8),
                ("LINEBEFORE", (0, 0), (0, -1), 4, colors.HexColor("#f59e0b")),
                ("BOX", (0, 0), (-1, -1), 0.5, colors.HexColor("#fde68a")),
            ]))
            story.append(box)
        except Exception:
            add_paragraph(esc(text), quote_style)

    def add_hr():
        story.append(HRFlowable(width="100%", thickness=0.8, color=colors.HexColor("#cbd5e1"), spaceBefore=6, spaceAfter=6))

    def add_image(node):
        src = str(node.get("src") or "").strip()
        if not src:
            return
        image_bytes = None
        try:
            if src.startswith("data:"):
                header, encoded = src.split(",", 1)
                if header.lower().startswith("data:image/") and ";base64" in header.lower() and len(encoded) <= 14_000_000:
                    image_bytes = base64.b64decode(encoded, validate=True)
            elif src.startswith("/files/") and current_user.is_authenticated:
                rel_path = _resolve_user_upload_rel_path(src, current_user.id)
                info = _get_file_disk_info(rel_path) if rel_path else None
                if info and info.get("exists") and int(info.get("size") or 0) <= 10 * 1024 * 1024:
                    image_bytes = _load_user_file_bytes(rel_path, info)
        except Exception:
            image_bytes = None
        if image_bytes and len(image_bytes) > 10 * 1024 * 1024:
            image_bytes = None
        if not image_bytes:
            alt = normalize_text(node.get("alt") or "image")
            if alt:
                story.append(Paragraph(f"[Image: {esc(alt)}]", note_style))
            return
        try:
            image = Image(BytesIO(image_bytes))
            image.hAlign = "CENTER"
            max_width = available_width
            max_height = 150 * mm
            try:
                image._restrictSize(max_width, max_height)
            except Exception:
                pass
            story.append(image)
            caption = normalize_text(node.get("alt") or "")
            if caption:
                story.append(Paragraph(esc(caption), note_style))
        except Exception:
            alt = normalize_text(node.get("alt") or "image")
            if alt:
                story.append(Paragraph(f"[Image: {esc(alt)}]", note_style))

    def list_item_children_text(li_node):
        inline_parts = []
        nested_lists = []
        for child in li_node.children:
            if isinstance(child, Tag) and (child.name or "").lower() in {"ul", "ol"}:
                nested_lists.append(child)
                continue
            inline_parts.append(inline_markup(child))
        return "".join(inline_parts), nested_lists

    def add_list(list_node, level=0, ordered=False):
        items = list_node.find_all("li", recursive=False)
        for idx, li in enumerate(items, start=1):
            item_markup, nested_lists = list_item_children_text(li)
            # Remove any trailing <br/> or whitespace before normalization
            item_markup = re.sub(r'(<br\s*/?>\s*)+$', '', item_markup.strip())
            item_text = normalize_text(item_markup, preserve_newlines=True)
            bullet = f"{idx}." if ordered else "-"
            item_style = paragraph_style(
                f"RichPasteList{level}_{idx}",
                font_size=10.3,
                leading=14.8,
                color="#111827",
                space_after=3,
                left_indent=max(0, (level + 1) * 12),
                first_line_indent=-12,
            )
            if item_text:
                try:
                    story.append(Paragraph(item_text, item_style, bulletText=bullet))
                except Exception:
                    story.append(Paragraph(esc(item_text), item_style, bulletText=bullet))
            elif not nested_lists:
                # Add empty item if no text and no nested lists
                story.append(Paragraph("&nbsp;", item_style, bulletText=bullet))

            for nested in nested_lists:
                add_list(nested, level=level + 1, ordered=(nested.name or "").lower() == "ol")

    def add_table(table_node):
        rows = []
        header_rows = 0
        tbody = table_node.find("tbody")
        tr_nodes = tbody.find_all("tr", recursive=False) if tbody else table_node.find_all("tr", recursive=False)
        if not tr_nodes:
            tr_nodes = table_node.find_all("tr")
        for row_index, tr in enumerate(tr_nodes):
            cells = []
            cell_nodes = tr.find_all(["th", "td"], recursive=False)
            if not cell_nodes:
                continue
            if any((cell.name or "").lower() == "th" for cell in cell_nodes) and header_rows == 0:
                header_rows = 1
            for cell in cell_nodes:
                cell_markup = normalize_text(inline_markup(cell), preserve_newlines=True)
                if not cell_markup:
                    cell_markup = "&nbsp;"
                cell_style = ParagraphStyle(
                    f"RichPasteTableCell{row_index}_{len(cells)}",
                    parent=table_cell_style,
                    wordWrap="CJK",
                    splitLongWords=1,
                )
                try:
                    p = Paragraph(cell_markup, cell_style)
                except Exception:
                    p = Paragraph(esc(cell_markup), cell_style)
                cells.append(p)
            if cells:
                rows.append(cells)
        if not rows:
            return
        
        col_count = max(len(r) for r in rows)
        if col_count == 0:
            return
        for row in rows:
            while len(row) < col_count:
                row.append(Paragraph("&nbsp;", table_cell_style))
        
        # Split very large tables into chunks to avoid layout issues
        CHUNK_SIZE = 50
        for i in range(0, len(rows), CHUNK_SIZE):
            chunk = rows[i : i + CHUNK_SIZE]
            is_first_chunk = (i == 0)
            
            # If not first chunk, we might want to repeat header, but SimpleDocTemplate 
            # might handle it if repeatRows is set. However, splitting manual is safer for build.
            current_header_rows = header_rows if is_first_chunk else 0
            
            table = Table(chunk, repeatRows=current_header_rows, hAlign="LEFT", 
                          colWidths=[available_width / col_count] * col_count,
                          splitByRow=1)
            
            style_cmds = [
                ("GRID", (0, 0), (-1, -1), 0.5, colors.HexColor("#cbd5e1")),
                ("VALIGN", (0, 0), (-1, -1), "TOP"),
                ("LEFTPADDING", (0, 0), (-1, -1), 6),
                ("RIGHTPADDING", (0, 0), (-1, -1), 6),
                ("TOPPADDING", (0, 0), (-1, -1), 5),
                ("BOTTOMPADDING", (0, 0), (-1, -1), 5),
            ]
            if current_header_rows:
                style_cmds.extend([
                    ("BACKGROUND", (0, 0), (-1, 0), colors.HexColor("#e2e8f0")),
                    ("TEXTCOLOR", (0, 0), (-1, 0), colors.HexColor("#0f172a")),
                    ("FONTNAME", (0, 0), (-1, 0), bold_font),
                ])
            table.setStyle(TableStyle(style_cmds))
            story.append(table)
            if i + CHUNK_SIZE < len(rows):
                story.append(Spacer(1, 4))

    def add_pre(node):
        text = normalize_text(node.get_text("\n"), preserve_newlines=True)
        if not text:
            return
        try:
            # XPreformatted inherits from Paragraph and supports splitting across pages.
            # It also interprets XML-like tags, so we MUST escape the content.
            story.append(XPreformatted(esc(text), code_style, dedent=0))
        except Exception:
            try:
                # Fallback to Paragraph with manual line breaks
                story.append(Paragraph(esc(text).replace("\n", "<br/>"), code_style))
            except Exception:
                pass

    def render_node(node):
        if node is None:
            return
        if isinstance(node, NavigableString):
            if type(node).__name__ in ('Doctype', 'Comment', 'Declaration', 'CData', 'ProcessingInstruction'):
                return
            text = normalize_text(str(node))
            if text:
                # NavigableString must be escaped before Paragraph
                add_paragraph(esc(text).replace("\n", "<br/>"), body_style)
            return
        if not isinstance(node, Tag):
            return
        tag_name = (node.name or "").lower()
        if tag_name in {"script", "style", "noscript", "meta", "link", "iframe", "canvas", "svg", "object", "embed", "head", "title"}:
            return
        if tag_name in {"h1", "h2", "h3", "h4", "h5", "h6"}:
            level = int(tag_name[1])
            add_paragraph(inline_markup(node), heading_styles.get(level, body_style))
            return
        if tag_name == "p":
            add_paragraph(inline_markup(node), body_style)
            return
        if tag_name in {"div", "section", "article", "main", "header", "footer", "aside", "body", "html"}:
            # Optimization: if it contains only inline elements, process as one paragraph
            inline_only = True
            for child in node.children:
                if isinstance(child, Tag):
                    child_tag = (child.name or "").lower()
                    if child_tag not in {"span", "b", "strong", "i", "em", "u", "s", "a", "code", "font", "br"}:
                        inline_only = False
                        break
            if inline_only:
                markup = inline_markup(node)
                if markup:
                    add_paragraph(markup, body_style)
                return
            for child in node.children:
                render_node(child)
            return
        if tag_name == "blockquote":
            add_blockquote(node)
            return
        if tag_name == "pre":
            add_pre(node)
            return
        if tag_name == "hr":
            add_hr()
            return
        if tag_name == "br":
            story.append(Spacer(1, 3))
            return
        if tag_name == "img":
            add_image(node)
            return
        if tag_name == "figure":
            img = node.find("img")
            if img:
                add_image(img)
            caption = node.find("figcaption")
            if caption:
                add_paragraph(inline_markup(caption), note_style)
            return
        if tag_name in {"ul", "ol"}:
            add_list(node, level=0, ordered=(tag_name == "ol"))
            return
        if tag_name == "table":
            add_table(node)
            return
        text_markup = inline_markup(node)
        if text_markup:
            add_paragraph(text_markup, body_style)

    soup = BeautifulSoup(content_html or "", "html.parser")
    container = soup.body or soup
    story.append(Paragraph(esc(str(safe_title)), title_style))
    story.append(Paragraph(f"Created at: {esc(safe_created_at)}", meta_style))
    story.append(Spacer(1, 6))

    try:
        for child in container.children:
            render_node(child)
    except Exception as e:
        logger.exception("Error during rich paste node rendering")
        story.append(Paragraph(f"[Content rendering partially failed: {esc(str(e))}]", note_style))

    if not any(isinstance(item, (Paragraph, Table, XPreformatted)) for item in story if not isinstance(item, Spacer)):
        story.append(Paragraph("内容がありません。", body_style))

    def draw_page(canvas, doc_obj):
        try:
            canvas.saveState()
            canvas.setStrokeColor(colors.HexColor("#dbe3ee"))
            canvas.setLineWidth(0.6)
            canvas.line(doc.leftMargin, doc.height + doc.topMargin + 2, A4[0] - doc.rightMargin, doc.height + doc.topMargin + 2)
            canvas.setFont(base_font, 8.5)
            canvas.setFillColor(colors.HexColor("#64748b"))
            canvas.drawRightString(A4[0] - doc.rightMargin, 10 * mm, f"Page {doc_obj.page}")
            canvas.restoreState()
        except Exception:
            pass

    try:
        doc.build(story, onFirstPage=draw_page, onLaterPages=draw_page)
    except Exception as e:
        logger.exception("ReportLab doc.build failed")
        # Fallback build with simple story if it failed due to complex layout
        doc_buffer.seek(0)
        doc_buffer.truncate()
        fallback_story = [Paragraph(f"PDF生成エラーが発生しました: {esc(str(e))}", body_style)]
        doc.build(fallback_story)

    return doc_buffer.getvalue()


_RICH_PASTE_ALLOWED_TAGS = frozenset({
    "a", "abbr", "address", "article", "b", "blockquote", "br", "caption", "cite", "code",
    "col", "colgroup", "dd", "del", "details", "div", "dl", "dt", "em", "figcaption",
    "figure", "h1", "h2", "h3", "h4", "h5", "h6", "hr", "i", "img", "kbd", "li", "main",
    "mark", "ol", "p", "pre", "q", "s", "samp", "section", "small", "span", "strong",
    "sub", "summary", "sup", "table", "tbody", "td", "th", "thead", "tfoot", "time", "tr",
    "u", "ul", "var",
})
_RICH_PASTE_ALLOWED_ATTRS = frozenset({
    "align", "alt", "cellpadding", "cellspacing", "colspan", "datetime", "dir", "headers",
    "height", "href", "lang", "open", "rel", "reversed", "rowspan", "scope", "src", "start",
    "style", "target", "title", "type", "value", "width",
})
_RICH_PASTE_SAFE_STYLE_PROPS = frozenset({
    "align-items", "align-self", "background", "background-color", "background-image", "border",
    "border-block-color", "border-block-style", "border-block-width", "border-bottom",
    "border-bottom-color", "border-bottom-left-radius", "border-bottom-right-radius",
    "border-bottom-style", "border-bottom-width", "border-collapse", "border-color",
    "border-image", "border-inline-color", "border-inline-style", "border-inline-width",
    "border-left", "border-left-color", "border-left-style", "border-left-width", "border-radius",
    "border-right", "border-right-color", "border-right-style", "border-right-width",
    "border-spacing", "border-style", "border-top", "border-top-color", "border-top-left-radius",
    "border-top-right-radius", "border-top-style", "border-top-width", "border-width",
    "box-shadow", "box-sizing", "break-after", "break-before", "break-inside", "clear",
    "clip-path", "color", "column-gap", "direction", "display", "flex", "flex-basis",
    "flex-direction", "flex-grow", "flex-shrink", "flex-wrap", "float", "font", "font-family",
    "font-feature-settings", "font-kerning", "font-language-override", "font-optical-sizing",
    "font-size", "font-size-adjust", "font-stretch", "font-style", "font-variant",
    "font-variant-caps", "font-variant-ligatures", "font-variation-settings", "font-weight", "gap",
    "grid", "grid-auto-columns", "grid-auto-flow", "grid-auto-rows", "grid-column",
    "grid-column-end", "grid-column-start", "grid-row", "grid-row-end", "grid-row-start",
    "grid-template", "grid-template-areas", "grid-template-columns", "grid-template-rows", "height",
    "hyphens", "justify-content", "justify-items", "justify-self", "letter-spacing", "line-break",
    "line-height", "list-style", "list-style-position", "list-style-type", "margin",
    "margin-block", "margin-block-end", "margin-block-start", "margin-bottom", "margin-inline",
    "margin-inline-end", "margin-inline-start", "margin-left", "margin-right", "margin-top",
    "max-height", "max-width", "min-height", "min-width", "object-fit", "object-position",
    "opacity", "order", "orphans", "outline", "outline-color", "outline-offset", "outline-style",
    "outline-width", "overflow", "overflow-wrap", "overflow-x", "overflow-y", "padding",
    "padding-block", "padding-block-end", "padding-block-start", "padding-bottom",
    "padding-inline", "padding-inline-end", "padding-inline-start", "padding-left",
    "padding-right", "padding-top", "page-break-after", "page-break-before",
    "page-break-inside", "row-gap", "table-layout", "text-align", "text-decoration",
    "text-decoration-color", "text-decoration-line", "text-decoration-style",
    "text-decoration-thickness", "text-indent", "text-overflow", "text-shadow", "text-transform",
    "text-underline-offset", "vertical-align", "visibility", "white-space", "widows", "width",
    "word-break", "word-spacing", "writing-mode", "-webkit-text-stroke",
    "-webkit-text-stroke-color", "-webkit-text-stroke-width",
})
_RICH_PASTE_DROP_TAGS = frozenset({
    "script", "style", "link", "meta", "noscript", "iframe", "canvas", "svg", "object",
    "embed", "base", "form", "input", "button", "select", "textarea",
})
_RICH_PASTE_UNSAFE_STYLE_RE = re.compile(
    r"url\s*\(|expression\s*\(|javascript\s*:|@import|behavior\s*:|-moz-binding|var\s*\(|env\s*\(",
    re.IGNORECASE,
)
_RICH_PASTE_DATA_IMAGE_RE = re.compile(
    r"^data:image/(?:png|jpe?g|gif|webp);base64,[a-z0-9+/=\s]+$",
    re.IGNORECASE,
)


def _sanitize_rich_paste_style(style_text):
    safe = []
    for declaration in str(style_text or "").split(";"):
        if ":" not in declaration:
            continue
        prop, value = declaration.split(":", 1)
        prop = prop.strip().lower()
        value = re.sub(r"\s*!important\s*$", "", value.strip(), flags=re.IGNORECASE)
        if prop not in _RICH_PASTE_SAFE_STYLE_PROPS or not value or len(value) > 1000:
            continue
        if _RICH_PASTE_UNSAFE_STYLE_RE.search(value):
            continue
        if any(ch in value for ch in "{}"):
            continue
        safe.append(f"{prop}: {value}")
    return "; ".join(safe)


def _sanitize_rich_paste_html(content_html):
    from bs4 import BeautifulSoup, Comment, Doctype, Tag

    soup = BeautifulSoup(str(content_html or ""), "html.parser")
    body_text_length = len(re.sub(r"\s+", " ", soup.get_text(" ", strip=True)))
    body_tag_count = len(soup.find_all(True))
    if body_text_length >= 1000 and body_tag_count >= 120:
        candidates = []
        candidates.extend(soup.find_all("article"))
        candidates.extend(soup.find_all("main"))
        candidates.extend(soup.select('[role="main"],[role="article"]'))
        if candidates:
            eligible = [
                node for node in candidates
                if len(re.sub(r"\s+", " ", node.get_text(" ", strip=True))) >= body_text_length * 0.65
            ]
            if eligible:
                best = min(
                    eligible,
                    key=lambda node: (0 if node.find("h1") else 1, len(node.find_all(True))),
                )
                soup = BeautifulSoup(str(best), "html.parser")
    all_tags = list(soup.find_all(True))
    if len(all_tags) > 25_000:
        raise ValueError("rich_paste_html_too_complex")

    for node in list(soup.contents):
        if isinstance(node, (Comment, Doctype)):
            node.extract()
    for node in list(soup.find_all(string=lambda text: isinstance(text, (Comment, Doctype)))):
        node.extract()

    for node in all_tags:
        if not isinstance(node, Tag) or node.parent is None:
            continue
        tag_name = str(node.name or "").lower()
        if tag_name in _RICH_PASTE_DROP_TAGS:
            node.decompose()
            continue
        if tag_name not in _RICH_PASTE_ALLOWED_TAGS:
            node.unwrap()
            continue

        clean_attrs = {}
        for raw_name, raw_value in list(node.attrs.items()):
            attr_name = str(raw_name or "").lower()
            if attr_name not in _RICH_PASTE_ALLOWED_ATTRS:
                continue
            if isinstance(raw_value, (list, tuple)):
                attr_value = " ".join(str(part) for part in raw_value)
            elif raw_value is None:
                attr_value = ""
            else:
                attr_value = str(raw_value)
            if len(attr_value) > 2_100_000:
                continue
            if attr_name == "style":
                attr_value = _sanitize_rich_paste_style(attr_value)
                if not attr_value:
                    continue
            elif attr_name == "href":
                href = attr_value.strip()
                parsed = urlparse(href)
                if parsed.scheme and parsed.scheme.lower() not in {"http", "https", "mailto"}:
                    continue
                attr_value = href
            elif attr_name == "src":
                src = attr_value.strip()
                if tag_name != "img":
                    continue
                if src.startswith("data:"):
                    if len(src) > 2_100_000 or not _RICH_PASTE_DATA_IMAGE_RE.fullmatch(src):
                        continue
                elif not src.startswith("/files/"):
                    continue
                attr_value = src
            elif attr_name in {"width", "height", "colspan", "rowspan", "start", "value"}:
                if not re.fullmatch(r"-?\d+(?:\.\d+)?%?", attr_value.strip()):
                    continue
            clean_attrs[attr_name] = attr_value
        node.attrs = clean_attrs

        if tag_name == "a" and node.get("target") == "_blank":
            node["rel"] = "noopener noreferrer"
        if tag_name == "img" and not node.get("src"):
            alt = str(node.get("alt") or node.get("title") or "image").strip()
            replacement = soup.new_tag("span")
            replacement["style"] = (
                "display: block; color: #64748b; font-style: italic; "
                "border: 1px dashed #cbd5e1; padding: 8px"
            )
            replacement.string = f"[Image: {alt[:300]}]"
            node.replace_with(replacement)

    return str(soup)


def _normalize_rich_paste_print_layout(content_html):
    """Flatten deeply nested screen layouts that can make paged layout non-terminating."""
    from bs4 import BeautifulSoup

    soup = BeautifulSoup(str(content_html or ""), "html.parser")
    styled_nodes = list(soup.find_all(style=True))
    complex_layout_count = 0
    for node in styled_nodes:
        style = str(node.get("style") or "")
        if re.search(r"(?:^|;)\s*display\s*:\s*(?:inline-)?(?:flex|grid)\b", style, re.IGNORECASE):
            complex_layout_count += 1
    screen_layout_count = 0
    for node in styled_nodes:
        if str(node.name or "").lower() not in {"article", "div", "main", "section"}:
            continue
        style = str(node.get("style") or "")
        padding_values = re.findall(
            r"(?:^|;)\s*padding(?:-left|-right|-inline|-inline-start|-inline-end)?\s*:\s*([^;]+)",
            style,
            flags=re.IGNORECASE,
        )
        large_side_padding = any(
            abs(float(pixel_value)) >= 96
            for padding_value in padding_values
            for pixel_value in re.findall(r"(-?\d+(?:\.\d+)?)px", padding_value, flags=re.IGNORECASE)
        )
        oversized_width = any(
            abs(float(pixel_value)) > 720
            for pixel_value in re.findall(
                r"(?:^|;)\s*(?:width|min-width)\s*:\s*(-?\d+(?:\.\d+)?)px",
                style,
                flags=re.IGNORECASE,
            )
        )
        if large_side_padding or oversized_width:
            screen_layout_count += 1
    if len(soup.find_all(True)) <= 500 and complex_layout_count <= 24 and screen_layout_count == 0:
        return str(soup)

    layout_props = {
        "align-items", "align-self", "column-gap", "flex", "flex-basis", "flex-direction",
        "flex-grow", "flex-shrink", "flex-wrap", "gap", "grid", "grid-auto-columns",
        "grid-auto-flow", "grid-auto-rows", "grid-column", "grid-column-end",
        "grid-column-start", "grid-row", "grid-row-end", "grid-row-start", "grid-template",
        "grid-template-areas", "grid-template-columns", "grid-template-rows", "justify-content",
        "justify-items", "justify-self", "order", "row-gap",
    }
    block_width_tags = {"article", "div", "main", "section"}
    side_padding_props = {
        "padding", "padding-left", "padding-right", "padding-inline", "padding-inline-start", "padding-inline-end",
    }
    for node in styled_nodes:
        declarations = []
        for declaration in str(node.get("style") or "").split(";"):
            if ":" not in declaration:
                continue
            prop, value = declaration.split(":", 1)
            prop = prop.strip().lower()
            value = value.strip()
            if prop in layout_props:
                continue
            if prop in {"height", "max-height", "min-height", "overflow", "overflow-x", "overflow-y"}:
                continue
            if prop in {"width", "min-width"} and str(node.name or "").lower() in block_width_tags:
                continue
            if prop in side_padding_props and str(node.name or "").lower() in block_width_tags:
                pixel_values = [
                    abs(float(match))
                    for match in re.findall(r"(-?\d+(?:\.\d+)?)px", value, flags=re.IGNORECASE)
                ]
                if any(pixel_value >= 96 for pixel_value in pixel_values):
                    value = "0px"
            if prop == "display":
                display_value = value.lower()
                if display_value in {"flex", "grid"}:
                    value = "block"
                elif display_value in {"inline-flex", "inline-grid"}:
                    value = "inline-block"
            declarations.append(f"{prop}: {value}")
        if declarations:
            node["style"] = "; ".join(declarations)
        elif node.has_attr("style"):
            del node["style"]
    return str(soup)


def _parse_rich_paste_css_color(value):
    text_value = str(value or "").strip().lower()
    if not text_value:
        return None
    candidates = re.findall(
        r"(?:rgba?|hsla?|oklab|oklch)\([^)]*\)|#[0-9a-f]{3,8}\b|\b(?:black|white|transparent)\b",
        text_value,
        flags=re.IGNORECASE,
    )
    if not candidates:
        return None
    token = candidates[-1].strip().lower()
    named = {
        "black": (0.0, 0.0, 0.0, 1.0),
        "white": (255.0, 255.0, 255.0, 1.0),
        "transparent": (0.0, 0.0, 0.0, 0.0),
    }
    if token in named:
        return named[token]
    if token.startswith("#"):
        digits = token[1:]
        if len(digits) in {3, 4}:
            digits = "".join(char * 2 for char in digits)
        if len(digits) not in {6, 8}:
            return None
        try:
            red = int(digits[0:2], 16)
            green = int(digits[2:4], 16)
            blue = int(digits[4:6], 16)
            alpha = int(digits[6:8], 16) / 255 if len(digits) == 8 else 1.0
            return float(red), float(green), float(blue), float(alpha)
        except ValueError:
            return None

    function_name, function_body = token.split("(", 1)
    function_body = function_body.rsplit(")", 1)[0].strip()
    alpha = 1.0
    if "/" in function_body:
        function_body, raw_alpha = function_body.rsplit("/", 1)
        raw_alpha = raw_alpha.strip()
        try:
            alpha = float(raw_alpha[:-1]) / 100 if raw_alpha.endswith("%") else float(raw_alpha)
        except ValueError:
            return None
    alpha = max(0.0, min(1.0, alpha))

    def parse_rgb_channel(raw_channel):
        raw_channel = raw_channel.strip()
        if raw_channel.endswith("%"):
            return max(0.0, min(255.0, float(raw_channel[:-1]) * 2.55))
        return max(0.0, min(255.0, float(raw_channel)))

    if function_name in {"rgb", "rgba"}:
        parts = [part for part in re.split(r"\s*,\s*|\s+", function_body.strip()) if part]
        if function_name == "rgba" and len(parts) == 4 and "/" not in token:
            raw_alpha = parts.pop()
            try:
                alpha = float(raw_alpha[:-1]) / 100 if raw_alpha.endswith("%") else float(raw_alpha)
            except ValueError:
                return None
        if len(parts) != 3:
            return None
        try:
            red, green, blue = (parse_rgb_channel(part) for part in parts)
            return red, green, blue, max(0.0, min(1.0, alpha))
        except ValueError:
            return None

    if function_name in {"hsl", "hsla"}:
        parts = [part for part in re.split(r"\s*,\s*|\s+", function_body.strip()) if part]
        if function_name == "hsla" and len(parts) == 4 and "/" not in token:
            raw_alpha = parts.pop()
            try:
                alpha = float(raw_alpha[:-1]) / 100 if raw_alpha.endswith("%") else float(raw_alpha)
            except ValueError:
                return None
        if len(parts) != 3:
            return None
        try:
            hue = float(re.sub(r"(?:deg|rad|turn)$", "", parts[0]))
            if parts[0].endswith("rad"):
                hue = math.degrees(hue)
            elif parts[0].endswith("turn"):
                hue *= 360
            saturation = max(0.0, min(1.0, float(parts[1].rstrip("%")) / 100))
            lightness = max(0.0, min(1.0, float(parts[2].rstrip("%")) / 100))
        except ValueError:
            return None
        chroma = (1 - abs((2 * lightness) - 1)) * saturation
        segment = (hue % 360) / 60
        intermediate = chroma * (1 - abs((segment % 2) - 1))
        if segment < 1:
            red1, green1, blue1 = chroma, intermediate, 0
        elif segment < 2:
            red1, green1, blue1 = intermediate, chroma, 0
        elif segment < 3:
            red1, green1, blue1 = 0, chroma, intermediate
        elif segment < 4:
            red1, green1, blue1 = 0, intermediate, chroma
        elif segment < 5:
            red1, green1, blue1 = intermediate, 0, chroma
        else:
            red1, green1, blue1 = chroma, 0, intermediate
        match = lightness - (chroma / 2)
        return (
            (red1 + match) * 255,
            (green1 + match) * 255,
            (blue1 + match) * 255,
            max(0.0, min(1.0, alpha)),
        )

    if function_name in {"oklab", "oklch"}:
        parts = [part for part in re.split(r"\s+", function_body.strip()) if part]
        if len(parts) != 3:
            return None
        try:
            lightness = float(parts[0].rstrip("%"))
            if parts[0].endswith("%"):
                lightness /= 100
            if function_name == "oklch":
                chroma = float(parts[1])
                hue_text = parts[2]
                hue = float(re.sub(r"(?:deg|rad|turn)$", "", hue_text))
                if hue_text.endswith("rad"):
                    hue = math.degrees(hue)
                elif hue_text.endswith("turn"):
                    hue *= 360
                lab_a = chroma * math.cos(math.radians(hue))
                lab_b = chroma * math.sin(math.radians(hue))
            else:
                lab_a = float(parts[1])
                lab_b = float(parts[2])
        except ValueError:
            return None
        l_value = (lightness + (0.3963377774 * lab_a) + (0.2158037573 * lab_b)) ** 3
        m_value = (lightness - (0.1055613458 * lab_a) - (0.0638541728 * lab_b)) ** 3
        s_value = (lightness - (0.0894841775 * lab_a) - (1.291485548 * lab_b)) ** 3
        red_linear = (4.0767416621 * l_value) - (3.3077115913 * m_value) + (0.2309699292 * s_value)
        green_linear = (-1.2684380046 * l_value) + (2.6097574011 * m_value) - (0.3413193965 * s_value)
        blue_linear = (-0.0041960863 * l_value) - (0.7034186147 * m_value) + (1.707614701 * s_value)

        def linear_to_srgb(channel):
            converted = 12.92 * channel if channel <= 0.0031308 else (1.055 * (channel ** (1 / 2.4))) - 0.055
            return max(0.0, min(255.0, converted * 255))

        return (
            linear_to_srgb(red_linear),
            linear_to_srgb(green_linear),
            linear_to_srgb(blue_linear),
            max(0.0, min(1.0, alpha)),
        )
    return None


def _rich_paste_color_luminance(color):
    if not color:
        return 0.0

    def channel(value):
        normalized = max(0.0, min(255.0, float(value))) / 255
        return normalized / 12.92 if normalized <= 0.04045 else ((normalized + 0.055) / 1.055) ** 2.4

    return (0.2126 * channel(color[0])) + (0.7152 * channel(color[1])) + (0.0722 * channel(color[2]))


def _rich_paste_color_contrast(first, second):
    first_luminance = _rich_paste_color_luminance(first)
    second_luminance = _rich_paste_color_luminance(second)
    return (max(first_luminance, second_luminance) + 0.05) / (
        min(first_luminance, second_luminance) + 0.05
    )


def _rich_paste_color_css(color):
    return f"rgb({round(color[0])}, {round(color[1])}, {round(color[2])})"


def _resolve_rich_paste_theme(content_html, requested_theme=None):
    from bs4 import BeautifulSoup, NavigableString

    requested_background = None
    requested_foreground = None
    if isinstance(requested_theme, dict):
        requested_background = _parse_rich_paste_css_color(requested_theme.get("background"))
        requested_foreground = _parse_rich_paste_css_color(requested_theme.get("foreground"))
        if requested_background and requested_background[3] < 0.9:
            requested_background = None
        if requested_foreground and requested_foreground[3] < 0.5:
            requested_foreground = None

    soup = BeautifulSoup(str(content_html or ""), "html.parser")
    background_candidates = []
    foreground_weights = {}
    inherited_foreground_candidates = []
    foreground_total = 0
    for node in soup.find_all(style=True):
        declarations = {}
        for declaration in str(node.get("style") or "").split(";"):
            if ":" not in declaration:
                continue
            prop, value = declaration.split(":", 1)
            declarations[prop.strip().lower()] = value.strip()

        background_value = declarations.get("background-color") or declarations.get("background")
        background = _parse_rich_paste_css_color(background_value)
        if background and background[3] >= 0.72:
            subtree_weight = len(re.sub(r"\s+", " ", node.get_text(" ", strip=True)))
            background_candidates.append((max(1, subtree_weight), background))

        foreground = _parse_rich_paste_css_color(declarations.get("color"))
        if foreground and foreground[3] >= 0.5:
            subtree_weight = len(re.sub(r"\s+", " ", node.get_text(" ", strip=True)))
            inherited_foreground_candidates.append((max(1, subtree_weight), foreground))
            direct_text = " ".join(
                str(child)
                for child in node.children
                if isinstance(child, NavigableString)
            )
            direct_weight = len(re.sub(r"\s+", " ", direct_text).strip())
            if direct_weight:
                key = tuple(round(part, 3) for part in foreground[:3])
                current = foreground_weights.get(key, {"weight": 0, "color": foreground})
                current["weight"] += direct_weight
                foreground_weights[key] = current
                foreground_total += direct_weight

    foreground_entries = sorted(
        foreground_weights.values(),
        key=lambda entry: entry["weight"],
        reverse=True,
    )
    inherited_foreground_candidates.sort(key=lambda candidate: candidate[0], reverse=True)
    dominant_foreground = (
        foreground_entries[0]["color"]
        if foreground_entries
        else (inherited_foreground_candidates[0][1] if inherited_foreground_candidates else None)
    )
    if foreground_entries:
        light_foreground_weight = sum(
            entry["weight"]
            for entry in foreground_entries
            if _rich_paste_color_luminance(entry["color"]) >= 0.6
        )
    elif inherited_foreground_candidates:
        foreground_total = inherited_foreground_candidates[0][0]
        light_foreground_weight = (
            foreground_total
            if _rich_paste_color_luminance(inherited_foreground_candidates[0][1]) >= 0.6
            else 0
        )
    else:
        light_foreground_weight = 0
    background_candidates.sort(key=lambda candidate: candidate[0], reverse=True)

    background = requested_background
    if not background and background_candidates:
        background = background_candidates[0][1]
    if not background:
        background = (
            (11.0, 11.0, 12.0, 1.0)
            if foreground_total and light_foreground_weight / foreground_total >= 0.55
            else (255.0, 255.0, 255.0, 1.0)
        )
    foreground = requested_foreground
    if not foreground:
        neutral_candidates = [
            (entry["weight"], entry["color"])
            for entry in foreground_entries
            if max(entry["color"][:3]) - min(entry["color"][:3]) <= 64
            and _rich_paste_color_contrast(background, entry["color"]) >= 3
        ]
        neutral_candidates.extend(
            (weight, color)
            for weight, color in inherited_foreground_candidates
            if max(color[:3]) - min(color[:3]) <= 64
            and _rich_paste_color_contrast(background, color) >= 3
        )
        neutral_candidates.sort(key=lambda candidate: candidate[0], reverse=True)
        foreground = neutral_candidates[0][1] if neutral_candidates else dominant_foreground
    dark = _rich_paste_color_luminance(background) < 0.32
    if not foreground or _rich_paste_color_contrast(background, foreground) < 3:
        foreground = (244.0, 244.0, 245.0, 1.0) if dark else (17.0, 24.0, 39.0, 1.0)

    return {
        "mode": "dark" if dark else "light",
        "background": _rich_paste_color_css(background),
        "foreground": _rich_paste_color_css(foreground),
        "muted": "rgb(161, 161, 170)" if dark else "rgb(100, 116, 139)",
        "border": "rgb(63, 63, 70)" if dark else "rgb(203, 213, 225)",
        "surface": "rgb(33, 33, 33)" if dark else "rgb(248, 250, 252)",
        "quote": "rgb(39, 39, 42)" if dark else "rgb(255, 249, 235)",
        "link": "rgb(125, 211, 252)" if dark else "rgb(15, 118, 110)",
    }


def _build_rich_paste_pdf_bytes_weasyprint(title, content_html, created_at=None, theme=None):
    safe_title = html.escape(str(title or "Clipboard Export").strip() or "Clipboard Export")
    safe_created_at = html.escape(
        str(created_at or datetime.utcnow().strftime("%Y-%m-%d %H:%M:%S")).strip()
    )
    resolved_theme = _resolve_rich_paste_theme(content_html, requested_theme=theme)
    theme_background = resolved_theme["background"]
    theme_foreground = resolved_theme["foreground"]
    theme_muted = resolved_theme["muted"]
    theme_border = resolved_theme["border"]
    theme_surface = resolved_theme["surface"]
    theme_quote = resolved_theme["quote"]
    theme_link = resolved_theme["link"]
    theme_mode = resolved_theme["mode"]
    document_html = f"""<!doctype html>
<html lang="ja">
<head>
<meta charset="utf-8">
<title>{safe_title}</title>
<style>
@page {{
  size: A4;
  margin: 16mm 16mm 18mm;
  background: {theme_background};
  @bottom-right {{
    content: "Page " counter(page) " / " counter(pages);
    color: {theme_muted};
    font-size: 8.5pt;
  }}
}}
html {{ color-scheme: {theme_mode}; background: {theme_background}; }}
body {{
  margin: 0;
  background: {theme_background};
  color: {theme_foreground};
  font-family: "IPAPGothic", "IPAGothic", "Droid Sans Fallback", sans-serif;
  font-size: 10.5pt;
  line-height: 1.55;
  overflow-wrap: anywhere;
  word-break: normal;
}}
*, *::before, *::after {{ box-sizing: border-box; }}
.document-title {{
  margin: 0 0 3mm;
  padding: 0 0 3mm;
  border-bottom: 1.5pt solid {theme_border};
  color: {theme_foreground};
  font-size: 18pt;
  line-height: 1.25;
}}
.document-meta {{ margin: 0 0 7mm; color: {theme_muted}; font-size: 8.5pt; }}
.rich-content {{ color: {theme_foreground}; }}
.rich-content h1, .rich-content h2, .rich-content h3,
.rich-content h4, .rich-content h5, .rich-content h6 {{
  line-height: 1.3;
  break-after: avoid;
}}
.rich-content p {{ margin: 0 0 0.85em; }}
.rich-content img {{ display: block; max-width: 100%; height: auto; margin: 0.9em auto; }}
.rich-content table {{
  max-width: 100%;
  margin: 1em 0;
  border-collapse: collapse;
  break-inside: auto;
}}
.rich-content thead {{ display: table-header-group; }}
.rich-content tr {{ break-inside: avoid; }}
.rich-content th, .rich-content td {{
  border: 0.6pt solid {theme_border};
  padding: 5pt 6pt;
  vertical-align: top;
  overflow-wrap: anywhere;
}}
.rich-content th {{ background: {theme_surface}; color: {theme_foreground}; font-weight: 700; }}
.rich-content pre {{
  max-width: 100%;
  margin: 1em 0;
  padding: 9pt;
  border: 0.6pt solid {theme_border};
  border-radius: 3pt;
  background: {theme_surface};
  color: {theme_foreground};
  font-family: "WenQuanYi Zen Hei Mono", "Droid Sans Fallback", monospace;
  font-size: 8.8pt;
  line-height: 1.4;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}}
.rich-content code, .rich-content kbd, .rich-content samp {{
  padding: 0.08em 0.28em;
  border-radius: 2pt;
  background: {theme_surface};
  color: {theme_foreground};
  font-family: "WenQuanYi Zen Hei Mono", "Droid Sans Fallback", monospace;
}}
.rich-content pre code {{ padding: 0; background: transparent; }}
.rich-content blockquote {{
  margin: 1em 0;
  padding: 8pt 10pt;
  border-left: 3pt solid #f59e0b;
  background: {theme_quote};
  color: {theme_foreground};
}}
.rich-content a {{ color: {theme_link}; text-decoration: underline; }}
.rich-content hr {{ margin: 1em 0; border: 0; border-top: 0.7pt solid {theme_border}; }}
.rich-content figure {{ max-width: 100%; margin: 1em 0; }}
.rich-content figcaption {{ color: {theme_muted}; font-size: 9pt; text-align: center; }}
</style>
</head>
<body>
<h1 class="document-title">{safe_title}</h1>
<p class="document-meta">Created at: {safe_created_at}</p>
<main class="rich-content">{content_html}</main>
</body>
</html>"""
    weasyprint_bin = os.path.join(os.path.dirname(sys.executable), "weasyprint")
    if not os.path.isfile(weasyprint_bin):
        raise RuntimeError("weasyprint_command_not_found")
    completed = subprocess.run(
        [
            weasyprint_bin,
            "--quiet",
            "--presentational-hints",
            "--optimize-images",
            "--jpeg-quality", "92",
            "--dpi", "180",
            "--timeout", "3",
            "--allowed-protocols", "data",
            "--no-http-redirects",
            "-", "-",
        ],
        input=document_html.encode("utf-8"),
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        timeout=75,
        check=False,
    )
    if completed.returncode != 0:
        stderr = completed.stderr.decode("utf-8", errors="replace").strip()
        raise RuntimeError(f"weasyprint_failed: {stderr[-1000:]}")
    pdf_bytes = completed.stdout
    if not isinstance(pdf_bytes, bytes) or not pdf_bytes.startswith(b"%PDF"):
        raise RuntimeError("weasyprint_invalid_pdf")
    return pdf_bytes


def _build_rich_paste_pdf_bytes(title, content_html, created_at=None, theme=None):
    safe_html = _sanitize_rich_paste_html(content_html)
    resolved_theme = _resolve_rich_paste_theme(safe_html, requested_theme=theme)
    print_html = _normalize_rich_paste_print_layout(safe_html)
    try:
        return _build_rich_paste_pdf_bytes_weasyprint(
            title,
            print_html,
            created_at=created_at,
            theme=resolved_theme,
        )
    except Exception:
        logger.exception("WeasyPrint rich paste rendering failed; using ReportLab fallback")
        return _build_rich_paste_pdf_bytes_reportlab(
            title,
            print_html,
            created_at=created_at,
        )


@app.route('/api/rich-paste/pdf', methods=['POST'])
@login_required
def rich_paste_pdf():
    if not getattr(current_user, "is_admin", False):
        return jsonify({'error': '403'}), 403
    if request.content_length and request.content_length > 2 * 1024 * 1024:
        return jsonify({'error': 'payload_too_large'}), 413
    
    log_force(
        "[DEBUG] rich_paste_pdf start "
        f"content_type={request.content_type} "
        f"content_length={request.content_length} "
        f"is_json={request.is_json}"
    )

    d = None
    if request.is_json:
        try:
            d = request.get_json(silent=True)
            if d:
                log_force(f"[DEBUG] rich_paste_pdf get_json success keys={list(d.keys())}")
        except Exception as e:
            log_force(f"[DEBUG] rich_paste_pdf get_json exception: {e}")

    if not isinstance(d, dict) or not d:
        if request.form:
            d = request.form.to_dict(flat=True)
            log_force("[DEBUG] rich_paste_pdf used request.form")
        else:
            try:
                # Crucial: Use cache=True to allow multiple reads if needed
                raw_body = request.get_data(cache=True, as_text=True)
                if raw_body and raw_body.strip():
                    log_force(f"[DEBUG] rich_paste_pdf raw_body_len={len(raw_body)}")
                    try:
                        d = json.loads(raw_body)
                        log_force("[DEBUG] rich_paste_pdf json.loads(raw_body) success")
                    except Exception:
                        # Fallback for some clients that might send raw HTML as body
                        if "<html>" in raw_body.lower() or "<div" in raw_body.lower():
                            d = {"html": raw_body}
                            log_force("[DEBUG] rich_paste_pdf treated raw_body as html")
            except Exception as e:
                log_force(f"[DEBUG] rich_paste_pdf get_data exception: {e}")
                d = {}

    if not isinstance(d, dict):
        d = {}

    content_html = str(d.get('html') or '').strip()
    title = (str(d.get('title') or 'Clipboard Export').strip() or 'Clipboard Export')[:200]
    created_at = str(d.get('created_at') or datetime.utcnow().strftime('%Y-%m-%d %H:%M:%S')).strip()[:100]
    requested_theme = d.get('theme') if isinstance(d.get('theme'), dict) else None

    log_force(
        "[DEBUG] rich_paste_pdf payload info "
        f"title_len={len(title)} "
        f"html_len={len(content_html)} "
        f"keys={sorted(list(d.keys())) if d else 'None'}"
    )

    if not content_html:
        log_force("[DEBUG] rich_paste_pdf error: missing_html")
        return jsonify({'error': 'missing_html'}), 400
    if len(content_html) > 2 * 1024 * 1024:
        return jsonify({'error': 'payload_too_large'}), 413

    log_force(f"[DEBUG] rich_paste_pdf starting _build_rich_paste_pdf_bytes for title={title}")
    try:
        pdf_bytes = _build_rich_paste_pdf_bytes(
            title,
            content_html,
            created_at=created_at,
            theme=requested_theme,
        )
        log_force(f"[DEBUG] rich_paste_pdf _build_rich_paste_pdf_bytes finished, size={len(pdf_bytes)}")
    except Exception as e:
        logger.exception("Server-side rich paste PDF generation failed")
        log_force(f"[DEBUG] rich_paste_pdf generation exception: {type(e).__name__}: {e}")
        return jsonify({'error': 'pdf_generation_failed', 'message': str(e)}), 500

    try:
        filename = _rich_paste_pdf_filename(title)
        resp = send_file(
            BytesIO(pdf_bytes),
            mimetype='application/pdf',
            as_attachment=True,
            download_name=filename
        )
        resp.headers['X-Rich-Paste-Filename'] = filename
        resp.headers['Cache-Control'] = 'no-store'
        log_force(f"[DEBUG] rich_paste_pdf success filename={filename} bytes={len(pdf_bytes)}")
        return resp
    except Exception as e:
        logger.exception("Server-side rich paste PDF response failed")
        log_force(f"[DEBUG] rich_paste_pdf response exception: {e}")
        return jsonify({'error': 'response_failed', 'message': str(e)}), 500


@app.route('/c/<thread_id>/pdf')
@login_required
def export_thread_pdf(thread_id):
    t = resolve_thread_for_user(thread_id, current_user.id)
    if not t:
        return jsonify({'error': '403'}), 403
    leaf_id = request.args.get('leaf_id', type=int)
    payload = _build_thread_pdf_payload(t, leaf_id=leaf_id)
    return jsonify(payload)

@app.route('/api/encryption_scan', methods=['GET'])
@login_required
def encryption_scan():
    thread_id = request.args.get('thread_id')
    q = Message.query.join(Thread, Message.thread_id == Thread.id).filter(Thread.user_id == current_user.id)
    target_thread = None
    if thread_id:
        target_thread = resolve_thread_for_user(thread_id, current_user.id)
        if not target_thread:
            return jsonify({'error': 'Invalid thread'}), 403
        q = q.filter(Message.thread_id == target_thread.id)
    try:
        total = q.count()
        encrypted = q.filter(Message.is_encrypted.is_(True)).count()
        unencrypted = q.filter((Message.is_encrypted.is_(False)) | (Message.is_encrypted.is_(None))).order_by(Message.timestamp.desc()).limit(100).all()
        unenc_list = []
        for m in unencrypted:
            unenc_list.append({
                "id": m.id,
                "thread_id": m.thread.public_id if m.thread else None,
                "role": m.role,
                "timestamp": m.timestamp.isoformat() if m.timestamp else None
            })
        return jsonify({
            "thread_id": target_thread.public_id if target_thread else None,
            "total": total,
            "encrypted": encrypted,
            "unencrypted": total - encrypted,
            "samples": unenc_list
        })
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@app.route('/api/admin/threads', methods=['GET'])
@login_required
def admin_threads_list():
    """List the current admin account's own threads with encryption status.

    Username selection was removed: only the logged-in admin's chats are in scope.
    """
    if not getattr(current_user, "is_admin", False):
        return jsonify({'error': '403'}), 403
    q = (request.args.get('q') or '').strip()
    query = Thread.query.filter_by(user_id=current_user.id)
    if q:
        query = query.filter(Thread.title.contains(q))
    threads = query.order_by(Thread.updated_at.desc()).limit(500).all()
    res = []
    for t in threads:
        msgs = Message.query.filter_by(thread_id=t.id).all()
        total = len(msgs)
        enc = sum(1 for m in msgs if m.is_encrypted)
        res.append({
            'thread_id': t.public_id or t.id,
            'title': t.title,
            'updated_at': t.updated_at.isoformat() if t.updated_at else None,
            'message_count': total,
            'encrypted_count': enc,
            'encrypted': enc > 0,
        })
    return jsonify({
        'user': {
            'username': current_user.username,
            'enable_e2ee': bool(getattr(current_user, 'enable_e2ee', False)),
        },
        'threads': res
    })

@app.route('/api/admin/threads/<thread_id>/encryption', methods=['POST'])
@login_required
def admin_toggle_thread_encryption(thread_id):
    """Decrypt or re-encrypt a single thread owned by the current admin account."""
    if not getattr(current_user, "is_admin", False):
        return jsonify({'error': '403'}), 403
    data = request.get_json(silent=True) or {}
    enable = bool(data.get('enable'))
    # Scope to the admin's own threads only (other users' chats are never targeted).
    t = resolve_thread_for_user(thread_id, current_user.id)
    if not t:
        return jsonify({'error': 'thread_not_found'}), 404
    changed = 0
    for m in t.messages:
        if enable and not m.is_encrypted:
            if m.content:
                m.content = encrypt_val(m.content)
            if m.thought_data:
                m.thought_data = encrypt_val(m.thought_data)
            m.is_encrypted = True
            changed += 1
        elif not enable and m.is_encrypted:
            if m.content:
                m.content = decrypt_val(m.content)
            if m.thought_data:
                m.thought_data = decrypt_val(m.thought_data)
            m.is_encrypted = False
            changed += 1
    safe_db_commit()
    return jsonify({
        'status': 'ok',
        'thread_id': t.public_id or t.id,
        'enable': enable,
        'changed': changed,
        'total': len(t.messages)
    })

@app.route('/api/threads/<thread_id>/settings', methods=['GET', 'PUT'])
@login_required
def update_thread_settings(thread_id):
    log_force(f"DEBUG: update_thread_settings started for {thread_id}, method={request.method}")
    t = resolve_thread_for_user(thread_id, current_user.id)
    if not t:
        log_force(f"DEBUG: thread not found for {thread_id}")
        return jsonify({'error': '403'}), 403
    if request.method == 'GET':
        log_force(f"DEBUG: update_thread_settings GET returning data for {thread_id}")
        return jsonify({
            'custom_instruction': t.custom_instruction,
            'include_global_instruction': t.include_global_instruction if t.include_global_instruction is not None else True,
            'is_temporary': bool(getattr(t, "is_temporary", False)),
            **_get_temp_chat_runtime_meta(t, user=current_user)
        })
    d = request.json or {}
    log_force(f"DEBUG: update_thread_settings received keys: {sorted(d.keys())}")
    if 'custom_instruction' in d:
        custom_instruction = str(d.get('custom_instruction') or '')
        if len(custom_instruction) > 100_000:
            return jsonify({'error': 'payload_too_large'}), 413
        t.custom_instruction = custom_instruction
    if 'include_global_instruction' in d:
        t.include_global_instruction = bool(d['include_global_instruction'])
    if 'is_temporary' in d:
        requested_temp = _coerce_bool_or_none(d.get('is_temporary'))
        t.is_temporary = bool(requested_temp)
    
    t.updated_at = datetime.utcnow()
    db.session.add(t)
    log_force(f"DEBUG: calling safe_db_commit")
    safe_db_commit()
    log_force(f"DEBUG: safe_db_commit finished")
    if bool(getattr(t, "is_temporary", False)):
        _mark_temp_chat_presence(
            t,
            current_user.id,
            timeout_seconds=_get_user_temp_chat_timeout_seconds(current_user)
        )
    else:
        _clear_temp_chat_tracking_for_thread(t)
    log_force(f"DEBUG: update_thread_settings returning ok")
    temp_meta = _get_temp_chat_runtime_meta(t, user=current_user)
    return jsonify({
        'status': 'ok',
        'is_temporary': bool(getattr(t, "is_temporary", False)),
        'timeout_seconds': temp_meta.get('timeout_seconds'),
        'temp_chat_expires_at': temp_meta.get('temp_chat_expires_at'),
        'temp_chat_remaining_seconds': temp_meta.get('temp_chat_remaining_seconds')
    })

